# Reparación puntual de bodega CENTRAL (fix stock 0 por importación Woo)
# ════════════════════════════════════════════════════════════════════════════
@app.route("/admin/lusync/stock/reparar-central")
def reparar_central_stock():
    """Crea/corrige la bodega CENTRAL de un SKU y re-sincroniza a los canales.

    Uso:
      /admin/lusync/stock/reparar-central?sku=MICO001&cantidad=35
      (opcional &token=... si no hay sesión)

    Sirve para recuperar productos que quedaron en 0 porque se importaron de
    Woo sin inicializar su bodega CENTRAL.
    """
    import os
    bypass_token = os.environ.get(
        "ADMIN_BYPASS_TOKEN",
        "lcTDX2fjcH3hiZFvv8apEwPd-eiCIqFdkKqJIVy1bVw",
    )
    token = request.args.get("token", "")
    if not (session.get("logged") or session.get("is_lusync_admin")
            or (token and token == bypass_token)):
        return redirect("/admin/lusync/login")

    sku = (request.args.get("sku", "") or "").strip()
    cantidad_str = (request.args.get("cantidad", "") or "").strip()
    solo_ver = (request.args.get("ver", "") or "").lower() in ("si", "1", "true")

    from inventario import (set_stock_bodega, get_stock_bodega,
                            stock_por_bodega, cargar_productos,
                            obtener_publicaciones_canal)

    # ── Modo diagnóstico: muestra el estado sin tocar nada ──
    if solo_ver:
        if not sku:
            return jsonify({"error": "Falta ?sku=... para diagnóstico"}), 400
        try:
            bodegas = stock_por_bodega(sku) or {}
        except Exception as e:
            bodegas = {"error": str(e)}
        # stock total en productos
        stock_total = None
        try:
            for p in cargar_productos():
                if p.get("sku") == sku:
                    stock_total = p.get("stock")
                    break
        except Exception:
            pass
        # publicaciones mapeadas por canal
        mapeos = {}
        for canal in ("woo", "walmart", "paris", "mercadolibre", "falabella", "ripley"):
            try:
                pubs = obtener_publicaciones_canal(sku, canal) or []
                mapeos[canal] = [{"sku_canal": p.get("sku_canal"),
                                  "item_id": p.get("item_id_canal")} for p in pubs]
            except Exception as e:
                mapeos[canal] = f"error: {e}"
        return jsonify({
            "modo": "diagnostico (no se modificó nada)",
            "sku": sku,
            "stock_total_productos": stock_total,
            "stock_por_bodega": bodegas,
            "central": bodegas.get("CENTRAL", "(sin bodega CENTRAL)"),
            "publicaciones_por_canal": mapeos,
        })

    if not sku or not cantidad_str:
        return jsonify({"error": "Faltan parámetros. Uso: ?sku=MICO001&cantidad=35  "
                                 "(o ?sku=MICO001&ver=si para solo diagnosticar)"}), 400
    try:
        cantidad = int(cantidad_str)
    except ValueError:
        return jsonify({"error": "cantidad debe ser un número entero"}), 400

    # Estado antes
    try:
        antes = stock_por_bodega(sku) or {}
    except Exception:
        antes = {}

    # 1. Fijar la bodega CENTRAL con el stock físico real (esto recalcula
    #    productos.stock automáticamente vía _recalcular_stock_total).
    set_stock_bodega(sku, "CENTRAL", cantidad)

    # 1b. Verificar qué stock va a calcular la sincronización (diagnóstico).
    #     Replica la query de sincronizar_stock_marketplaces para mostrarlo.
    stock_calculado = None
    diag_bodegas = {}
    try:
        from inventario import get_conn
        _cn = get_conn(); _cur = _cn.cursor()
        _cur.execute("""
            SELECT sb.bodega_codigo, sb.cantidad, b.tipo
            FROM stock_bodega sb
            LEFT JOIN bodegas b ON b.codigo = sb.bodega_codigo
            WHERE sb.sku = %s
        """, (sku,))
        for cod, cant, tipo in _cur.fetchall():
            diag_bodegas[cod] = {"cantidad": cant, "tipo": tipo}
        _cur.execute("""
            SELECT COALESCE(SUM(sb.cantidad), 0)
            FROM stock_bodega sb
            LEFT JOIN bodegas b ON b.codigo = sb.bodega_codigo
            WHERE sb.sku = %s
              AND (b.tipo = 'propia' OR b.tipo IS NULL OR sb.bodega_codigo = 'CENTRAL')
        """, (sku,))
        stock_calculado = int((_cur.fetchone() or [0])[0] or 0)
        _cur.close(); _cn.close()
    except Exception as e:
        diag_bodegas = {"error": str(e)}

    # 2. Re-sincronizar a los marketplaces (lee CENTRAL fresco y publica).
    #    Capturamos el detalle por canal para ver exactamente qué se publicó.
    sync_log = []
    detalle_publicacion = {}
    try:
        ret = sincronizar_stock_marketplaces(sku, contexto="reparar_central")
        sync_log.append("Sincronización a marketplaces disparada")
        if isinstance(ret, dict):
            detalle_publicacion = ret
    except Exception as e:
        sync_log.append(f"Error al sincronizar: {e}")

    # Estado después
    central_despues = None
    try:
        central_despues = get_stock_bodega(sku, "CENTRAL")
    except Exception:
        pass

    return jsonify({
        "ok": True,
        "sku": sku,
        "central_antes": antes.get("CENTRAL", "(no existía)"),
        "central_despues": central_despues if central_despues is not None else cantidad,
        "stock_que_se_publico": stock_calculado,
        "_diagnostico_bodegas": diag_bodegas,
        "_detalle_por_canal": detalle_publicacion,
        "cantidad_fijada": cantidad,
        "sincronizacion": sync_log,
        "nota": "El stock CENTRAL es tu stock físico propio. Se publicó a los "
                "canales seller (Falabella, Walmart, etc.). Verificá en cada "
                "marketplace en 1-2 minutos.",
    })

# ════════════════════════════════════════════════════════════════════════════
# SYNC CENTRALIZADO MULTI-MARKETPLACE
# ════════════════════════════════════════════════════════════════════════════
# Helper único que se llama AUTOMÁTICAMENTE en TODOS los lugares donde cambia
# stock (entrada manual, salida manual, sync de órdenes, devoluciones, etc.)
#
# Sincroniza con los 6 marketplaces conectados de forma RESILIENTE:
#  - Si un canal falla, los demás siguen ejecutándose
#  - Devuelve resumen detallado de qué funcionó y qué no
#  - No bloquea la operación principal aunque algún canal esté caído
#
# Uso típico:
#   sincronizar_stock_marketplaces(sku, nuevo_stock)
# ════════════════════════════════════════════════════════════════════════════

def _asegurar_fecha_compra(canal, orden_id, fecha_compra, sku=None):
    """Asegura que el último movimiento de salida de esta orden tenga fecha_compra_marketplace.
    Se llama después de descontar_venta porque bodegas_logic.descontar_venta puede no
    escribir esa columna. Idempotente."""
    if not fecha_compra or not orden_id:
        return
    try:
        from inventario import get_conn as _gc, TZ_CHILE
        fc = fecha_compra
        if hasattr(fc, 'tzinfo') and fc.tzinfo:
            fc = fc.astimezone(TZ_CHILE).replace(tzinfo=None)
        conn = _gc(); cur = conn.cursor()
        cur.execute("ALTER TABLE movimientos ADD COLUMN IF NOT EXISTS fecha_compra_marketplace TIMESTAMP")
        if sku:
            cur.execute("""
                UPDATE movimientos SET fecha_compra_marketplace = %s
                WHERE id = (
                    SELECT id FROM movimientos
                    WHERE canal = %s
                      AND (COALESCE(orden_id::text,'') = %s OR COALESCE(numero_orden,'') = %s)
                      AND sku = %s AND tipo = 'salida'
                      AND fecha_compra_marketplace IS NULL
                    ORDER BY fecha DESC LIMIT 1
                )
            """, (fc, canal, str(orden_id), str(orden_id), sku))
        else:
            cur.execute("""
                UPDATE movimientos SET fecha_compra_marketplace = %s
                WHERE canal = %s
                  AND (COALESCE(orden_id::text,'') = %s OR COALESCE(numero_orden,'') = %s)
                  AND tipo = 'salida' AND fecha_compra_marketplace IS NULL
            """, (fc, canal, str(orden_id), str(orden_id)))
        conn.commit(); cur.close(); conn.close()
    except Exception as e:
        print(f"[_asegurar_fecha_compra] {canal} {orden_id}: {e}")


# Registro en memoria de las últimas sincronizaciones de stock (diagnóstico).
# Cada entrada: sku, contexto, tenant de la conexión, stock calculado, guards
# que actuaron y resultado por canal. Se consulta en /admin/lusync/stock/sync-log.
from collections import deque as _deque_sync
_SYNC_TRACE_LOG = _deque_sync(maxlen=50)


def sincronizar_stock_marketplaces(sku, stock=None, contexto="manual"):
    """Sincroniza el stock de un SKU con TODOS los marketplaces conectados.

    Args:
        sku: SKU Lusync del producto
        stock: IGNORADO para el cálculo (se mantiene por compatibilidad de firma).
               El stock que se publica a los canales seller se calcula SIEMPRE
               desde la bodega CENTRAL (bodegas propias).
        contexto: descripción para logs

    Returns:
        dict con resultado por canal: {"meli": "ok", "falabella": "error: ...", ...}

    POR QUÉ SE IGNORA EL PARÁMETRO `stock`:
    Había ~9 llamadas en el código que pasaban valores DISTINTOS: unas el stock
    total (productos.stock, que incluye fulfillment), otras el de CENTRAL. Eso
    hacía que, según qué job corriera (ventas, auto_sync periódico, cancelaciones),
    se publicara un número inflado o inconsistente — dejando SKUs con stock
    multiplicado (ej. publicar 212 cuando CENTRAL real es 16) o cayendo a 0.
    Centralizar el cálculo aquí garantiza que SIEMPRE se publique el stock propio
    (CENTRAL) a los canales seller, sin importar quién llame. Fulfillment NO se
    toca (lo gestiona cada marketplace).

    REGLAS DE ÉXITO/FALLA:
    - Si la función lanza excepción → error
    - Si retorna dict con ok:False → error (con detalle)
    - Si retorna dict con exitosas > 0 → ok
    - Si retorna dict sin publicaciones → 'sin_publicaciones' (NO se considera error)
    - Si retorna None o algo que no es dict → ok (compatibilidad legacy)
    """
    # Stock a publicar = SIEMPRE CENTRAL (bodegas propias), nunca el total.
    _trace = {"sku": sku, "contexto": contexto}
    try:
        from inventario import get_conn, _get_pool
        _cn = get_conn()
        _cur = _cn.cursor()
        # Registrar el tenant efectivo de ESTA conexión (diagnóstico RLS).
        try:
            _cur.execute("SELECT current_setting('app.tenant_id', true), current_setting('app.is_admin', true)")
            _t_row = _cur.fetchone() or (None, None)
            _trace["tenant_conexion"] = _t_row[0]
            _trace["is_admin_conexion"] = _t_row[1]
        except Exception:
            pass
        # LECTURA BLINDADA (v10): el stock a publicar se lee SIEMPRE con bypass
        # admin LOCAL a la transacción, resolviendo el tenant dueño del SKU.
        # Motivo: con RLS multi-tenant, la misma query devuelve resultados
        # distintos según el contexto de la conexión (sesión de usuario, job del
        # scheduler, token). Eso hacía que el ajuste manual publicara 0 y el
        # scheduler lo "levantara" después con desfase. Con bypass local +
        # tenant explícito, el resultado es idéntico desde cualquier ruta.
        # set_config(..., true) es transacción-local y el rollback final lo
        # limpia: NO contamina la conexión al volver al pool.
        _cur.execute("SELECT set_config('app.is_admin', 'true', true)")
        # Stock propio por tenant (JOIN también por tenant para no mezclar ni
        # duplicar filas de bodegas homónimas de otros tenants).
        _cur.execute("""
            SELECT sb.tenant_id, COALESCE(SUM(sb.cantidad), 0)
            FROM stock_bodega sb
            LEFT JOIN bodegas b
              ON b.codigo = sb.bodega_codigo AND b.tenant_id = sb.tenant_id
            WHERE sb.sku = %s
              AND (b.tipo = 'propia' OR b.tipo IS NULL OR sb.bodega_codigo = 'CENTRAL')
            GROUP BY sb.tenant_id
        """, (sku,))
        _por_tenant = {int(r[0]): int(r[1] or 0) for r in _cur.fetchall()
                       if r and r[0] is not None}
        _trace["stock_por_tenant"] = dict(_por_tenant)

        if len(_por_tenant) == 1:
            stock_publicar = next(iter(_por_tenant.values()))
        elif len(_por_tenant) > 1:
            # SKU presente en varios tenants: desambiguar por el tenant del
            # mapeo de canales activo (el que realmente publica).
            _cur.execute("""
                SELECT DISTINCT tenant_id FROM sku_mapeo_canal
                WHERE sku_lusync = %s AND activo = TRUE
            """, (sku,))
            _t_map = [int(r[0]) for r in _cur.fetchall() if r and r[0] is not None]
            _eleg = [t for t in _t_map if t in _por_tenant]
            if len(_eleg) == 1:
                stock_publicar = _por_tenant[_eleg[0]]
                _trace["tenant_elegido"] = _eleg[0]
            else:
                stock_publicar = max(_por_tenant.values())
                _trace["tenant_ambiguo"] = True
                print(f"[Sync][{contexto}] AVISO {sku}: stock en varios tenants "
                      f"{_por_tenant}; publico {stock_publicar}. Revisar tenant_id de los datos.")
        else:
            stock_publicar = 0
        _trace["stock_calculado"] = stock_publicar

        # Guard anti-cero (respaldo; el bypass local sigue activo en esta transacción):
        # nunca publicar 0 si existe stock real en CENTRAL o en productos.stock.
        if stock_publicar == 0:
            _cur.execute("""
                SELECT COALESCE(SUM(cantidad), 0)
                FROM stock_bodega
                WHERE sku = %s AND bodega_codigo = 'CENTRAL'
            """, (sku,))
            central_real = int((_cur.fetchone() or [0])[0] or 0)
            if central_real > 0:
                print(f"[Sync][{contexto}] GUARD anti-cero (CENTRAL) para {sku}: "
                      f"cálculo=0 pero CENTRAL={central_real}. Publico {central_real}.")
                _trace["guard_central"] = central_real
                stock_publicar = central_real
            else:
                _cur.execute("SELECT COALESCE(MAX(stock), 0) FROM productos WHERE sku = %s", (sku,))
                row_prod = _cur.fetchone()
                prod_stock = int(row_prod[0]) if row_prod and row_prod[0] is not None else 0
                if prod_stock > 0:
                    print(f"[Sync][{contexto}] GUARD anti-cero (productos.stock) para {sku}: "
                          f"CENTRAL=0 pero productos.stock={prod_stock}. Publico {prod_stock}.")
                    _trace["guard_productos_stock"] = prod_stock
                    stock_publicar = prod_stock
        # Cerrar la transacción: limpia el set_config local (bypass) antes de
        # devolver la conexión al pool.
        _cn.rollback()
        _cur.close()
        try:
            _get_pool().putconn(_cn)
        except Exception:
            _cn.close()
    except Exception as e:
        # Fallback defensivo: si no se pudo leer CENTRAL, usar el valor recibido
        # (comportamiento legacy) en vez de fallar el sync por completo.
        print(f"[Sync][{contexto}] no pude leer CENTRAL de {sku}: {e}; "
              f"uso valor recibido={stock}")
        _trace["fallback_except"] = str(e)[:200]
        _trace["stock_recibido_usado"] = stock
        stock_publicar = int(stock) if stock is not None else 0

    stock_publicar = max(0, stock_publicar)

    resultado = {}
    canales = [
        ("woo",          actualizar_stock_woo),
        ("walmart",      actualizar_stock_walmart),
        ("paris",        actualizar_stock_paris),
        ("mercadolibre", actualizar_stock_meli),
        ("falabella",    actualizar_stock_falabella),
        ("ripley",       actualizar_stock_ripley),
    ]
    stock = stock_publicar  # las llamadas internas de abajo usan `stock`
    for nombre_canal, fn in canales:
        try:
            ret = fn(sku, stock)
            # Inspeccionar el retorno con detalle
            if isinstance(ret, dict):
                exitosas = int(ret.get("exitosas", 0) or 0)
                fallidas = int(ret.get("fallidas", 0) or 0)
                total    = int(ret.get("total_publicaciones", 0) or 0)
                ok_flag  = ret.get("ok", None)

                if total == 0:
                    # Sin publicaciones mapeadas — NO es error real
                    resultado[nombre_canal] = "sin_publicaciones"
                    print(f"[SyncCentral][{contexto}] {nombre_canal}: SKU {sku} sin publicaciones (no se actualiza)")
                elif fallidas > 0 and exitosas == 0:
                    log_str = " | ".join(ret.get("log", [])[:3])
                    resultado[nombre_canal] = f"error: {fallidas}/{total} fallaron — {log_str[:120]}"
                    print(f"[SyncCentral][{contexto}] {nombre_canal} FALLÓ para SKU {sku} ({fallidas}/{total}): {log_str}")
                elif fallidas > 0 and exitosas > 0:
                    resultado[nombre_canal] = f"parcial: {exitosas} ok, {fallidas} fallaron"
                    print(f"[SyncCentral][{contexto}] {nombre_canal} PARCIAL para SKU {sku}: {exitosas}/{total}")
                elif exitosas > 0:
                    resultado[nombre_canal] = f"ok ({exitosas}/{total})"
                elif ok_flag is False:
                    resultado[nombre_canal] = f"error: {ret.get('log', ['fallo'])[0] if ret.get('log') else 'sin detalle'}"
                    print(f"[SyncCentral][{contexto}] {nombre_canal} falló con ok:False para SKU {sku}")
                else:
                    resultado[nombre_canal] = "ok"
            else:
                # Función legacy que no retorna dict — asumir ok si no hubo excepción
                resultado[nombre_canal] = "ok"
        except Exception as e:
            resultado[nombre_canal] = f"error: {str(e)[:80]}"
            print(f"[SyncCentral][{contexto}] {nombre_canal} EXCEPCIÓN para SKU {sku}: {e}")

    # Si CUALQUIER canal con publicaciones falló, crear una alerta para que se note
    canales_con_error = [c for c, v in resultado.items() if v.startswith("error") or v.startswith("parcial")]
    if canales_con_error:
        try:
            crear_alerta(
                tipo="error_sync",
                titulo=f"Stock no sincronizado — SKU {sku}",
                mensaje=(
                    f"El SKU <b>{sku}</b> NO se sincronizó correctamente con: "
                    f"<b>{', '.join(canales_con_error)}</b>. "
                    f"Contexto: {contexto}. Detalles: {resultado}"
                ),
                sku=sku,
                enviar_email=True
            )
        except Exception as e_al:
            print(f"[SyncCentral] no pude crear alerta: {e_al}")

    # Incluir el stock que se publicó, para diagnóstico desde los endpoints.
    resultado["_stock_publicado"] = stock_publicar

    # Registrar esta corrida en el log de diagnóstico (en memoria).
    try:
        import datetime as _dt
        _trace["timestamp"] = _dt.datetime.now().isoformat(timespec="seconds")
        _trace["stock_publicado"] = stock_publicar
        _trace["resultado_canales"] = dict(resultado)
        _SYNC_TRACE_LOG.append(_trace)
    except Exception:
        pass

    return resultado

# ════════════════════════════════════════════════════════════════════════════
# DECORADOR: con_tenant_default
# ════════════════════════════════════════════════════════════════════════════
# Envuelve schedulers y otras funciones de background para que sus get_conn()
# tengan tenant context. Mientras solo hay 1 tenant (Babymine, id=1),
# se itera sobre todos los tenants activos en BD.
#
# Funcionamiento: usa threading.local para que get_conn() pueda leer el tenant
# actual incluso sin sesión Flask.

import threading
_thread_tenant = threading.local()

def get_thread_tenant():
    """Devuelve el tenant_id seteado para este thread, o None."""
    return getattr(_thread_tenant, "tenant_id", None)

def set_thread_tenant(tenant_id, is_admin=False):
    """Setea tenant_id para el thread actual."""
    _thread_tenant.tenant_id = int(tenant_id) if tenant_id else None
    _thread_tenant.is_admin = bool(is_admin)

def clear_thread_tenant():
    """Limpia el tenant del thread."""
    _thread_tenant.tenant_id = None
    _thread_tenant.is_admin = False


def con_tenant_default(func):
    """Decorador: ejecuta func() una vez por cada tenant activo en BD.
    Mientras solo hay 1 tenant (Babymine), corre 1 vez con tenant_id=1.
    """
    from functools import wraps
    @wraps(func)
    def wrapper(*args, **kwargs):
        try:
            from inventario import get_conn as _gc, release_conn as _rc
            conn = _gc(is_admin=True)  # admin para listar todos los tenants
            cur = conn.cursor()
            cur.execute("SELECT id FROM tenants WHERE estado = 'activo' ORDER BY id ASC")
            tenant_ids = [r[0] for r in cur.fetchall()]
            cur.close()
            _rc(conn)
        except Exception as e:
            print(f"[con_tenant_default] Error listando tenants: {e}, usando default=1")
            tenant_ids = [1]

        for tid in tenant_ids:
            try:
                set_thread_tenant(tid, is_admin=False)
                print(f"[{func.__name__}] Ejecutando para tenant_id={tid}")
                func(*args, **kwargs)
            except Exception as e:
                import traceback
                print(f"[{func.__name__}] Error tenant {tid}: {e}")
                traceback.print_exc()
            finally:
                clear_thread_tenant()
    return wrapper


# ── SYNC AUTOMÁTICO WALMART CADA 5 MINUTOS ──
@con_tenant_default
def _sync_walmart_automatico():
    """Tarea de background: sincroniza órdenes Walmart sin requerir sesión"""
    # FIX: lock anti-overlapping igual que los demás canales
    if not hasattr(_sync_walmart_automatico, "_running"):
        _sync_walmart_automatico._running = False
    if _sync_walmart_automatico._running:
        print("[Scheduler Walmart] Ya hay un sync corriendo, salto")
        return
    _sync_walmart_automatico._running = True
    try:
        print("[Scheduler] Iniciando sync automático Walmart...")
        from inventario import obtener_sku_lusync_por_canal, descontar_venta_inteligente
        from bodegas_logic import detectar_fulfillment_walmart
        productos = cargar_productos()
        nuevas = 0
        errores = []

        # Descuenta apenas Walmart crea la orden (Created) para evitar sobreventa en otros canales.
        # Si el cliente cancela, el bloque de cancelaciones (más abajo) reintegra el stock automáticamente.
        for estado in ["Created", "Acknowledged", "Shipped", "Delivered"]:
            ordenes = obtener_ordenes_walmart(estado)
            for o in ordenes:
                order_id = o.get("purchaseOrderId")
                if not order_id:
                    continue
                customer_order_id = str(o.get("customerOrderId", order_id))
                if not intentar_marcar_orden_atomic(customer_order_id):
                    continue

                lineas = o.get("orderLines", {}).get("orderLine", [])
                if isinstance(lineas, dict):
                    lineas = [lineas]

                # Detectar si esta orden es WFS (Walmart Fulfillment Services)
                es_wfs = detectar_fulfillment_walmart(o)
                tipo_str = "WFS" if es_wfs else "Seller"

                items_descontados = []
                for linea in lineas:
                    try:
                        sku = linea.get("item", {}).get("sku")
                        if not sku:
                            continue
                        cantidad = 1
                        qty = linea.get("orderLineQuantity", {})
                        if qty and qty.get("amount"):
                            cantidad = int(float(qty.get("amount", 1)))
                        if cantidad == 1:
                            status_qty = linea.get("statusQuantity", {})
                            if status_qty and status_qty.get("amount"):
                                cantidad = int(float(status_qty.get("amount", 1)))

                        # FIX: usar obtener_sku_lusync_por_canal (más eficiente que listar_sku_mapeo)
                        sku_lusync = obtener_sku_lusync_por_canal("walmart", sku) or sku

                        # Buscar producto y descontar de bodega correcta
                        producto_existe = any(p["sku"] == sku_lusync for p in productos)
                        if not producto_existe:
                            print(f"[Scheduler] SKU '{sku_lusync}' no encontrado en inventario")
                            continue

                        # Parsear fecha real de compra (Walmart: orderDate puede ser epoch ms o ISO)
                        fecha_compra_wm = None
                        try:
                            date_raw = (o.get("orderDate") or o.get("createdAt") or
                                        o.get("orderPlacedTime") or o.get("orderTimestamp") or "")
                            if date_raw:
                                # Walmart suele devolver epoch en milisegundos (ej: 1714588800000)
                                if isinstance(date_raw, (int, float)) or (isinstance(date_raw, str) and str(date_raw).isdigit()):
                                    epoch_ms = int(date_raw)
                                    fecha_compra_wm = datetime.fromtimestamp(
                                        epoch_ms / 1000 if epoch_ms > 9999999999 else epoch_ms
                                    )
                                else:
                                    # ISO string
                                    fecha_compra_wm = datetime.fromisoformat(
                                        str(date_raw).replace("Z", "+00:00")
                                    )
                        except Exception as _e_wm:
                            print(f"[Scheduler Walmart] no parsea fecha '{date_raw}': {_e_wm}")
                            fecha_compra_wm = None

                        resultado = descontar_venta_inteligente(
                            sku=sku_lusync,
                            cantidad=cantidad,
                            canal="Walmart",
                            fulfillment=es_wfs,
                            orden_id=customer_order_id,
                            motivo=f"Venta Walmart {tipo_str}",
                            usuario="Sistema",
                            fecha_compra_marketplace=fecha_compra_wm
                        )
                        _asegurar_fecha_compra("Walmart", customer_order_id, fecha_compra_wm, sku=sku_lusync)
                        print(f"[Scheduler] {customer_order_id} {tipo_str}: {sku_lusync} -{cantidad} desde {resultado['bodega']}")

                        # Sync a otros canales SOLO si fue Seller (afectó Central)
                        if not es_wfs:
                            stock_total = resultado.get("stock_despues", 0)
                            sincronizar_stock_marketplaces(sku_lusync, stock_total, contexto="walmart_orden_bg")
                        items_descontados.append(sku_lusync)
                    except Exception as e:
                        errores.append(str(e))
                        print(f"[Scheduler] Error linea: {e}")

                # FIX: marcar solo UNA vez después de procesar (antes había doble marcar)
                # [atomic] orden marcada al inicio — no remarcar
                nuevas += 1

        # ── CANCELACIONES WALMART — devolver stock si se canceló una orden ya procesada
        try:
            canceladas = obtener_ordenes_walmart("Cancelled")
            reingresadas = 0
            for o in canceladas:
                order_id = o.get("purchaseOrderId")
                if not order_id:
                    continue
                customer_order_id = str(o.get("customerOrderId", order_id))
                cancel_key = f"CANCEL-{customer_order_id}"

                # Solo procesar si la orden fue previamente descontada Y no se reingresó antes
                if not orden_ya_procesada_texto(customer_order_id):
                    continue  # nunca se procesó, no hay stock que devolver
                if orden_ya_procesada_texto(cancel_key):
                    continue  # ya se procesó la cancelación

                lineas = o.get("orderLines", {}).get("orderLine", [])
                if isinstance(lineas, dict):
                    lineas = [lineas]

                productos = cargar_productos()
                items_cancelados = []  # para alerta consolidada
                for linea in lineas:
                    try:
                        sku = linea.get("item", {}).get("sku")
                        if not sku:
                            continue
                        cantidad = 1
                        qty = linea.get("orderLineQuantity", {})
                        if qty and qty.get("amount"):
                            cantidad = int(float(qty.get("amount", 1)))
                        if cantidad == 1:
                            status_qty = linea.get("statusQuantity", {})
                            if status_qty and status_qty.get("amount"):
                                cantidad = int(float(status_qty.get("amount", 1)))

                        for p in productos:
                            if p["sku"] == sku:
                                p["stock"] = p["stock"] + cantidad
                                guardar_producto(p)
                                registrar_movimiento("entrada", p["sku"], p["nombre"],
                                                    cantidad, "Cancelación Walmart",
                                                    usuario="Sistema", canal="Walmart",
                                                    orden_id=customer_order_id)
                                sincronizar_stock_marketplaces(p["sku"], p["stock"], contexto="walmart_cancelacion")
                                items_cancelados.append(f"{p['nombre']} (SKU: {sku}) x{cantidad}")
                                print(f"[Scheduler] CANCELACIÓN SKU:{sku} +{cantidad} Stock:{p['stock']}")
                    except Exception as e:
                        print(f"[Scheduler] Error cancelación linea: {e}")

                # Crear alerta consolidada por orden cancelada
                if items_cancelados:
                    try:
                        crear_alerta(
                            tipo="cancelacion",
                            canal="Walmart",
                            titulo=f"Orden cancelada en Walmart: {customer_order_id}",
                            mensaje="El cliente canceló la orden. Stock reintegrado automáticamente:<br><br>" +
                                    "<br>".join(f"• {it}" for it in items_cancelados),
                            orden_id=customer_order_id,
                            sku=items_cancelados[0].split("SKU: ")[1].split(")")[0] if items_cancelados else None
                        )
                    except Exception as e:
                        print(f"[Scheduler] Error creando alerta: {e}")

                # [atomic] orden marcada al inicio — no remarcar
                reingresadas += 1

            if reingresadas:
                print(f"[Scheduler] Cancelaciones procesadas: {reingresadas}")
        except Exception as e:
            print(f"[Scheduler] Error procesando cancelaciones: {e}")

        # Paris ya tiene su propia función _sync_paris_automatico con job registrado
        # No se duplica aquí para evitar doble procesamiento

        print(f"[Scheduler] Sync completado — nuevas:{nuevas} errores:{len(errores)}")
    except Exception as e:
        print(f"[Scheduler] Error general: {e}")
    finally:
        _sync_walmart_automatico._running = False



# ════════════════════════════════════════════════════════════════════════════
# SYNC AUTOMÁTICO MULTI-MARKETPLACE
# ════════════════════════════════════════════════════════════════════════════
# Distribución escalonada para NO saturar Render ni APIs externas:
#
#   Min 0:  MELI          ← más vendido = más reactivo (cada 5 min)
#   Min 2:  Falabella     ← 2do en volumen (cada 10 min)
#   Min 4:  Walmart       ← (ya existente, cada 5 min)
#   Min 5:  MELI nuevamente
#   Min 6:  París         ← cada 10 min
#   Min 8:  Ripley        ← cada 10 min
#   Min 10: MELI nuevamente
#   Min 10: Woo (web)     ← cada 10 min, último por menor volumen
#
# Cada sync tiene LOCK anti-overlapping: si un sync tarda más de su intervalo,
# el siguiente se salta hasta que termine.
# ════════════════════════════════════════════════════════════════════════════

# Locks globales para evitar que 2 ejecuciones del mismo canal corran a la vez
_sync_locks = {
    "meli":      {"running": False},
    "falabella": {"running": False},
    "paris":     {"running": False},
    "ripley":    {"running": False},
    "woo":       {"running": False},
    "autocorreccion": {"running": False},
}


@con_tenant_default
def _sync_meli_automatico():
    """Sync órdenes + cancelaciones MercadoLibre cada 5 min."""
    if _sync_locks["meli"]["running"]:
        print("[Scheduler MELI] Ya hay un sync corriendo, salto esta vez")
        return
    _sync_locks["meli"]["running"] = True
    try:
        print("[Scheduler MELI] Iniciando sync automático...")
        from mercadolibre import obtener_ordenes_meli
        from inventario import descontar_venta_inteligente, detectar_fulfillment_meli
        from datetime import datetime
        nuevas = 0
        canceladas = 0
        errores = []

        # Solo últimas 6 horas para mantener carga baja
        try:
            ordenes = obtener_ordenes_meli(limit=50, offset=0)
        except Exception as e:
            print(f"[Scheduler MELI] Error obteniendo órdenes: {e}")
            return

        for o in ordenes:
            try:
                order_id = str(o.get("id", ""))
                estado = o.get("status", "")
                meli_key = f"MELI-{order_id}"
                cancel_key = f"MELI-CANCEL-{order_id}"

                # ── Órdenes pagadas ──
                if estado in ("paid", "confirmed"):
                    if not intentar_marcar_orden_atomic(meli_key):
                        continue

                    # Parsear fecha de compra
                    fecha_compra = None
                    try:
                        ds = (o.get("date_created", "") or "").replace("Z", "+00:00")
                        if ds:
                            fecha_compra = datetime.fromisoformat(ds)
                    except: pass

                    es_full = detectar_fulfillment_meli(o)
                    items_descontados = []

                    for item in o.get("order_items", []):
                        item_data = item.get("item", {})
                        item_id = item_data.get("id", "")
                        sku_seller = (
                            (item_data.get("seller_sku") or "").strip()
                            or (item_data.get("seller_custom_field") or "").strip()
                        )
                        cantidad = int(item.get("quantity", 1))
                        if not sku_seller:
                            continue

                        # Traducir SKU canal MELI a SKU Lusync (ej: ODJ3N001 → ODJ3NB001)
                        try:
                            from inventario import obtener_sku_lusync_por_canal
                            sku_lusync = obtener_sku_lusync_por_canal("mercadolibre", sku_canal=sku_seller, item_id_canal=item_id) or sku_seller
                        except Exception:
                            sku_lusync = sku_seller

                        # Descuento inteligente (Full vs Central)
                        try:
                            descontar_venta_inteligente(
                                sku=sku_lusync,
                                cantidad=cantidad,
                                canal="mercadolibre",
                                fulfillment=es_full,
                                orden_id=order_id,
                                fecha_compra_marketplace=fecha_compra
                            )
                            items_descontados.append((sku_lusync, cantidad))

                            # Sync a otros canales SOLO si fue Seller (Full no afecta otras bodegas)
                            if not es_full:
                                p_actual = next((pp for pp in cargar_productos() if pp["sku"] == sku_lusync), None)
                                if p_actual:
                                    sincronizar_stock_marketplaces(
                                        sku_lusync, p_actual["stock"],
                                        contexto="meli_orden_bg"
                                    )
                        except Exception as e:
                            errores.append(f"MELI {order_id}/{sku_seller}→{sku_lusync}: {e}")

                    if items_descontados:
                        # [atomic] orden marcada al inicio — no remarcar
                        nuevas += 1

                # ── Órdenes canceladas ──
                elif estado in ("cancelled", "canceled"):
                    if not intentar_marcar_orden_atomic(cancel_key):
                        continue
                    if not orden_ya_procesada_texto(meli_key):
                        # Nunca se procesó la venta, no hay nada que reintegrar
                        # [atomic] orden marcada al inicio — no remarcar
                        continue

                    items_reintegrados = []
                    for item in o.get("order_items", []):
                        item_data = item.get("item", {})
                        item_id_canc = item_data.get("id", "")
                        sku_seller = (
                            (item_data.get("seller_sku") or "").strip()
                            or (item_data.get("seller_custom_field") or "").strip()
                        )
                        cantidad = int(item.get("quantity", 1))
                        if not sku_seller: continue

                        # Traducir SKU canal a Lusync
                        try:
                            from inventario import obtener_sku_lusync_por_canal
                            sku_lusync = obtener_sku_lusync_por_canal("mercadolibre", sku_canal=sku_seller, item_id_canal=item_id_canc) or sku_seller
                        except Exception:
                            sku_lusync = sku_seller

                        productos = cargar_productos()
                        for p in productos:
                            if p["sku"] == sku_lusync:
                                p["stock"] += cantidad
                                guardar_producto(p)
                                registrar_movimiento(
                                    "entrada", p["sku"], p["nombre"], cantidad,
                                    f"Cancelación MELI orden {order_id}",
                                    usuario="Sistema", canal="MercadoLibre", orden_id=order_id
                                )
                                sincronizar_stock_marketplaces(
                                    p["sku"], p["stock"],
                                    contexto="meli_cancelacion_bg"
                                )
                                items_reintegrados.append(f"{p['nombre']} (SKU: {sku_seller}→{sku_lusync}) x{cantidad}")
                                break

                    if items_reintegrados:
                        try:
                            crear_alerta(
                                tipo="cancelacion",
                                titulo=f"Orden cancelada en MercadoLibre: {order_id}",
                                mensaje="Stock reintegrado:<br>" + "<br>".join(f"• {it}" for it in items_reintegrados),
                                sku=sku_lusync
                            )
                        except: pass
                        canceladas += 1

                    # [atomic] orden marcada al inicio — no remarcar
            except Exception as e:
                errores.append(f"MELI orden: {e}")

        print(f"[Scheduler MELI] Sync OK — nuevas:{nuevas} canceladas:{canceladas} errores:{len(errores)}")
    except Exception as e:
        print(f"[Scheduler MELI] Error general: {e}")
    finally:
        _sync_locks["meli"]["running"] = False


@con_tenant_default
def _sync_falabella_automatico():
    """Sync órdenes + cancelaciones Falabella cada 10 min."""
    if _sync_locks["falabella"]["running"]:
        print("[Scheduler Falabella] Ya hay un sync corriendo, salto")
        return
    _sync_locks["falabella"]["running"] = True
    try:
        print("[Scheduler Falabella] Iniciando sync automático...")
        # FIX: importar también obtener_items_orden_falabella — los items NO vienen
        # dentro del objeto orden, hay que pedirlos por separado con el order_id
        from falabella import obtener_ordenes_falabella, obtener_items_orden_falabella
        from inventario import obtener_sku_lusync_por_canal
        from bodegas_logic import descontar_venta, detectar_fulfillment_falabella
        nuevas = 0
        canceladas = 0
        errores = []

        # FIX: buscar en todos los estados relevantes en pasadas separadas para
        # no mezclar lógica. Estado=None devuelve todos (sin filtro).
        # Falabella SellerCenter soporta: pending, ready_to_ship, shipped, delivered, canceled
        estados_activos   = ["pending", "ready_to_ship", "shipped", "delivered"]
        estados_cancelados = ["canceled"]

        todas_ordenes = []
        for estado in estados_activos + estados_cancelados:
            try:
                lote = obtener_ordenes_falabella(estado=estado, dias=7, limit=50, offset=0)
                if isinstance(lote, list):
                    todas_ordenes.extend(lote)
            except Exception as e:
                errores.append(f"FA get estado {estado}: {e}")

        print(f"[Scheduler Falabella] Total órdenes obtenidas: {len(todas_ordenes)}")

        for o in todas_ordenes:
            if not isinstance(o, dict):
                continue
            # obtener_ordenes_falabella ya desenvuelve {"Order":{}} — o es la orden directa
            try:
                order_id = str(o.get("OrderId") or o.get("orderId") or o.get("id") or "")
                if not order_id:
                    continue
                # OrderNumber = número amigable que ve el cliente en Falabella (ej "3235355242")
                # OrderId = ID interno corto para APIs (ej "1153216340")
                order_number = str(o.get("OrderNumber") or o.get("orderNumber") or order_id)
                # Estado puede venir en Statuses[0].Status o en Status directo
                statuses = o.get("Statuses") or []
                if isinstance(statuses, list) and statuses:
                    estado_orden = (statuses[0].get("Status") or "").lower()
                else:
                    estado_orden = (o.get("Status") or o.get("status") or "").lower()
                fa_key = f"FALABELLA-{order_id}"
                cancel_key = f"FALABELLA-CANCEL-{order_id}"

                # ── Órdenes nuevas (estados que descuentan stock) ──
                if estado_orden in ("ready_to_ship", "shipped", "delivered", "pending"):
                    if not intentar_marcar_orden_atomic(fa_key):
                        continue

                    # FIX CRÍTICO: los items NO vienen en el objeto orden.
                    # Hay que pedirlos explícitamente por order_id
                    try:
                        items_orden = obtener_items_orden_falabella(order_id) or []
                    except Exception as e:
                        errores.append(f"FA items orden {order_id}: {e}")
                        items_orden = []

                    if not items_orden:
                        print(f"[Scheduler Falabella] Orden {order_id}: sin items, saltando")
                        continue

                    es_fbf = detectar_fulfillment_falabella(o)
                    tipo_str = "FBF" if es_fbf else "FBS"
                    items_descontados = []

                    # Parsear fecha real de compra (Falabella: CreatedAt = "2026-05-05 23:57:15" sin tz)
                    fecha_compra_fa = None
                    try:
                        import pytz as _pytz_fa
                        date_str = (o.get("CreatedAt") or o.get("created_at") or "")
                        if date_str:
                            try:
                                # Formato con T y/o timezone
                                fecha_compra_fa = datetime.fromisoformat(date_str.replace("Z", "+00:00"))
                            except ValueError:
                                try:
                                    # Formato "YYYY-MM-DD HH:MM:SS" sin timezone → asumir UTC
                                    fecha_naive = datetime.strptime(date_str.strip(), "%Y-%m-%d %H:%M:%S")
                                    fecha_compra_fa = _pytz_fa.utc.localize(fecha_naive)
                                except Exception:
                                    fecha_compra_fa = None
                    except Exception:
                        fecha_compra_fa = None

                    for item in items_orden:
                        # FIX: campo real de Falabella es "Sku" (no "SellerSku")
                        # obtener_items_orden_falabella ya lo normaliza en SellerSku=Sku
                        # y agrupa cantidad real (cada OrderItem = 1 unidad)
                        seller_sku = (item.get("SellerSku") or item.get("Sku") or
                                      item.get("sellerSku") or item.get("sku") or "").strip()
                        cantidad = int(item.get("Quantity") or item.get("quantity") or 1)
                        if not seller_sku:
                            continue

                        sku_lusync = obtener_sku_lusync_por_canal("falabella", seller_sku) or seller_sku

                        productos = cargar_productos()
                        prod = next((p for p in productos if p["sku"] == sku_lusync), None)
                        if not prod:
                            print(f"[Scheduler Falabella] SKU '{sku_lusync}' no encontrado")
                            continue

                        resultado = descontar_venta(
                            sku=sku_lusync,
                            cantidad=cantidad,
                            canal="Falabella",
                            fulfillment=es_fbf,
                            orden_id=order_id,
                            motivo=f"Venta Falabella {tipo_str}",
                            usuario="Sistema",
                            fecha_compra_marketplace=fecha_compra_fa,
                            origen_registro="scheduler"
                        )
                        _asegurar_fecha_compra("Falabella", order_id, fecha_compra_fa, sku=sku_lusync)
                        # Setear numero_orden = OrderNumber (lo que se ve en seller center)
                        try:
                            from inventario import get_conn as _gc_fan
                            _c_fan = _gc_fan(); _cur_fan = _c_fan.cursor()
                            _cur_fan.execute("""
                                UPDATE movimientos SET numero_orden = %s
                                WHERE canal = 'Falabella'
                                  AND (orden_id::text = %s OR numero_orden = %s)
                                  AND sku = %s
                                  AND tipo = 'salida'
                                  AND (numero_orden IS NULL OR numero_orden = orden_id::text)
                            """, (order_number, str(order_id), str(order_id), sku_lusync))
                            _c_fan.commit(); _cur_fan.close(); _c_fan.close()
                        except Exception as e_no:
                            print(f"[Scheduler Falabella] no pude setear numero_orden: {e_no}")
                        sincronizar_stock_marketplaces(
                            sku_lusync, resultado.get("stock_despues", 0),
                            contexto="falabella_orden_bg"
                        )
                        items_descontados.append(f"{seller_sku} x{cantidad}")
                        print(f"[Scheduler Falabella] {order_id} {tipo_str}: {sku_lusync} -{cantidad} desde {resultado.get('bodega','?')}")

                    if items_descontados:
                        # [atomic] orden marcada al inicio — no remarcar
                        nuevas += 1

                # ── Órdenes canceladas ──
                elif estado_orden in ("canceled", "cancelled"):
                    if not intentar_marcar_orden_atomic(cancel_key):
                        continue
                    if not orden_ya_procesada_texto(fa_key):
                        # nunca se descontó, solo marcar cancelación para no volver
                        # [atomic] orden marcada al inicio — no remarcar
                        continue

                    try:
                        items_orden = obtener_items_orden_falabella(order_id) or []
                    except Exception as e:
                        errores.append(f"FA items cancelada {order_id}: {e}")
                        items_orden = []

                    items_reintegrados = []
                    ultimo_sku = None
                    for item in items_orden:
                        seller_sku = (item.get("SellerSku") or item.get("Sku") or
                                      item.get("sellerSku") or item.get("sku") or "").strip()
                        cantidad = int(item.get("Quantity") or item.get("quantity") or 1)
                        if not seller_sku:
                            continue
                        ultimo_sku = seller_sku
                        sku_lusync = obtener_sku_lusync_por_canal("falabella", seller_sku) or seller_sku

                        productos = cargar_productos()
                        prod = next((p for p in productos if p["sku"] == sku_lusync), None)
                        if not prod:
                            continue

                        prod["stock"] += cantidad
                        guardar_producto(prod)

                        # Parsear fecha real de compra de la orden cancelada
                        fecha_compra_fa_cancel = None
                        try:
                            date_str = (o.get("CreatedAt") or o.get("created_at") or "")
                            if date_str:
                                if "T" in str(date_str):
                                    fecha_compra_fa_cancel = datetime.fromisoformat(str(date_str).replace("Z","+00:00"))
                                else:
                                    fecha_compra_fa_cancel = datetime.strptime(str(date_str)[:19], "%Y-%m-%d %H:%M:%S")
                        except Exception:
                            pass

                        registrar_movimiento(
                            "entrada", prod["sku"], prod["nombre"], cantidad,
                            f"Cancelación Falabella orden {order_number}",
                            usuario="Sistema", canal="Falabella", orden_id=order_id,
                            numero_orden=order_number,
                            fecha_compra_marketplace=fecha_compra_fa_cancel,
                            origen_registro="scheduler"
                        )
                        _asegurar_fecha_compra("Falabella", order_id, fecha_compra_fa_cancel, sku=prod["sku"])
                        sincronizar_stock_marketplaces(
                            prod["sku"], prod["stock"], contexto="falabella_cancelacion_bg"
                        )
                        items_reintegrados.append(f"{prod['nombre']} (SKU: {seller_sku}) x{cantidad}")

                    if items_reintegrados:
                        try:
                            crear_alerta(
                                tipo="cancelacion",
                                titulo=f"Orden cancelada en Falabella: {order_id}",
                                mensaje="Stock reintegrado:<br>" + "<br>".join(f"• {it}" for it in items_reintegrados),
                                sku=ultimo_sku
                            )
                        except:
                            pass
                        canceladas += 1

                    # [atomic] orden marcada al inicio — no remarcar

            except Exception as e:
                errores.append(f"FALABELLA orden: {e}")

        import gc; gc.collect()
        print(f"[Scheduler Falabella] Sync OK — nuevas:{nuevas} canceladas:{canceladas} errores:{len(errores)}")
        if errores:
            print(f"[Scheduler Falabella] Errores: {errores[:3]}")
    except Exception as e:
        print(f"[Scheduler Falabella] Error general: {e}")
    finally:
        _sync_locks["falabella"]["running"] = False


@con_tenant_default
def _sync_paris_automatico():
    """Sync órdenes + cancelaciones París cada 10 min."""
    if _sync_locks["paris"]["running"]:
        print("[Scheduler Paris] Ya hay un sync corriendo, salto")
        return
    _sync_locks["paris"]["running"] = True
    try:
        print("[Scheduler Paris] Iniciando sync automático...")
        from paris import obtener_ordenes_paris_todas
        from inventario import obtener_sku_lusync_por_canal
        from bodegas_logic import descontar_venta, detectar_fulfillment_paris
        nuevas = 0
        canceladas = 0
        errores = []

        # Traer sin filtro de estado (Paris no filtra bien por estado en la API)
        # dias=7 — ventana suficiente; el UNIQUE constraint evita duplicados
        try:
            ordenes = obtener_ordenes_paris_todas(dias=7, max_paginas=10)
        except Exception as e:
            print(f"[Scheduler Paris] Error obteniendo órdenes: {e}")
            return

        print(f"[Scheduler Paris] Órdenes obtenidas: {len(ordenes)}")

        for o in ordenes:
            try:
                sub_order = str(o.get("subOrderNumber") or o.get("subOrder") or o.get("orderNumber") or "")
                if not sub_order:
                    continue

                # Prefijos consistentes con paris.py y reprocesar_ordenes
                pa_key     = f"PARIS-{sub_order}"
                cancel_key = f"PARIS-CANCEL-{sub_order}"

                # FIX: el estado en París viene en itemStatus dentro de shipments[].items[],
                # NO a nivel de la orden. Tomar el estado general de la orden si existe,
                # pero NO descartar órdenes por estado — procesar todas las no marcadas.
                estado_orden = (
                    o.get("status") or o.get("itemStatus") or o.get("orderStatus") or ""
                ).lower()

                # Estados que indican cancelación explícita
                es_cancelada = estado_orden in ("canceled", "cancelled", "rejected", "failure")

                # ── Órdenes canceladas ──
                if es_cancelada:
                    if not intentar_marcar_orden_atomic(cancel_key):
                        continue
                    if not orden_ya_procesada_texto(pa_key):
                        # [atomic] orden marcada al inicio — no remarcar
                        continue
                    # Reintegrar: recorrer shipments → items (estructura real de París)
                    items_reintegrados = []
                    ultimo_sku = None
                    for ship in (o.get("shipments") or []):
                        for item in (ship.get("items") or []):
                            seller_sku = (item.get("seller_sku") or item.get("sellerSku") or "").strip()
                            cantidad = int(item.get("quantity") or 1)
                            if not seller_sku:
                                continue
                            ultimo_sku = seller_sku
                            sku_lusync = obtener_sku_lusync_por_canal("paris", seller_sku) or seller_sku
                            productos = cargar_productos()
                            prod = next((p for p in productos if p["sku"] == sku_lusync), None)
                            if not prod:
                                continue
                            prod["stock"] += cantidad
                            guardar_producto(prod)
                            registrar_movimiento(
                                "entrada", prod["sku"], prod["nombre"], cantidad,
                                f"Cancelación París orden {sub_order}",
                                usuario="Sistema", canal="París", orden_id=sub_order
                            )
                            sincronizar_stock_marketplaces(prod["sku"], prod["stock"], contexto="paris_cancelacion_bg")
                            items_reintegrados.append(f"{prod['nombre']} (SKU: {seller_sku}) x{cantidad}")
                    if items_reintegrados:
                        try:
                            crear_alerta(
                                tipo="cancelacion",
                                titulo=f"Orden cancelada en París: {sub_order}",
                                mensaje="Stock reintegrado:<br>" + "<br>".join(f"• {it}" for it in items_reintegrados),
                                sku=ultimo_sku
                            )
                        except:
                            pass
                        canceladas += 1
                    # [atomic] orden marcada al inicio — no remarcar
                    continue

                # ── Órdenes nuevas: procesar todas las no marcadas ──
                if not intentar_marcar_orden_atomic(pa_key):
                    continue

                # FIX CRÍTICO: los items están en shipments[].items[], NO en o.get("items")
                es_cd = detectar_fulfillment_paris(o)
                tipo_str = "Fulfillment" if es_cd else "Seller"
                items_descontados = []

                # Parsear fecha real de compra (Paris API: createdAt en ISO UTC)
                fecha_compra_pa = None
                try:
                    date_str = (o.get("createdAt") or o.get("created_at") or "")
                    if date_str:
                        fecha_compra_pa = datetime.fromisoformat(date_str.replace("Z", "+00:00"))
                except Exception:
                    fecha_compra_pa = None

                # Consolidar ítems por seller_sku — París puede repetir el mismo SKU
                # en múltiples shipments de la misma orden (bug conocido de su API)
                _items_paris = {}
                for ship in (o.get("shipments") or []):
                    for item in (ship.get("items") or []):
                        seller_sku = (item.get("seller_sku") or item.get("sellerSku") or "").strip()
                        cantidad = int(item.get("quantity") or 1)
                        if not seller_sku:
                            continue
                        if seller_sku in _items_paris:
                            _items_paris[seller_sku] += cantidad
                        else:
                            _items_paris[seller_sku] = cantidad

                for seller_sku, cantidad in _items_paris.items():
                        seller_sku = seller_sku
                        cantidad = cantidad
                        if not seller_sku:
                            continue

                        sku_lusync = obtener_sku_lusync_por_canal("paris", seller_sku) or seller_sku
                        productos = cargar_productos()
                        prod = next((p for p in productos if p["sku"] == sku_lusync), None)
                        if not prod:
                            print(f"[Scheduler Paris] SKU '{sku_lusync}' no encontrado")
                            _msg_mapeo = (
                                f"La orden <b>{sub_order}</b> de París contiene el SKU "
                                f"<b>{seller_sku}</b> que no está registrado en Lusync. "
                                "El stock <b>NO fue descontado</b>. Ve a Mapeo SKUs para registrarlo."
                            )
                            crear_alerta(
                                tipo="sku_sin_mapeo",
                                titulo=f"SKU sin mapeo — París: {seller_sku}",
                                mensaje=_msg_mapeo,
                                canal="Paris",
                                orden_id=str(sub_order),
                                sku=seller_sku,
                                enviar_email=True
                            )
                            continue

                        resultado = descontar_venta(
                            sku=sku_lusync,
                            cantidad=cantidad,
                            canal="Paris",
                            fulfillment=es_cd,
                            orden_id=sub_order,
                            motivo=f"Venta Paris {tipo_str}",
                            usuario="Sistema",
                            fecha_compra_marketplace=fecha_compra_pa,
                            origen_registro="scheduler"
                        )
                        _asegurar_fecha_compra("Paris", sub_order, fecha_compra_pa, sku=sku_lusync)
                        sincronizar_stock_marketplaces(
                            sku_lusync, resultado.get("stock_despues", 0),
                            contexto="paris_orden_bg"
                        )
                        items_descontados.append(f"{seller_sku} x{cantidad}")
                        print(f"[Scheduler Paris] {sub_order} {tipo_str}: {sku_lusync} -{cantidad} desde {resultado.get('bodega','?')}")

                if items_descontados:
                    # Orden procesada exitosamente — ya está marcada atómicamente desde el inicio
                    nuevas += 1
                elif not items_descontados and o.get("shipments"):
                    # Todos los items fallaron (SKU sin mapeo, etc.)
                    # Des-marcar la orden para que el scheduler lo reintente en el próximo ciclo
                    try:
                        fecha_str = o.get("createdAt") or o.get("created_at") or ""
                        horas = 0
                        if fecha_str:
                            from datetime import timezone as _tz
                            fecha_orden = datetime.fromisoformat(fecha_str.replace("Z", "+00:00"))
                            horas = (datetime.now(_tz.utc) - fecha_orden).total_seconds() / 3600
                        if horas > 48:
                            # Más de 48h sin poder procesar → dejar marcada (evitar loop eterno)
                            print(f"[Scheduler Paris] {sub_order} marcada sin items (>48h sin mapeo)")
                        else:
                            # Reciente → des-marcar para reintentar cuando se mapee el SKU
                            from inventario import get_conn as _gc_pa
                            _c_pa = _gc_pa(); _cr_pa = _c_pa.cursor()
                            _cr_pa.execute("DELETE FROM ordenes_procesadas WHERE order_id_texto = %s",
                                          (pa_key,))
                            _c_pa.commit(); _cr_pa.close(); _c_pa.close()
                            print(f"[Scheduler Paris] {sub_order} des-marcada — SKU sin mapeo, reintentará")
                    except Exception:
                        pass

            except Exception as e:
                errores.append(f"PA orden: {e}")

        import gc; gc.collect()
        print(f"[Scheduler Paris] Sync OK — nuevas:{nuevas} canceladas:{canceladas} errores:{len(errores)}")
        if errores:
            print(f"[Scheduler Paris] Errores: {errores[:3]}")
    except Exception as e:
        print(f"[Scheduler Paris] Error general: {e}")
    finally:
        _sync_locks["paris"]["running"] = False


@con_tenant_default
def _sync_ripley_automatico():
    """Sync órdenes + cancelaciones Ripley cada 10 min."""
    if _sync_locks["ripley"]["running"]:
        print("[Scheduler Ripley] Ya hay un sync corriendo, salto")
        return
    _sync_locks["ripley"]["running"] = True
    try:
        print("[Scheduler Ripley] Iniciando sync automático...")
        from ripley import obtener_ordenes_ripley
        from inventario import obtener_sku_lusync_por_canal
        from bodegas_logic import descontar_venta, detectar_fulfillment_ripley
        nuevas = 0
        canceladas = 0
        errores = []

        # FIX: Mirakl/Ripley requiere filtrar por estado explícito — si se pasa estado=None
        # la API puede devolver lista vacía o error. Iterar por cada estado activo
        # igual que hace el scheduler manual en ripley.py.
        # FIX: los estados en Mirakl son: WAITING_ACCEPTANCE, WAITING_DEBIT, SHIPPING,
        # SHIPPED, RECEIVED, REFUSED, CANCELED — en MAYÚSCULAS.
        estados_activos    = ["WAITING_ACCEPTANCE", "WAITING_DEBIT", "SHIPPING", "SHIPPED", "RECEIVED"]
        estados_cancelados = ["REFUSED", "CANCELED"]

        todas_ordenes = []
        for estado in estados_activos + estados_cancelados:
            try:
                lote = obtener_ordenes_ripley(estado=estado, dias=7, max_resultados=50)
                if isinstance(lote, list):
                    todas_ordenes.extend(lote)
            except Exception as e:
                errores.append(f"RP get estado {estado}: {e}")

        print(f"[Scheduler Ripley] Total órdenes obtenidas: {len(todas_ordenes)}")

        for o in todas_ordenes:
            try:
                # FIX: Mirakl devuelve el ID en "order_id" y el estado en "order_state"
                order_id = str(
                    o.get("order_id") or o.get("commercial_id") or
                    o.get("id") or ""
                )
                if not order_id:
                    continue

                # FIX: campo correcto es order_state (no status ni state)
                estado = (
                    o.get("order_state") or o.get("status") or o.get("state") or ""
                ).upper()

                rp_key     = f"RIPLEY-{order_id}"
                cancel_key = f"RP-CANCEL-{order_id}"

                # FIX: los items en Mirakl vienen en order_lines[].order_line_items[]
                # o directamente en order_lines[] según versión. Intentar ambos.
                items_orden = o.get("order_lines") or o.get("items") or o.get("lines") or []

                # ── Órdenes canceladas ──
                if estado in ("REFUSED", "CANCELED", "CANCELLED"):
                    if not intentar_marcar_orden_atomic(cancel_key):
                        continue
                    if not orden_ya_procesada_texto(rp_key):
                        # [atomic] orden marcada al inicio — no remarcar
                        continue
                    items_reintegrados = []
                    ultimo_sku = None
                    for item in items_orden:
                        shop_sku = (item.get("offer_sku") or item.get("shop_sku") or
                                    item.get("sku") or item.get("seller_sku") or "").strip()
                        cantidad = int(item.get("quantity") or 1)
                        if not shop_sku:
                            continue
                        ultimo_sku = shop_sku
                        sku_lusync = obtener_sku_lusync_por_canal("ripley", shop_sku) or shop_sku
                        productos = cargar_productos()
                        prod = next((p for p in productos if p["sku"] == sku_lusync), None)
                        if not prod:
                            continue
                        prod["stock"] += cantidad
                        guardar_producto(prod)
                        registrar_movimiento(
                            "entrada", prod["sku"], prod["nombre"], cantidad,
                            f"Cancelación Ripley orden {order_id}",
                            usuario="Sistema", canal="Ripley", orden_id=order_id
                        )
                        sincronizar_stock_marketplaces(prod["sku"], prod["stock"], contexto="ripley_cancelacion_bg")
                        items_reintegrados.append(f"{prod['nombre']} (SKU: {shop_sku}) x{cantidad}")
                    if items_reintegrados:
                        try:
                            crear_alerta(
                                tipo="cancelacion",
                                titulo=f"Orden cancelada en Ripley: {order_id}",
                                mensaje="Stock reintegrado:<br>" + "<br>".join(f"• {it}" for it in items_reintegrados),
                                sku=ultimo_sku
                            )
                        except:
                            pass
                        canceladas += 1
                    # [atomic] orden marcada al inicio — no remarcar
                    continue

                # ── Órdenes nuevas activas ──
                if estado not in ("WAITING_ACCEPTANCE", "WAITING_DEBIT", "SHIPPING", "SHIPPED", "RECEIVED"):
                    continue  # estado desconocido, saltar
                if not intentar_marcar_orden_atomic(rp_key):
                    continue

                es_fbr = detectar_fulfillment_ripley(o)
                tipo_str = "FBR" if es_fbr else "Seller"
                items_descontados = []

                # Parsear fecha real de compra (Mirakl/Ripley: created_date en ISO UTC)
                fecha_compra_rp = None
                try:
                    date_str = (o.get("created_date") or o.get("createdDate") or "")
                    if date_str:
                        fecha_compra_rp = datetime.fromisoformat(date_str.replace("Z", "+00:00"))
                except Exception:
                    fecha_compra_rp = None

                for item in items_orden:
                    shop_sku = (item.get("offer_sku") or item.get("shop_sku") or
                                item.get("sku") or item.get("seller_sku") or "").strip()
                    cantidad = int(item.get("quantity") or 1)
                    if not shop_sku:
                        continue

                    sku_lusync = obtener_sku_lusync_por_canal("ripley", shop_sku) or shop_sku
                    productos = cargar_productos()
                    prod = next((p for p in productos if p["sku"] == sku_lusync), None)
                    if not prod:
                        print(f"[Scheduler Ripley] SKU '{sku_lusync}' no encontrado")
                        continue

                    resultado = descontar_venta(
                        sku=sku_lusync,
                        cantidad=cantidad,
                        canal="Ripley",
                        fulfillment=es_fbr,
                        orden_id=order_id,
                        motivo=f"Venta Ripley {tipo_str}",
                        usuario="Sistema",
                        fecha_compra_marketplace=fecha_compra_rp,
                        origen_registro="scheduler"
                    )
                    _asegurar_fecha_compra("Ripley", order_id, fecha_compra_rp, sku=sku_lusync)
                    sincronizar_stock_marketplaces(
                        sku_lusync, resultado.get("stock_despues", 0),
                        contexto="ripley_orden_bg"
                    )
                    items_descontados.append(f"{shop_sku} x{cantidad}")
                    print(f"[Scheduler Ripley] {order_id} {tipo_str}: {sku_lusync} -{cantidad} desde {resultado.get('bodega','?')}")

                if items_descontados:
                    # [atomic] orden marcada al inicio — no remarcar
                    nuevas += 1

            except Exception as e:
                errores.append(f"RP orden: {e}")

        import gc; gc.collect()
        print(f"[Scheduler Ripley] Sync OK — nuevas:{nuevas} canceladas:{canceladas} errores:{len(errores)}")
        if errores:
            print(f"[Scheduler Ripley] Errores: {errores[:3]}")
    except Exception as e:
        print(f"[Scheduler Ripley] Error general: {e}")
    finally:
        _sync_locks["ripley"]["running"] = False


@con_tenant_default
def _sync_woo_automatico():
    """Sync órdenes + cancelaciones WooCommerce cada 10 min.
    
    Si el sitio Woo (babymine.cl) tiene problemas SSL/timeout, sale rápido sin afectar
    los syncs de otros marketplaces.
    """
    if _sync_locks["woo"]["running"]:
        print("[Scheduler Woo] Ya hay un sync corriendo, salto")
        return
    _sync_locks["woo"]["running"] = True
    try:
        print("[Scheduler Woo] Iniciando sync automático...")
        nuevas = 0
        canceladas = 0
        errores = []

        # Fecha UTC moderna (datetime.utcnow() está deprecated en Python 3.12+)
        from datetime import timezone as _tz
        fecha_corte = (datetime.now(_tz.utc) - timedelta(days=2)).isoformat()

        # Órdenes nuevas (processing/completed)
        ordenes_nuevas = []
        try:
            res = requests.get(
                "https://www.babymine.cl/wp-json/wc/v3/orders",
                params={
                    "consumer_key": WC_KEY, "consumer_secret": WC_SECRET,
                    "status": "processing,completed", "per_page": 50,
                    "after": fecha_corte
                },
                timeout=10  # Timeout corto: si Woo está lento o caído, abortamos rápido
            )
            if res.status_code == 200:
                ordenes_nuevas = res.json() or []
            else:
                print(f"[Scheduler Woo] HTTP {res.status_code} consultando órdenes nuevas")
        except requests.exceptions.SSLError as e:
            print(f"[Scheduler Woo] SSL error en babymine.cl (sitio Woo no responde): {str(e)[:120]}")
            print(f"[Scheduler Woo] Saltando sync Woo esta vez. Verificar certificado SSL del sitio.")
            return  # Salir limpio, otros marketplaces siguen
        except requests.exceptions.Timeout:
            print(f"[Scheduler Woo] Timeout consultando Woo (>10s) — sitio lento. Saltando.")
            return
        except Exception as e:
            print(f"[Scheduler Woo] Error obteniendo nuevas: {e}")
            return

        for o in ordenes_nuevas:
            try:
                order_id = str(o.get("id", ""))
                woo_key = f"WOO-{order_id}"
                if not intentar_marcar_orden_atomic(woo_key):
                    continue
                items_descontados = []
                # Parsear fecha real de compra (WooCommerce: date_created en ISO)
                fecha_compra_woo = None
                try:
                    date_str = (o.get("date_created") or o.get("date_created_gmt") or "")
                    if date_str:
                        fecha_compra_woo = datetime.fromisoformat(
                            str(date_str).replace("Z", "+00:00")
                        )
                except Exception:
                    fecha_compra_woo = None

                for line in o.get("line_items", []):
                    sku = (line.get("sku") or "").strip()
                    cantidad = int(line.get("quantity") or 1)
                    if not sku: continue
                    productos = cargar_productos()
                    for p in productos:
                        if p["sku"] == sku:
                            p["stock"] = max(0, p["stock"] - cantidad)
                            guardar_producto(p)
                            registrar_movimiento(
                                "salida", p["sku"], p["nombre"], cantidad,
                                f"Venta Web (Woo) orden {order_id}",
                                usuario="Sistema", canal="Web", orden_id=order_id,
                                fecha_override=fecha_compra_woo,
                                fecha_compra_marketplace=fecha_compra_woo,
                                origen_registro="scheduler"
                            )
                            _asegurar_fecha_compra("Web", order_id, fecha_compra_woo, sku=p["sku"])
                            sincronizar_stock_marketplaces(
                                p["sku"], p["stock"], contexto="woo_orden_bg"
                            )
                            items_descontados.append(sku)
                            break
                if items_descontados:
                    # [atomic] orden marcada al inicio — no remarcar
                    nuevas += 1
            except Exception as e:
                errores.append(f"Woo orden: {e}")

        # Órdenes canceladas (mismo manejo de errores robusto)
        ordenes_canc = []
        try:
            res_c = requests.get(
                "https://www.babymine.cl/wp-json/wc/v3/orders",
                params={
                    "consumer_key": WC_KEY, "consumer_secret": WC_SECRET,
                    "status": "cancelled,refunded,failed", "per_page": 50,
                    "after": fecha_corte
                },
                timeout=10
            )
            if res_c.status_code == 200:
                ordenes_canc = res_c.json() or []
            else:
                print(f"[Scheduler Woo] HTTP {res_c.status_code} consultando canceladas")
        except (requests.exceptions.SSLError, requests.exceptions.Timeout) as e:
            print(f"[Scheduler Woo] Saltando canceladas por error red: {str(e)[:80]}")
            ordenes_canc = []
        except Exception as e:
            print(f"[Scheduler Woo] Error obteniendo canceladas: {e}")
            ordenes_canc = []

        for o in ordenes_canc:
            try:
                order_id = str(o.get("id", ""))
                woo_key = f"WOO-{order_id}"
                cancel_key = f"WOO-CANCEL-{order_id}"
                if orden_ya_procesada_texto(cancel_key): continue
                if not orden_ya_procesada_texto(woo_key):
                    # [atomic] orden marcada al inicio — no remarcar
                    continue
                items_reintegrados = []
                ultimo_sku = None
                for line in o.get("line_items", []):
                    sku = (line.get("sku") or "").strip()
                    cantidad = int(line.get("quantity") or 1)
                    if not sku: continue
                    ultimo_sku = sku
                    productos = cargar_productos()
                    for p in productos:
                        if p["sku"] == sku:
                            p["stock"] += cantidad
                            guardar_producto(p)
                            registrar_movimiento(
                                "entrada", p["sku"], p["nombre"], cantidad,
                                f"Cancelación Web orden {order_id}",
                                usuario="Sistema", canal="Web", orden_id=order_id
                            )
                            sincronizar_stock_marketplaces(
                                p["sku"], p["stock"], contexto="woo_cancelacion_bg"
                            )
                            items_reintegrados.append(f"{p['nombre']} (SKU: {sku}) x{cantidad}")
                            break
                if items_reintegrados:
                    try:
                        crear_alerta(
                            tipo="cancelacion",
                            titulo=f"Orden cancelada en Web: {order_id}",
                            mensaje="Stock reintegrado:<br>" + "<br>".join(f"• {it}" for it in items_reintegrados),
                            sku=ultimo_sku
                        )
                    except: pass
                    canceladas += 1
                # [atomic] orden marcada al inicio — no remarcar
            except Exception as e:
                errores.append(f"Woo cancel: {e}")

        print(f"[Scheduler Woo] Sync OK — nuevas:{nuevas} canceladas:{canceladas} errores:{len(errores)}")
    except Exception as e:
        print(f"[Scheduler Woo] Error general: {e}")
    finally:
        _sync_locks["woo"]["running"] = False


scheduler = BackgroundScheduler(daemon=True)

# ── Registrar todos los schedulers (escalonados) ──
