@app.route("/admin/mapear_sku", methods=["GET", "POST"])
def admin_mapear_sku():
    """Registra un mapeo SKU en AMBAS tablas (sku_mapeo + sku_mapeo_canal).
    Accesible con token para emergencias sin deploy.
    GET/POST params: sku_lusync, canal, sku_canal, token
    Ejemplo: /admin/mapear_sku?sku_lusync=SDCMR001&canal=paris&sku_canal=SDCR2021-1&token=XXX
    """
    bypass_token = os.environ.get("ADMIN_BYPASS_TOKEN", "lcTDX2fjcH3hiZFvv8apEwPd-eiCIqFdkKqJIVy1bVw")
    _json_data = (request.get_json(silent=True) or {}) if request.is_json else {}
    token_recibido = request.args.get("token") or _json_data.get("token", "")
    autorizado = session.get("logged") or (token_recibido == bypass_token)
    if not autorizado:
        return jsonify({"error": "no autorizado"}), 401

    data = {}
    try:
        if request.is_json:
            data = request.get_json(silent=True) or {}
    except Exception:
        data = {}
    sku_lusync = (request.args.get("sku_lusync") or data.get("sku_lusync") or "").strip()
    canal      = (request.args.get("canal")      or data.get("canal")      or "").strip().lower()
    sku_canal  = (request.args.get("sku_canal")  or data.get("sku_canal")  or "").strip()

    if not sku_lusync or not canal or not sku_canal:
        return jsonify({
            "error": "Faltan parámetros",
            "uso": "/admin/mapear_sku?sku_lusync=SDCMR001&canal=paris&sku_canal=SDCR2021-1&token=XXX"
        }), 400

    try:
        from inventario import agregar_publicacion, guardar_sku_mapeo_fila

        # 1. sku_mapeo_canal (tabla nueva — la que usa el scheduler)
        agregar_publicacion(sku_lusync, canal, sku_canal)

        # 2. sku_mapeo (tabla vieja — para el panel visual)
        col_map = {
            "paris": "paris", "walmart": "walmart", "falabella": "falabella",
            "ripley": "ripley", "mercadolibre": "mercadolibre", "hites": "hites",
            "woocommerce": "web", "web": "web"
        }
        col = col_map.get(canal)
        if col:
            guardar_sku_mapeo_fila(sku_lusync, {col: sku_canal})

        registrar_audit(
            session.get("usuario", "admin_token"), request.remote_addr,
            "mapear_sku_admin",
            detalle=f"{sku_lusync} → {canal}:{sku_canal}"
        )

        return jsonify({
            "ok": True,
            "sku_lusync": sku_lusync,
            "canal": canal,
            "sku_canal": sku_canal,
            "mensaje": f"✅ Mapeado correctamente: {sku_lusync} ↔ {canal}:{sku_canal}",
            "siguiente": f"Ahora llama /paris/forzar_orden/3104945440 para reprocesar la orden"
        })

    except Exception as e:
        import traceback
        return jsonify({"ok": False, "error": str(e), "trace": traceback.format_exc()}), 500


def ruta_plataforma_web():
    if not session.get("logged"): return jsonify({}), 401
    if request.method == "POST":
        data = request.json or {}
        set_plataforma_web(data.get("plataforma", "woocommerce"))
        return jsonify({"ok": True})
    return jsonify({"plataforma": get_plataforma_web()})

@app.route("/sku_mapeo/exportar_excel")
def ruta_exportar_excel():
    if not session.get("logged"): return redirect("/")
    try:
        import io, openpyxl
        filas = listar_sku_mapeo()
        wb = openpyxl.Workbook()
        ws = wb.active
        ws.title = "Mapeo SKUs"
        ws.append(["SKU Lusync","Producto","SKU Web","SKU Walmart","SKU Paris",
                   "SKU Falabella","SKU Ripley","SKU MercadoLibre","SKU Hites"])
        for f in filas:
            ws.append([f.get("sku_lusync",""), f.get("nombre",""),
                       f.get("sku_web",""), f.get("sku_walmart",""),
                       f.get("sku_paris",""), f.get("sku_falabella",""),
                       f.get("sku_ripley",""), f.get("sku_mercadolibre",""),
                       f.get("sku_hites","")])
        buf = io.BytesIO()
        wb.save(buf); buf.seek(0)
        return send_file(buf, download_name="mapeo_skus.xlsx", as_attachment=True,
                         mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")
    except Exception as e:
        return jsonify({"error": str(e)}), 500

@app.route("/sku_mapeo/importar_excel", methods=["POST"])
def ruta_importar_excel():
    """Importa mapeo SKU → marketplaces desde Excel.

    Estructura esperada (columnas):
      A: SKU Lusync
      B: Producto (nombre, ignorado)
      C: SKU Web
      D: SKU Walmart
      E: SKU Paris
      F: SKU Falabella
      G: SKU Ripley
      H: SKU MercadoLibre
      I: SKU Hites

    Pobla DOS tablas:
      1. sku_mapeo (legacy 1:1) — para compatibilidad
      2. sku_mapeo_canal (nuevo multi-publicación) — para que UI muestre badges
    """
    if not session.get("logged"): return jsonify({"ok": False, "error": "no autorizado"}), 401
    try:
        import io, openpyxl
        from inventario import agregar_publicacion

        archivo = request.files.get("archivo")
        if not archivo:
            return jsonify({"ok": False, "error": "No se recibio archivo"})
        wb = openpyxl.load_workbook(io.BytesIO(archivo.read()), data_only=True)
        ws = wb.active
        rows = list(ws.iter_rows(values_only=True))
        if len(rows) < 2:
            return jsonify({"ok": False, "error": "Archivo vacio o sin datos"})

        importados = 0
        publicaciones_agregadas = 0
        publicaciones_fallidas = 0
        errores = []
        log = []

        # Mapeo de columna → canal (índice de columna en el Excel)
        # Col A=0 sku_lusync, B=1 producto, C=2 web, D=3 walmart, E=4 paris,
        # F=5 falabella, G=6 ripley, H=7 mercadolibre, I=8 hites
        canales_columnas = [
            (2, "web"),
            (3, "walmart"),
            (4, "paris"),
            (5, "falabella"),
            (6, "ripley"),
            (7, "mercadolibre"),
            (8, "hites"),
        ]

        for i, row in enumerate(rows[1:], start=2):
            try:
                sku_lusync = str(row[0]).strip() if row[0] else ""
                if not sku_lusync or sku_lusync == "None":
                    continue

                # 1. Tabla legacy sku_mapeo (1:1)
                skus = {
                    "web":          str(row[2]).strip() if len(row) > 2 and row[2] else "",
                    "walmart":      str(row[3]).strip() if len(row) > 3 and row[3] else "",
                    "paris":        str(row[4]).strip() if len(row) > 4 and row[4] else "",
                    "falabella":    str(row[5]).strip() if len(row) > 5 and row[5] else "",
                    "ripley":       str(row[6]).strip() if len(row) > 6 and row[6] else "",
                    "mercadolibre": str(row[7]).strip() if len(row) > 7 and row[7] else "",
                    "hites":        str(row[8]).strip() if len(row) > 8 and row[8] else "",
                }
                guardar_sku_mapeo_fila(sku_lusync, skus)
                importados += 1

                # 2. Tabla nueva sku_mapeo_canal (multi-publicación)
                # Para cada canal con SKU, agregamos UNA publicación (idempotente)
                for col_idx, canal in canales_columnas:
                    if col_idx < len(row) and row[col_idx]:
                        sku_canal_val = str(row[col_idx]).strip()
                        if sku_canal_val and sku_canal_val.lower() not in ("none", "nan", "null", ""):
                            # Para MELI: si el SKU empieza con MLC, es item_id; sino es seller_sku
                            item_id_canal = None
                            sku_para_guardar = sku_canal_val
                            if canal == "mercadolibre" and sku_canal_val.upper().startswith("MLC"):
                                item_id_canal = sku_canal_val
                                sku_para_guardar = sku_canal_val

                            # ── BLINDAJE: verificar si ya existe ANTES de insertar ──
                            # Esto evita los duplicados que se crean cuando se re-importa
                            # el Excel sobre un dataset que ya fue procesado por auto_mapeo_v2
                            try:
                                from inventario import get_conn
                                conn_check = get_conn(); cur_check = conn_check.cursor()
                                cur_check.execute("""
                                    SELECT COUNT(*) FROM sku_mapeo_canal
                                    WHERE canal = %s
                                      AND sku_lusync = %s
                                      AND sku_canal = %s
                                      AND activo = TRUE
                                """, (canal, sku_lusync, sku_para_guardar))
                                ya_existe = cur_check.fetchone()[0] > 0
                                cur_check.close(); conn_check.close()
                            except Exception as e_check:
                                ya_existe = False
                                log.append(f"Fila {i} {sku_lusync}/{canal}: error chequeando existencia: {e_check}")

                            if ya_existe:
                                log.append(f"Fila {i} {sku_lusync} → {canal}:{sku_canal_val}: ya existe, skip (blindaje anti-duplicado)")
                                continue

                            try:
                                mapeo_id = agregar_publicacion(
                                    sku_lusync=sku_lusync,
                                    canal=canal,
                                    sku_canal=sku_para_guardar,
                                    item_id_canal=item_id_canal,
                                    es_catalogo=False,
                                    notas="import_excel"
                                )
                                if mapeo_id:
                                    publicaciones_agregadas += 1
                                else:
                                    publicaciones_fallidas += 1
                                    log.append(f"Fila {i} {sku_lusync} → {canal}:{sku_canal_val}: agregar_publicacion devolvió None")
                            except Exception as e_pub:
                                publicaciones_fallidas += 1
                                log.append(f"Fila {i} {sku_lusync} → {canal}:{sku_canal_val}: {e_pub}")

            except Exception as e:
                errores.append(f"Fila {i}: {str(e)}")

        registrar_importacion_mapeo(
            session.get("usuario", "Sistema"),
            archivo.filename,
            importados,
            [{"fila": i, "error": e} for i, e in enumerate(errores)]
        )
        registrar_audit(
            session.get("usuario", "Sistema"), request.remote_addr,
            "importar_mapeo_excel",
            detalle=f"importados={importados} pubs={publicaciones_agregadas} pubs_fallidas={publicaciones_fallidas}"
        )

        return jsonify({
            "ok": True,
            "importados": importados,
            "publicaciones_agregadas": publicaciones_agregadas,
            "publicaciones_fallidas": publicaciones_fallidas,
            "errores": errores,
            "log_publicaciones": log[:50]  # primeros 50 errores de pub
        })
    except Exception as e:
        import traceback
        return jsonify({"ok": False, "error": str(e), "trace": traceback.format_exc()}), 500



@app.route("/debug/paris_stock")
def debug_paris_stock():
    """Diagnóstico: prueba envío de stock a Paris para todos los productos mapeados."""
    if not session.get("logged"): return redirect("/")
    try:
        from inventario import listar_sku_mapeo, cargar_productos
        from paris import actualizar_stock_paris, verificar_conexion_paris

        conexion = verificar_conexion_paris()
        productos = {p["sku"]: p for p in cargar_productos()}
        mapeo = listar_sku_mapeo()

        resultados = []
        for fila in mapeo:
            sku_lusync = fila.get("sku_lusync", "")
            sku_paris  = fila.get("sku_paris", "")
            if not sku_paris:
                continue
            prod = productos.get(sku_lusync)
            stock_actual = prod.get("stock", 0) if prod else 0

            ok = actualizar_stock_paris(sku_lusync, stock_actual)
            resultados.append({
                "sku_lusync": sku_lusync,
                "sku_paris":  sku_paris,
                "nombre":     fila.get("nombre", ""),
                "stock":      stock_actual,
                "ok":         ok
            })

        return jsonify({
            "conexion": conexion,
            "total_mapeados": len(resultados),
            "exitosos": sum(1 for r in resultados if r["ok"]),
            "fallidos": sum(1 for r in resultados if not r["ok"]),
            "detalle":  resultados
        })
    except Exception as e:
        import traceback
        return jsonify({"error": str(e), "trace": traceback.format_exc()}), 500



@app.route("/debug/paris_stock_raw")
def debug_paris_stock_raw():
    """Envía stock a Paris uno por uno y muestra status + body crudo de cada respuesta."""
    if not session.get("logged"): return redirect("/")
    try:
        import requests as req
        from inventario import listar_sku_mapeo, cargar_productos
        from paris import paris_headers, PARIS_BASE_URL

        productos = {p["sku"]: p for p in cargar_productos()}
        mapeo = listar_sku_mapeo()

        resultados = []
        for fila in mapeo:
            sku_lusync = fila.get("sku_lusync", "")
            sku_paris  = (fila.get("sku_paris", "") or "").strip()
            if not sku_paris:
                continue
            prod = productos.get(sku_lusync)
            stock_actual = int(prod.get("stock", 0)) if prod else 0

            payload = {"skus": [{"skuSeller": sku_paris, "quantity": stock_actual}]}
            try:
                res = req.post(
                    f"{PARIS_BASE_URL}/v1/stock/sku-seller",
                    headers=paris_headers(),
                    json=payload,
                    timeout=15
                )
                resultados.append({
                    "sku_lusync": sku_lusync,
                    "sku_paris": sku_paris,
                    "stock": stock_actual,
                    "status": res.status_code,
                    "request_body": payload,
                    "response_body": res.text[:500]
                })
            except Exception as e:
                resultados.append({
                    "sku_lusync": sku_lusync,
                    "sku_paris": sku_paris,
                    "stock": stock_actual,
                    "error": str(e),
                    "request_body": payload
                })

        return jsonify({"resultados": resultados})
    except Exception as e:
        import traceback
        return jsonify({"error": str(e), "trace": traceback.format_exc()}), 500


@app.route("/debug/paris_stock_v2")
def debug_paris_stock_v2():
    """Prueba 3 variantes de payload para identificar el formato correcto."""
    if not session.get("logged"): return redirect("/")
    try:
        import requests as req
        from paris import paris_headers, PARIS_BASE_URL

        # Probar con un SKU conocido del catálogo
        sku_test = "CDPPASN001"
        stock = 99

        variantes = [
            {"nombre": "skuSeller (camelCase, actual)",
             "payload": {"skus": [{"skuSeller": sku_test, "quantity": stock}]}},
            {"nombre": "sku_seller (snake_case)",
             "payload": {"skus": [{"sku_seller": sku_test, "quantity": stock}]}},
            {"nombre": "sku (campo simple)",
             "payload": {"skus": [{"sku": sku_test, "quantity": stock}]}},
            {"nombre": "objeto plano sin skus[]",
             "payload": {"skuSeller": sku_test, "quantity": stock}},
            {"nombre": "snake_case plano",
             "payload": {"sku_seller": sku_test, "quantity": stock}},
        ]

        resultados = []
        for v in variantes:
            try:
                res = req.post(
                    f"{PARIS_BASE_URL}/v1/stock/sku-seller",
                    headers=paris_headers(),
                    json=v["payload"],
                    timeout=15
                )
                resultados.append({
                    "variante": v["nombre"],
                    "payload_enviado": v["payload"],
                    "status": res.status_code,
                    "response": res.text[:400]
                })
            except Exception as e:
                resultados.append({
                    "variante": v["nombre"],
                    "payload_enviado": v["payload"],
                    "error": str(e)
                })

        return jsonify({"sku_probado": sku_test, "stock": stock, "resultados": resultados})
    except Exception as e:
        import traceback
        return jsonify({"error": str(e), "trace": traceback.format_exc()}), 500


@app.route("/debug/paris_stock_consultar")
def debug_paris_stock_consultar():
    """Consulta el stock actual desde la API de Paris para los SKUs mapeados."""
    if not session.get("logged"): return redirect("/")
    try:
        import requests as req
        from inventario import listar_sku_mapeo
        from paris import paris_headers, PARIS_BASE_URL

        mapeo = listar_sku_mapeo()
        resultados = []

        for fila in mapeo:
            sku_paris = (fila.get("sku_paris", "") or "").strip()
            if not sku_paris:
                continue

            # Endpoint v1: stock por sku_seller
            try:
                res = req.get(
                    f"{PARIS_BASE_URL}/v1/stock/sku-seller/{sku_paris}",
                    headers=paris_headers(),
                    timeout=15
                )
                resultados.append({
                    "sku_paris": sku_paris,
                    "sku_lusync": fila.get("sku_lusync"),
                    "endpoint": "v1/stock/sku-seller/{sku}",
                    "status": res.status_code,
                    "response": res.text[:600]
                })
            except Exception as e:
                resultados.append({
                    "sku_paris": sku_paris,
                    "error": str(e)
                })

        return jsonify({"resultados": resultados})
    except Exception as e:
        import traceback
        return jsonify({"error": str(e), "trace": traceback.format_exc()}), 500


@app.route("/debug/paris_stock_listar")
def debug_paris_stock_listar():
    """Lista todo el stock actual del seller usando el endpoint v2/stock."""
    if not session.get("logged"): return redirect("/")
    try:
        import requests as req
        from paris import paris_headers, PARIS_BASE_URL

        # Probar varios endpoints para ver cuál funciona
        endpoints = [
            "/v2/stock",
            "/v1/stock",
            "/v2/stock/sku-seller",
            "/v1/stock/sku-seller",
        ]
        resultados = []
        for ep in endpoints:
            try:
                res = req.get(
                    f"{PARIS_BASE_URL}{ep}",
                    headers=paris_headers(),
                    params={"limit": 200, "offset": 0},
                    timeout=20
                )
                resultados.append({
                    "endpoint": ep,
                    "status": res.status_code,
                    "response": res.text[:1500]
                })
            except Exception as e:
                resultados.append({"endpoint": ep, "error": str(e)})
        return jsonify({"resultados": resultados})
    except Exception as e:
        import traceback
        return jsonify({"error": str(e), "trace": traceback.format_exc()}), 500


@app.route("/debug/paris_stock_warehouse")
def debug_paris_stock_warehouse():
    """Probar enviando stock con campo warehouse explícito en distintos formatos."""
    if not session.get("logged"): return redirect("/")
    try:
        import requests as req
        from paris import paris_headers, PARIS_BASE_URL

        sku_test = "RHR2022-1"  # tiene stock real 25, voy a enviar 99 y ver si actualiza
        stock = 99

        variantes = [
            {"nombre": "sin warehouse",
             "payload": {"skus": [{"sku_seller": sku_test, "quantity": stock}]}},
            {"nombre": "warehouse=Dropshipping (nombre real)",
             "payload": {"skus": [{"sku_seller": sku_test, "quantity": stock, "warehouse": "Dropshipping"}]}},
            {"nombre": "warehouse=dropship (lo que retornó la API)",
             "payload": {"skus": [{"sku_seller": sku_test, "quantity": stock, "warehouse": "dropship"}]}},
            {"nombre": "warehouseName=Dropshipping",
             "payload": {"skus": [{"sku_seller": sku_test, "quantity": stock, "warehouseName": "Dropshipping"}]}},
        ]

        resultados = []
        for v in variantes:
            try:
                res = req.post(
                    f"{PARIS_BASE_URL}/v1/stock/sku-seller",
                    headers=paris_headers(),
                    json=v["payload"],
                    timeout=15
                )
                resultados.append({
                    "variante": v["nombre"],
                    "request": v["payload"],
                    "status": res.status_code,
                    "response": res.text[:600]
                })
            except Exception as e:
                resultados.append({"variante": v["nombre"], "error": str(e)})

        # Esperar 2 segundos y consultar el listado para ver si se reflejó
        import time
        time.sleep(2)
        listado = req.get(f"{PARIS_BASE_URL}/v2/stock", headers=paris_headers(),
                          params={"limit": 200}, timeout=20)

        # Buscar el SKU de prueba en el listado
        sku_actual = None
        if listado.status_code == 200:
            data = listado.json()
            for s in data.get("skus", []):
                if s.get("sku_seller") == sku_test:
                    sku_actual = {
                        "sku_seller": s.get("sku_seller"),
                        "quantity": s.get("quantity"),
                        "availableStock": s.get("availableStock"),
                        "warehouseName": s.get("warehouseName"),
                        "updatedAt": s.get("updatedAt")
                    }
                    break

        return jsonify({
            "sku_probado": sku_test,
            "stock_enviado": stock,
            "tests": resultados,
            "estado_actual_en_paris": sku_actual or "no encontrado en listado"
        })
    except Exception as e:
        import traceback
        return jsonify({"error": str(e), "trace": traceback.format_exc()}), 500


# /paris/sync_estado movido a paris.py (Blueprint)


@app.route("/paris/forzar_sync_sku", methods=["POST"])
def ruta_paris_forzar_sync():
    """Re-envía el stock actual de un SKU específico a Paris."""
    if not session.get("logged"): return jsonify({"ok": False}), 401
    try:
        from inventario import cargar_productos
        from paris import actualizar_stock_paris
        data = request.json or {}
        sku = data.get("sku_lusync", "").strip()
        if not sku:
            return jsonify({"ok": False, "error": "SKU no proporcionado"})
        prod = next((p for p in cargar_productos() if p["sku"] == sku), None)
        if not prod:
            return jsonify({"ok": False, "error": f"SKU {sku} no existe en inventario"})
        ok = actualizar_stock_paris(sku, prod["stock"])
        return jsonify({"ok": ok, "sku": sku, "stock_enviado": prod["stock"]})
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)}), 500


@app.route("/paris/forzar_orden/<sub_order_number>", methods=["POST", "GET"])
def paris_forzar_orden(sub_order_number):
    """Fuerza el procesamiento de una orden París específica ahora mismo.
    Útil cuando el scheduler no la captó (orden antigua, estado raro, etc.).
    Borra la marca si ya existía y la reprocesa completa.
    """
    if not session.get("logged"):
        return jsonify({"error": "no autorizado"}), 401
    try:
        from paris import obtener_orden_paris, obtener_ordenes_paris_todas
        from inventario import (orden_ya_procesada_texto, marcar_orden_procesada_texto,
                                obtener_sku_lusync_por_canal, get_conn as _gc)
        from bodegas_logic import descontar_venta, detectar_fulfillment_paris

        # 1. Buscar la orden — primero por endpoint directo, luego en listado
        orden = None
        fuente = "directo"
        try:
            orden = obtener_orden_paris(sub_order_number)
        except Exception:
            pass

        if not orden:
            fuente = "listado_30d"
            todas = obtener_ordenes_paris_todas(dias=30)
            for o in todas:
                if str(o.get("subOrderNumber","")) == str(sub_order_number):
                    orden = o; break

        if not orden:
            fuente = "listado_90d"
            todas = obtener_ordenes_paris_todas(dias=90)
            for o in todas:
                if str(o.get("subOrderNumber","")) == str(sub_order_number):
                    orden = o; break

        if not orden:
            return jsonify({
                "ok": False,
                "error": f"Orden {sub_order_number} no encontrada en Paris API (buscado hasta 90 días)",
                "sugerencia": "Verifica el número de sub-orden en el panel de París"
            }), 404

        pa_key     = f"PARIS-{sub_order_number}"
        cancel_key = f"PARIS-CANCEL-{sub_order_number}"

        # 2. Verificar si ya fue procesada
        ya_estaba = orden_ya_procesada_texto(pa_key)

        # Si ya está marcada, NO reprocesar a menos que se pase ?forzar=si explícitamente
        # Esto evita que un doble clic o llamada accidental duplique el stock
        if ya_estaba:
            forzar = request.args.get("forzar", "").lower()
            if forzar != "si":
                return jsonify({
                    "ok": False,
                    "ya_procesada": True,
                    "orden": sub_order_number,
                    "mensaje": (
                        f"⚠️ La orden {sub_order_number} ya fue procesada. "
                        f"El stock NO fue modificado. "
                        f"Si necesitas reprocesarla igual, agrega ?forzar=si a la URL."
                    )
                })
            # Con ?forzar=si: borrar marca y reprocesar
            _c = _gc(); _cur = _c.cursor()
            _cur.execute("DELETE FROM ordenes_procesadas WHERE order_id_texto IN (%s, %s)",
                         (pa_key, cancel_key))
            _c.commit(); _cur.close(); _c.close()
            print(f"[forzar_orden] Marca borrada manualmente con ?forzar=si: {pa_key}")

        # 3. Estado de la orden
        estado = (orden.get("status") or orden.get("itemStatus") or orden.get("orderStatus") or "").lower()
        es_cd  = detectar_fulfillment_paris(orden)
        tipo_str = "Fulfillment" if es_cd else "Seller"

        # 4. Procesar items — deduplicar SKUs antes de descontar
        # París puede devolver el mismo SKU en múltiples shipments de la misma orden.
        # Consolidamos por seller_sku sumando cantidades para no descontar dos veces.
        items_procesados = []
        items_fallidos   = []
        shipments = orden.get("shipments") or []

        if not shipments:
            return jsonify({
                "ok": False,
                "orden": sub_order_number,
                "estado": estado,
                "fuente": fuente,
                "error": "La orden no tiene shipments — estructura inesperada de París",
                "campos_orden": list(orden.keys())
            })

        # Consolidar ítems por seller_sku (suma cantidades de todos los shipments)
        items_consolidados = {}
        for ship in shipments:
            for item in (ship.get("items") or []):
                seller_sku = (item.get("seller_sku") or item.get("sellerSku") or "").strip()
                cantidad   = int(item.get("quantity") or 1)
                if not seller_sku:
                    items_fallidos.append({"error": "item sin seller_sku", "item": item})
                    continue
                if seller_sku in items_consolidados:
                    items_consolidados[seller_sku]["cantidad"] += cantidad
                else:
                    items_consolidados[seller_sku] = {"seller_sku": seller_sku, "cantidad": cantidad}

        print(f"[forzar_orden] {sub_order_number}: {len(items_consolidados)} SKUs únicos tras consolidar shipments")

        for seller_sku, item_data in items_consolidados.items():
                seller_sku = item_data["seller_sku"]
                cantidad   = item_data["cantidad"]
                if not seller_sku:
                    items_fallidos.append({"error": "item sin seller_sku", "item": item})
                    continue

                sku_lusync = obtener_sku_lusync_por_canal("paris", seller_sku) or seller_sku
                productos  = cargar_productos()
                prod = next((p for p in productos if p["sku"] == sku_lusync), None)
                if not prod:
                    items_fallidos.append({
                        "seller_sku": seller_sku,
                        "sku_lusync": sku_lusync,
                        "error": "SKU no encontrado en inventario Lusync"
                    })
                    continue

                resultado = descontar_venta(
                    sku=sku_lusync, cantidad=cantidad,
                    canal="Paris", fulfillment=es_cd,
                    orden_id=sub_order_number,
                    motivo=f"Venta Paris {tipo_str} (forzado manual)",
                    usuario=session.get("usuario", "Admin"),
                    origen_registro="manual"
                )
                sincronizar_stock_marketplaces(
                    sku_lusync, resultado.get("stock_despues", 0),
                    contexto="paris_forzado"
                )
                items_procesados.append({
                    "seller_sku"   : seller_sku,
                    "sku_lusync"   : sku_lusync,
                    "cantidad"     : cantidad,
                    "bodega"       : resultado.get("bodega", "?"),
                    "stock_antes"  : resultado.get("stock_antes"),
                    "stock_despues": resultado.get("stock_despues"),
                })

        # 5. Orden ya fue marcada atómicamente al inicio de forzar_orden
        # Si no hubo items procesados, des-marcar para permitir reintento
        if not items_procesados:
            try:
                from inventario import get_conn as _gc_fo
                _c_fo = _gc_fo(); _cr_fo = _c_fo.cursor()
                _cr_fo.execute("DELETE FROM ordenes_procesadas WHERE order_id_texto = %s",
                               (f"PARIS-{sub_order_number}",))
                _c_fo.commit(); _cr_fo.close(); _c_fo.close()
            except Exception:
                pass

        return jsonify({
            "ok"              : len(items_procesados) > 0,
            "orden"           : sub_order_number,
            "estado_api"      : estado,
            "tipo"            : tipo_str,
            "fuente"          : fuente,
            "ya_estaba_marcada": ya_estaba,
            "items_procesados": items_procesados,
            "items_fallidos"  : items_fallidos,
            "mensaje"         : (
                f"✅ {len(items_procesados)} ítem(s) procesado(s) correctamente"
                if items_procesados
                else "⚠️ No se procesó ningún ítem — revisa items_fallidos"
            )
        })

    except Exception as e:
        import traceback
        return jsonify({"ok": False, "error": str(e), "trace": traceback.format_exc()}), 500


@app.route("/admin/revertir_duplicados/<numero_orden>", methods=["GET"])
def admin_revertir_duplicados(numero_orden):
    """Revierte movimientos duplicados de una orden específica.
    Conserva SOLO el último movimiento registrado y devuelve el stock
    de los duplicados (los anteriores).
    Params: token, canal (opcional, default=paris), keep=last|first
    """
    bypass_token = os.environ.get("ADMIN_BYPASS_TOKEN", "lcTDX2fjcH3hiZFvv8apEwPd-eiCIqFdkKqJIVy1bVw")
    token = request.args.get("token", "")
    if not session.get("logged") and token != bypass_token:
        return jsonify({"error": "no autorizado"}), 401

    keep = request.args.get("keep", "last")  # last = conservar el más reciente

    try:
        from inventario import get_conn as _gc, ajustar_stock_bodega
        conn = _gc(); cur = conn.cursor()

        # Buscar todos los movimientos de esa orden (numero_orden o orden_id)
        cur.execute("""
            SELECT id, sku, nombre, cantidad, tipo, canal, fecha, usuario, motivo
            FROM movimientos
            WHERE (numero_orden = %s OR orden_id::text = %s)
              AND tipo = 'salida'
            ORDER BY fecha ASC
        """, (numero_orden, numero_orden))

        cols = [d[0] for d in cur.description]
        movs = [dict(zip(cols, r)) for r in cur.fetchall()]

        if not movs:
            cur.close(); conn.close()
            return jsonify({"error": f"No se encontraron movimientos de salida para la orden {numero_orden}"}), 404

        if len(movs) == 1:
            cur.close(); conn.close()
            return jsonify({"ok": True, "mensaje": "Solo hay 1 movimiento — no hay duplicados", "movimientos": movs})

        # Determinar cuál conservar
        conservar = movs[-1] if keep == "last" else movs[0]
        eliminar  = [m for m in movs if m["id"] != conservar["id"]]

        revertidos = []
        for m in eliminar:
            sku      = m["sku"]
            cantidad = int(m["cantidad"] or 1)
            bodega   = "CENTRAL"  # default — los duplicados suelen ser de CENTRAL

            # Devolver el stock a la bodega
            ajustar_stock_bodega(sku, bodega, +cantidad)

            # Actualizar también la tabla productos
            cur.execute("UPDATE productos SET stock = stock + %s WHERE sku = %s", (cantidad, sku))

            # Eliminar el movimiento duplicado
            cur.execute("DELETE FROM movimientos WHERE id = %s", (m["id"],))

            revertidos.append({
                "mov_id"  : m["id"],
                "sku"     : sku,
                "cantidad": cantidad,
                "fecha"   : str(m["fecha"]),
                "usuario" : m["usuario"],
                "motivo"  : m["motivo"],
                "stock_devuelto": cantidad,
            })

        conn.commit()

        # Sincronizar stock a marketplaces
        skus_afectados = list(set(m["sku"] for m in eliminar))
        for sku in skus_afectados:
            cur.execute("""
                SELECT COALESCE(SUM(sb.cantidad),0) FROM stock_bodega sb
                LEFT JOIN bodegas b ON b.codigo = sb.bodega_codigo
                WHERE sb.sku = %s AND (b.tipo = 'propia' OR b.tipo IS NULL OR sb.bodega_codigo = 'CENTRAL')
            """, (sku,))
            stock_disp = int(cur.fetchone()[0] or 0)
            sincronizar_stock_marketplaces(sku, stock_disp, contexto="revertir_duplicados")

        cur.close(); conn.close()

        registrar_audit(
            session.get("usuario", "admin_token"), request.remote_addr,
            "revertir_duplicados",
            detalle=f"orden={numero_orden} eliminados={len(revertidos)} conservado_id={conservar['id']}"
        )

        return jsonify({
            "ok"           : True,
            "orden"        : numero_orden,
            "total_movs"   : len(movs),
            "conservado"   : {"id": conservar["id"], "fecha": str(conservar["fecha"]),
                               "usuario": conservar["usuario"]},
            "revertidos"   : revertidos,
            "skus_sync"    : skus_afectados,
            "mensaje"      : f"✅ {len(revertidos)} movimiento(s) duplicado(s) revertidos. Stock devuelto y sincronizado."
        })

    except Exception as e:
        import traceback
        return jsonify({"ok": False, "error": str(e), "trace": traceback.format_exc()}), 500


