        sql = f"""
            SELECT id, sku_lusync, canal, sku_canal, item_id_canal, activo, es_catalogo
            FROM sku_mapeo_canal
            {'WHERE ' + ' AND '.join(where) if where else ''}
            ORDER BY canal, sku_canal
        """
        cur.execute(sql, params)
