@app.route("/admin/movimiento_detalle/<orden>", methods=["GET"])
def admin_movimiento_detalle(orden):
    """Ver y/o corregir movimientos por orden.
    Params query:
      - fecha_compra=2026-05-08T20:30:00  → actualiza fecha_compra_marketplace
      - numero_orden=3235355242           → actualiza numero_orden
    Uso:
      Ver:       /admin/movimiento_detalle/1153216340?token=XXX
      Corregir:  /admin/movimiento_detalle/1153216340?numero_orden=3235355242&fecha_compra=2026-05-08T20:30:00&token=XXX
    """
    bypass_token = os.environ.get("ADMIN_BYPASS_TOKEN","lcTDX2fjcH3hiZFvv8apEwPd-eiCIqFdkKqJIVy1bVw")
    if not session.get("logged") and request.args.get("token") != bypass_token:
        return jsonify({"error":"no autorizado"}),401

    fecha_nueva  = request.args.get("fecha_compra", "")
    numero_nuevo = request.args.get("numero_orden", "")

    try:
        from inventario import get_conn as _gc, TZ_CHILE
        from datetime import datetime as _dt

        conn = _gc(); cur = conn.cursor()
        cambios = {}

        # Si se pasó fecha_compra, hacer UPDATE
        if fecha_nueva:
            try:
                fc = _dt.fromisoformat(fecha_nueva.replace("Z","+00:00"))
                if hasattr(fc, 'tzinfo') and fc.tzinfo:
                    fc = fc.astimezone(TZ_CHILE).replace(tzinfo=None)
                cur.execute("""
                    UPDATE movimientos SET fecha_compra_marketplace = %s
                    WHERE COALESCE(orden_id::text,'') = %s
                       OR COALESCE(numero_orden,'') = %s
                """, (fc, str(orden), str(orden)))
                cambios["fecha_compra_actualizada"] = cur.rowcount
            except Exception as e:
                cambios["fecha_compra_error"] = str(e)

        # Si se pasó numero_orden, hacer UPDATE
        if numero_nuevo:
            try:
                cur.execute("""
                    UPDATE movimientos SET numero_orden = %s
                    WHERE COALESCE(orden_id::text,'') = %s
                       OR COALESCE(numero_orden,'') = %s
                """, (str(numero_nuevo), str(orden), str(orden)))
                cambios["numero_orden_actualizado"] = cur.rowcount
            except Exception as e:
                cambios["numero_orden_error"] = str(e)

        if cambios:
            conn.commit()

        # Mostrar estado actual de los movimientos
        cur.execute("""
            SELECT id, tipo, sku, nombre, cantidad, canal, fecha,
                   fecha_compra_marketplace, fecha_importacion,
                   COALESCE(orden_id::text,'') AS oid,
                   COALESCE(numero_orden,'') AS no, motivo
            FROM movimientos
            WHERE COALESCE(orden_id::text,'') = %s
               OR COALESCE(numero_orden,'') = %s
            ORDER BY fecha DESC
        """, (str(orden), str(numero_nuevo or orden)))
        cols = [d[0] for d in cur.description]
        movs = [dict(zip(cols, r)) for r in cur.fetchall()]
        for m in movs:
            for k in ("fecha", "fecha_compra_marketplace", "fecha_importacion"):
                if m.get(k) and hasattr(m[k], "isoformat"):
                    m[k] = m[k].isoformat()

        cur.close(); conn.close()

        return jsonify({
            "busqueda": orden,
            "movimientos": movs,
            "cambios": cambios or None
        })
    except Exception as e:
        import traceback
        return jsonify({"error": str(e), "trace": traceback.format_exc()}), 500


@app.route("/admin/paris_test_stock", methods=["GET"])
def admin_paris_test_stock():
    """Prueba los distintos formatos de actualización de stock en Paris para diagnosticar.
    Uso: /admin/paris_test_stock?sku_seller=CDBRWA001&sku_marketplace=MKM0RWUKKM-1&cantidad=6&token=XXX
    """
    bypass_token = os.environ.get("ADMIN_BYPASS_TOKEN","lcTDX2fjcH3hiZFvv8apEwPd-eiCIqFdkKqJIVy1bVw")
    if not session.get("logged") and request.args.get("token") != bypass_token:
        return jsonify({"error":"no autorizado"}),401

    sku_seller       = request.args.get("sku_seller", "CDBRWA001")
    sku_marketplace  = request.args.get("sku_marketplace", "MKM0RWUKKM-1")
    cantidad         = int(request.args.get("cantidad", "6"))

    try:
        from paris import PARIS_BASE_URL, paris_headers
        import requests as _r
        resultados = {}

        # 1. /v1/stock/sku-seller con sku_seller
        r1 = _r.post(
            f"{PARIS_BASE_URL}/v1/stock/sku-seller",
            headers=paris_headers(),
            json={"skus":[{"sku_seller": sku_seller, "quantity": cantidad}]},
            timeout=15
        )
        resultados["v1_sku_seller"] = {
            "payload": {"sku_seller": sku_seller, "quantity": cantidad},
            "status": r1.status_code, "body": r1.text[:800]
        }

        # 2. /v2/stock con sku_marketplace
        r2 = _r.post(
            f"{PARIS_BASE_URL}/v2/stock",
            headers=paris_headers(),
            json={"skus":[{"sku": sku_marketplace, "quantity": cantidad}]},
            timeout=15
        )
        resultados["v2_sku_marketplace"] = {
            "payload": {"sku": sku_marketplace, "quantity": cantidad},
            "status": r2.status_code, "body": r2.text[:800]
        }

        # 3. /v1/stock/sku-seller con marketplace_sku
        r3 = _r.post(
            f"{PARIS_BASE_URL}/v1/stock/sku-seller",
            headers=paris_headers(),
            json={"skus":[{"sku_seller": sku_marketplace, "quantity": cantidad}]},
            timeout=15
        )
        resultados["v1_sku_seller_con_marketplace_sku"] = {
            "payload": {"sku_seller": sku_marketplace, "quantity": cantidad},
            "status": r3.status_code, "body": r3.text[:800]
        }

        return jsonify({"ok": True, "pruebas": resultados})

    except Exception as e:
        import traceback
        return jsonify({"error": str(e), "trace": traceback.format_exc()}), 500


@app.route("/stats/devoluciones_estado")
def ruta_stats_devoluciones_estado():
    """Resumen del estado de devoluciones para dashboard.
    Devuelve: conteos por estado, por urgencia (vencidas/urgente/atención/en plazo),
    por canal y lista de las más próximas a vencer.
    """
    if not session.get("logged"): return jsonify({}), 401
    try:
        from inventario import get_conn as _gc, horas_habiles_restantes, calcular_deadline_72h_habiles
        conn = _gc(); cur = conn.cursor()

        # Conteo por estado
        cur.execute("""
            SELECT estado, COUNT(*) FROM devoluciones
            GROUP BY estado
        """)
        por_estado = {r[0] or 'sin_estado': int(r[1]) for r in cur.fetchall()}

        # Conteo por canal
        cur.execute("""
            SELECT canal, COUNT(*) FROM devoluciones
            WHERE canal IS NOT NULL AND canal <> ''
            GROUP BY canal
        """)
        por_canal = [{"canal": r[0], "count": int(r[1])} for r in cur.fetchall()]

        # Pendientes con deadline (las que requieren revisión)
        cur.execute("""
            SELECT id, codigo, oc_origen, canal, sku, nombre, estado,
                   fecha_solicitud, fecha_deadline
            FROM devoluciones
            WHERE estado IN ('pendiente', 'recibida', 'en_transito', 'en_revision')
            ORDER BY fecha_deadline ASC NULLS LAST
        """)
        pendientes = []
        urgencia = {"vencidas": 0, "urgente": 0, "atencion": 0, "en_plazo": 0}
        for r in cur.fetchall():
            id_, codigo, oc, canal, sku, nombre, estado, fs, fd = r
            # Si no tiene deadline, calcularlo desde fecha_solicitud
            if not fd and fs:
                fd = calcular_deadline_72h_habiles(fs)
                # Persistir el deadline calculado
                cur.execute("UPDATE devoluciones SET fecha_deadline = %s WHERE id = %s", (fd, id_))

            horas = horas_habiles_restantes(fd) if fd else None
            if horas is None:
                clasificacion = "sin_deadline"
            elif horas < 0:
                clasificacion = "vencida"
                urgencia["vencidas"] += 1
            elif horas < 24:
                clasificacion = "urgente"
                urgencia["urgente"] += 1
            elif horas < 48:
                clasificacion = "atencion"
                urgencia["atencion"] += 1
            else:
                clasificacion = "en_plazo"
                urgencia["en_plazo"] += 1

            pendientes.append({
                "id": id_, "codigo": codigo, "oc_origen": oc, "canal": canal,
                "sku": sku, "nombre": nombre, "estado": estado,
                "fecha_solicitud": fs.isoformat() if fs else None,
                "fecha_deadline": fd.isoformat() if fd else None,
                "horas_restantes": round(horas, 1) if horas is not None else None,
                "clasificacion": clasificacion
            })

        conn.commit()
        cur.close(); conn.close()

        return jsonify({
            "por_estado": por_estado,
            "por_canal": por_canal,
            "urgencia": urgencia,
            "pendientes": pendientes[:20],  # Top 20 más urgentes
            "total_pendientes": len([p for p in pendientes if p["clasificacion"] != "sin_deadline"])
        })
    except Exception as e:
        import traceback
        return jsonify({"error": str(e), "trace": traceback.format_exc()}), 500


