@app.route("/admin/lusync/tenant/<int:tenant_id>/conectar_marketplace", methods=["GET", "POST"])
@requiere_lusync_admin
def admin_lusync_conectar_marketplace(tenant_id):
    """Form para conectar un marketplace a un tenant.
    Las credenciales se encriptan con Fernet antes de guardar.
    """
    if request.method == "GET":
        try:
            from tenancy import listar_tenants
            tenants = listar_tenants()
            tenant = next((t for t in tenants if t["id"] == tenant_id), None)
            if not tenant:
                return "<h1>Tenant no encontrado</h1>", 404
        except Exception as e:
            return f"<pre>{e}</pre>", 500

        return f"""
        <!DOCTYPE html>
        <html><head><title>Conectar MKT · {tenant['nombre']}</title></head>
        <body style="margin:0;font-family:system-ui;background:#fafaf9;padding:24px;">
            <div style="max-width:600px;margin:20px auto;background:white;border:1px solid #e8e6e0;border-radius:12px;padding:28px;">
                <a href="/admin/lusync/tenant/{tenant_id}" style="color:#534AB7;text-decoration:none;font-size:12px;">← Volver al detalle</a>
                <h2 style="margin:14px 0 6px;">🛍️ Conectar Marketplace</h2>
                <p style="font-size:13px;color:#666;margin-bottom:20px;">Tenant: <b>{tenant['nombre']}</b></p>

                <form id="frm" onsubmit="enviar(event)">

                    <div style="margin-bottom:14px;">
                        <label style="display:block;font-size:12px;font-weight:600;margin-bottom:4px;">Marketplace *</label>
                        <select id="canal" onchange="cambiarCampos()" style="width:100%;padding:9px;border:1px solid #ddd;border-radius:6px;font-size:13px;box-sizing:border-box;">
                            <option value="">— Elige marketplace —</option>
                            <option value="mercadolibre">MercadoLibre (OAuth: refresh_token)</option>
                            <option value="falabella">Falabella (API key + secret)</option>
                            <option value="paris">Paris (API key + secret)</option>
                            <option value="walmart">Walmart (Client ID + Client Secret)</option>
                            <option value="ripley">Ripley (API key + secret)</option>
                            <option value="hites">Hites (API key + secret)</option>
                            <option value="web">Web/WooCommerce (URL + Consumer Key + Secret)</option>
                            <option value="shopify">Shopify (Store URL + Access Token)</option>
                        </select>
                    </div>

                    <div style="margin-bottom:14px;">
                        <label style="display:block;font-size:12px;font-weight:600;margin-bottom:4px;">Alias (opcional)</label>
                        <input id="alias" placeholder="ej: Cuenta Principal" value="default"
                               style="width:100%;padding:9px;border:1px solid #ddd;border-radius:6px;font-size:13px;box-sizing:border-box;">
                        <small style="color:#888;font-size:10px;">Para distinguir si el cliente tiene varias cuentas del mismo MKT.</small>
                    </div>

                    <div id="campos_dinamicos" style="display:none;">
                        <fieldset style="border:1px solid #e5e7eb;border-radius:8px;padding:14px;margin-bottom:14px;">
                            <legend style="font-size:11px;font-weight:600;color:#534AB7;text-transform:uppercase;padding:0 8px;">Credenciales</legend>

                            <div id="campos_inputs"></div>
                        </fieldset>
                    </div>

                    <div style="margin-bottom:14px;padding:10px;background:#dbeafe;border-radius:6px;font-size:11px;color:#1e40af;">
                        🔒 Las credenciales se encriptan con Fernet antes de guardarse. Solo Lusync con la LUSYNC_FERNET_KEY puede desencriptarlas.
                    </div>

                    <button type="submit" style="width:100%;padding:12px;background:#534AB7;color:white;border:0;border-radius:7px;font-size:14px;font-weight:600;cursor:pointer;">
                        Conectar marketplace
                    </button>
                </form>

                <div id="resultado" style="margin-top:16px;padding:14px;border-radius:8px;display:none;"></div>
            </div>

            <script>
            const camposPorCanal = {{
                'mercadolibre': [
                    {{nombre: 'client_id', label: 'Client ID', placeholder: 'App ID de MELI'}},
                    {{nombre: 'client_secret', label: 'Client Secret', placeholder: 'Secret de MELI'}},
                    {{nombre: 'refresh_token', label: 'Refresh Token', placeholder: 'TG-...'}}
                ],
                'falabella': [
                    {{nombre: 'api_key', label: 'User ID (email)', placeholder: 'user@empresa.cl'}},
                    {{nombre: 'api_secret', label: 'API Key', placeholder: 'tu_api_key_aqui'}}
                ],
                'paris': [
                    {{nombre: 'usuario', label: 'Usuario', placeholder: 'usuario_paris'}},
                    {{nombre: 'password', label: 'Password Paris', placeholder: '••••••••'}}
                ],
                'walmart': [
                    {{nombre: 'client_id', label: 'Client ID', placeholder: 'Walmart Partner Client ID'}},
                    {{nombre: 'client_secret', label: 'Client Secret', placeholder: 'Walmart Secret'}}
                ],
                'ripley': [
                    {{nombre: 'api_key', label: 'API Key', placeholder: 'Mirakl API Key'}}
                ],
                'hites': [
                    {{nombre: 'api_key', label: 'API Key', placeholder: 'API Key Hites'}}
                ],
                'web': [
                    {{nombre: 'site_url', label: 'URL del sitio', placeholder: 'https://tutienda.cl'}},
                    {{nombre: 'consumer_key', label: 'Consumer Key', placeholder: 'ck_...'}},
                    {{nombre: 'consumer_secret', label: 'Consumer Secret', placeholder: 'cs_...'}}
                ],
                'shopify': [
                    {{nombre: 'store_url', label: 'Store URL', placeholder: 'mistore.myshopify.com'}},
                    {{nombre: 'access_token', label: 'Admin API Access Token', placeholder: 'shpat_...'}}
                ]
            }};

            function cambiarCampos() {{
                const canal = document.getElementById('canal').value;
                const campos = camposPorCanal[canal];
                const contenedor = document.getElementById('campos_dinamicos');
                const inputs = document.getElementById('campos_inputs');

                if (!campos) {{
                    contenedor.style.display = 'none';
                    return;
                }}

                inputs.innerHTML = '';
                campos.forEach(c => {{
                    inputs.innerHTML += `
                        <div style="margin-bottom:12px;">
                            <label style="display:block;font-size:12px;font-weight:600;margin-bottom:4px;">${{c.label}}</label>
                            <input data-campo="${{c.nombre}}" placeholder="${{c.placeholder}}" required
                                   style="width:100%;padding:9px;border:1px solid #ddd;border-radius:6px;font-size:13px;font-family:monospace;box-sizing:border-box;">
                        </div>
                    `;
                }});
                contenedor.style.display = 'block';
            }}

            async function enviar(e) {{
                e.preventDefault();
                const r = document.getElementById('resultado');
                const canal = document.getElementById('canal').value;
                const alias = document.getElementById('alias').value || 'default';
                if (!canal) {{
                    r.style.display='block';r.style.background='#fee2e2';r.style.color='#991b1b';
                    r.innerText = '❌ Elige un marketplace primero';
                    return;
                }}

                const credenciales = {{}};
                document.querySelectorAll('[data-campo]').forEach(inp => {{
                    credenciales[inp.dataset.campo] = inp.value;
                }});

                r.style.display='block';r.style.background='#f3f4f6';r.style.color='#374151';
                r.innerText = '⏳ Encriptando y guardando...';

                try {{
                    const res = await fetch('/admin/lusync/tenant/{tenant_id}/conectar_marketplace', {{
                        method: 'POST',
                        headers: {{'Content-Type': 'application/json'}},
                        body: JSON.stringify({{canal, alias, credenciales}})
                    }});
                    const data = await res.json();
                    if (data.ok) {{
                        r.style.background='#dcfce7';r.style.color='#166534';
                        r.innerHTML = '✅ <b>Marketplace conectado</b><br>Credencial ID: ' + data.cred_id + '<br><br>' +
                            '<a href="/admin/lusync/tenant/{tenant_id}" style="color:#534AB7;">→ Ver detalle del tenant</a>';
                        document.getElementById('frm').style.display = 'none';
                    }} else {{
                        r.style.background='#fee2e2';r.style.color='#991b1b';
                        r.innerText = '❌ ' + (data.error || 'Error');
                    }}
                }} catch(err) {{
                    r.style.background='#fee2e2';r.style.color='#991b1b';
                    r.innerText = '❌ ' + err.message;
                }}
            }}
            </script>
        </body></html>
        """

    # POST: guardar credenciales encriptadas
    try:
        data = request.json or {}
        canal = (data.get("canal") or "").strip().lower()
        alias = (data.get("alias") or "default").strip()
        credenciales = data.get("credenciales") or {}

        if not canal:
            return jsonify({"error": "Canal obligatorio"}), 400
        if not credenciales:
            return jsonify({"error": "Credenciales obligatorias"}), 400

        from tenancy import guardar_credenciales_canal
        cred_id = guardar_credenciales_canal(tenant_id, canal, credenciales, alias=alias)
        return jsonify({"ok": True, "cred_id": cred_id, "canal": canal, "alias": alias})
    except Exception as e:
        import traceback
        return jsonify({"error": str(e), "trace": traceback.format_exc()[:500]}), 500


@app.route("/admin/rls/normalizar_canales_historicos", methods=["POST", "GET"])
def admin_rls_normalizar_canales_historicos():
    """Corrige movimientos históricos con canal mal capitalizado.
    Convierte 'mercadolibre' → 'MercadoLibre' y similares.
    """
    bypass_token = os.environ.get("ADMIN_BYPASS_TOKEN", "lcTDX2fjcH3hiZFvv8apEwPd-eiCIqFdkKqJIVy1bVw")
    if not session.get("logged") and not session.get("is_lusync_admin") and request.args.get("token") != bypass_token:
        return jsonify({"error": "no autorizado"}), 401
    try:
        from inventario import get_conn, release_conn
        conn = get_conn(is_admin=True); cur = conn.cursor()

        # Ver canales actuales
        cur.execute("SELECT canal, COUNT(*) FROM movimientos GROUP BY canal ORDER BY COUNT(*) DESC")
        antes = {r[0] or "(null)": r[1] for r in cur.fetchall()}

        # Mapeo de normalización
        normalizaciones = [
            ("mercadolibre", "MercadoLibre"),
            ("MERCADOLIBRE", "MercadoLibre"),
            ("meli", "MercadoLibre"),
            ("MELI", "MercadoLibre"),
            ("Mercadolibre", "MercadoLibre"),
            ("paris", "Paris"),
            ("PARIS", "Paris"),
            ("falabella", "Falabella"),
            ("FALABELLA", "Falabella"),
            ("walmart", "Walmart"),
            ("WALMART", "Walmart"),
            ("ripley", "Ripley"),
            ("RIPLEY", "Ripley"),
            ("web", "Web"),
            ("WEB", "Web"),
            ("woocommerce", "Web"),
            ("WooCommerce", "Web"),
            ("hites", "Hites"),
            ("HITES", "Hites"),
        ]

        updates = {}
        total_modificadas = 0
        for canal_malo, canal_bueno in normalizaciones:
            cur.execute("UPDATE movimientos SET canal = %s WHERE canal = %s",
                        (canal_bueno, canal_malo))
            n = cur.rowcount
            if n > 0:
                updates[f"{canal_malo} → {canal_bueno}"] = n
                total_modificadas += n

        conn.commit()

        # Después
        cur.execute("SELECT canal, COUNT(*) FROM movimientos GROUP BY canal ORDER BY COUNT(*) DESC")
        despues = {r[0] or "(null)": r[1] for r in cur.fetchall()}

        cur.close(); release_conn(conn)

        return jsonify({
            "ok": True,
            "total_filas_modificadas": total_modificadas,
            "canales_modificados": updates,
            "distribucion_antes": antes,
            "distribucion_despues": despues
        })
    except Exception as e:
        import traceback
        return jsonify({"error": str(e), "trace": traceback.format_exc()[:500]}), 500


@app.route("/admin/rls/listar_canales", methods=["GET"])
def admin_rls_listar_canales():
    """Lista todos los canales distintos en movimientos para detectar mal capitalizados."""
    bypass_token = os.environ.get("ADMIN_BYPASS_TOKEN", "lcTDX2fjcH3hiZFvv8apEwPd-eiCIqFdkKqJIVy1bVw")
    if not session.get("logged") and not session.get("is_lusync_admin") and request.args.get("token") != bypass_token:
        return jsonify({"error": "no autorizado"}), 401
    try:
        from inventario import get_conn, release_conn
        conn = get_conn(is_admin=True); cur = conn.cursor()
        cur.execute("""
            SELECT canal, COUNT(*) as cnt, MAX(fecha) as ultima
            FROM movimientos
            GROUP BY canal
            ORDER BY ultima DESC
        """)
        canales = []
        for r in cur.fetchall():
            canales.append({
                "canal": r[0],
                "cantidad": r[1],
                "ultima_fecha": r[2].isoformat() if r[2] else None
            })
        cur.close(); release_conn(conn)
        return jsonify({"canales": canales, "total": len(canales)})
    except Exception as e:
        import traceback
        return jsonify({"error": str(e), "trace": traceback.format_exc()[:500]}), 500


@app.route("/admin/rls/forzar_sync_woo", methods=["GET"])
def admin_rls_forzar_sync_woo():
    """Fuerza un sync inmediato de Woo y muestra resultados paso a paso.
    Útil para probar si una orden se procesa correctamente sin esperar el scheduler.
    """
    bypass_token = os.environ.get("ADMIN_BYPASS_TOKEN", "lcTDX2fjcH3hiZFvv8apEwPd-eiCIqFdkKqJIVy1bVw")
    if not session.get("logged") and not session.get("is_lusync_admin") and request.args.get("token") != bypass_token:
        return jsonify({"error": "no autorizado"}), 401

    try:
        from datetime import timezone as _tz
        from inventario import get_conn, release_conn, cargar_productos, guardar_producto, registrar_movimiento

        # Setear tenant_id en threading.local para que get_conn y RLS funcionen
        set_thread_tenant(1, is_admin=False)

        dias = int(request.args.get("dias", "3"))
        fecha_corte = (datetime.now(_tz.utc) - timedelta(days=dias)).isoformat()

        log = []
        nuevas_procesadas = 0
        canceladas_procesadas = 0
        ya_procesadas = 0
        sin_sku = 0
        errores = []

        # ─── 1. ÓRDENES NUEVAS (processing/completed) ───
        log.append(f"=== Consultando órdenes processing,completed desde {fecha_corte}...")
        try:
            res = requests.get(
                "https://www.babymine.cl/wp-json/wc/v3/orders",
                params={
                    "consumer_key": WC_KEY, "consumer_secret": WC_SECRET,
                    "status": "processing,completed", "per_page": 50,
                    "after": fecha_corte
                },
                timeout=15
            )
            if res.status_code != 200:
                return jsonify({"error": f"HTTP {res.status_code}", "body": res.text[:500]})
            ordenes_nuevas = res.json() or []
            log.append(f"   Encontradas: {len(ordenes_nuevas)} órdenes nuevas")
        except Exception as e:
            return jsonify({"error": f"Error consultando Woo: {e}"})

        for o in ordenes_nuevas:
            try:
                order_id = str(o.get("id", ""))
                woo_key = f"WOO-{order_id}"
                status = o.get("status", "")

                # Verificar si ya está marcada
                conn = get_conn(); cur = conn.cursor()
                cur.execute("SELECT 1 FROM ordenes_procesadas WHERE order_id_texto = %s LIMIT 1", (woo_key,))
                ya_existe = cur.fetchone() is not None
                cur.close(); release_conn(conn)

                if ya_existe:
                    log.append(f"   ↺ {woo_key} ({status}): YA procesada, saltando")
                    ya_procesadas += 1
                    continue

                # Marcar atómicamente
                from inventario import intentar_marcar_orden_atomic
                if not intentar_marcar_orden_atomic(woo_key):
                    log.append(f"   ↺ {woo_key}: no se pudo marcar atómicamente")
                    continue

                # Parsear fecha real
                fecha_woo = o.get("date_created") or ""
                items_descontados = []

                for line in o.get("line_items", []):
                    sku = (line.get("sku") or "").strip()
                    cantidad = int(line.get("quantity") or 1)
                    if not sku:
                        sin_sku += 1
                        log.append(f"   ⚠ {woo_key}: line sin SKU")
                        continue

                    productos = cargar_productos()
                    producto_encontrado = False
                    for p in productos:
                        if p["sku"] == sku:
                            producto_encontrado = True
                            stock_antes = p["stock"]
                            p["stock"] = max(0, stock_antes - cantidad)
                            guardar_producto(p)
                            registrar_movimiento(
                                "salida", p["sku"], p["nombre"], cantidad,
                                f"Venta Web orden {order_id}",
                                usuario="Sistema", canal="Web", orden_id=order_id,
                                numero_orden=order_id,
                                fecha_compra_marketplace=fecha_woo,
                                origen_registro="webhook"
                            )
                            items_descontados.append(f"{sku} ({stock_antes}→{p['stock']})")
                            log.append(f"   ✓ {woo_key} ({status}): {sku} x{cantidad} descontado ({stock_antes}→{p['stock']})")
                            break
                    if not producto_encontrado:
                        log.append(f"   ⚠ {woo_key}: SKU '{sku}' NO existe en productos")

                if items_descontados:
                    nuevas_procesadas += 1
            except Exception as e:
                errores.append(f"Order {order_id}: {e}")
                log.append(f"   ✗ {woo_key}: ERROR {e}")

        # ─── 2. ÓRDENES CANCELADAS ───
        log.append(f"=== Consultando órdenes cancelled,refunded...")
        try:
            res_c = requests.get(
                "https://www.babymine.cl/wp-json/wc/v3/orders",
                params={
                    "consumer_key": WC_KEY, "consumer_secret": WC_SECRET,
                    "status": "cancelled,refunded", "per_page": 30,
                    "after": fecha_corte
                },
                timeout=15
            )
            ordenes_canc = res_c.json() or [] if res_c.status_code == 200 else []
            log.append(f"   Encontradas: {len(ordenes_canc)} canceladas")
        except Exception as e:
            log.append(f"   ✗ Error: {e}")
            ordenes_canc = []

        for o in ordenes_canc:
            try:
                order_id = str(o.get("id", ""))
                woo_key = f"WOO-{order_id}"
                cancel_key = f"WOO-CANCEL-{order_id}"

                conn = get_conn(); cur = conn.cursor()
                cur.execute("SELECT 1 FROM ordenes_procesadas WHERE order_id_texto = %s LIMIT 1", (cancel_key,))
                cancel_ya = cur.fetchone() is not None
                cur.execute("SELECT 1 FROM ordenes_procesadas WHERE order_id_texto = %s LIMIT 1", (woo_key,))
                venta_existia = cur.fetchone() is not None
                cur.close(); release_conn(conn)

                if cancel_ya:
                    log.append(f"   ↺ {cancel_key}: cancelación YA procesada")
                    continue

                if not venta_existia:
                    log.append(f"   ⏭ {woo_key}: NUNCA fue venta (era pending) → ignorar")
                    # Marcar para no procesar de nuevo
                    from inventario import marcar_orden_procesada_texto
                    marcar_orden_procesada_texto(cancel_key)
                    continue

                # SÍ era venta, reintegrar stock
                items_reintegrados = []
                for line in o.get("line_items", []):
                    sku = (line.get("sku") or "").strip()
                    cantidad = int(line.get("quantity") or 1)
                    if not sku: continue
                    productos = cargar_productos()
                    for p in productos:
                        if p["sku"] == sku:
                            stock_antes = p["stock"]
                            p["stock"] = stock_antes + cantidad
                            guardar_producto(p)
                            registrar_movimiento(
                                "entrada", p["sku"], p["nombre"], cantidad,
                                f"Cancelación Web orden {order_id}",
                                usuario="Sistema", canal="Web", orden_id=order_id,
                                origen_registro="webhook"
                            )
                            items_reintegrados.append(f"{sku} ({stock_antes}→{p['stock']})")
                            log.append(f"   ✓ {cancel_key}: {sku} x{cantidad} REINTEGRADO ({stock_antes}→{p['stock']})")
                            break

                if items_reintegrados:
                    from inventario import marcar_orden_procesada_texto
                    marcar_orden_procesada_texto(cancel_key)
                    canceladas_procesadas += 1
            except Exception as e:
                errores.append(f"Cancel {order_id}: {e}")
                log.append(f"   ✗ {cancel_key}: ERROR {e}")

        return jsonify({
            "ok": True,
            "resumen": {
                "ordenes_nuevas_procesadas": nuevas_procesadas,
                "ordenes_ya_procesadas_antes": ya_procesadas,
                "cancelaciones_procesadas": canceladas_procesadas,
                "items_sin_sku": sin_sku,
                "errores": len(errores)
            },
            "errores": errores,
            "log_detallado": log
        })
    except Exception as e:
        import traceback
        return jsonify({"error": str(e), "trace": traceback.format_exc()[:600]}), 500
    finally:
        try:
            clear_thread_tenant()
        except: pass


@app.route("/admin/rls/debug_woo_completadas", methods=["GET"])
def admin_rls_debug_woo_completadas():
    """Lista órdenes Woo en estado processing/completed de los últimos N días
    y verifica si tienen movimiento de venta en BD.
    """
    bypass_token = os.environ.get("ADMIN_BYPASS_TOKEN", "lcTDX2fjcH3hiZFvv8apEwPd-eiCIqFdkKqJIVy1bVw")
    if not session.get("logged") and not session.get("is_lusync_admin") and request.args.get("token") != bypass_token:
        return jsonify({"error": "no autorizado"}), 401

    try:
        dias = int(request.args.get("dias", "14"))
        from datetime import timezone as _tz
        fecha_corte = (datetime.now(_tz.utc) - timedelta(days=dias)).isoformat()

        res = requests.get(
            "https://www.babymine.cl/wp-json/wc/v3/orders",
            params={
                "consumer_key": WC_KEY, "consumer_secret": WC_SECRET,
                "status": "processing,completed",
                "per_page": 100,
                "after": fecha_corte
            },
            timeout=20
        )
        if res.status_code != 200:
            return jsonify({"error": f"HTTP {res.status_code}", "body": res.text[:500]})

        ordenes = res.json() or []

        from inventario import get_conn, release_conn
        conn = get_conn(is_admin=True); cur = conn.cursor()

        diagnostico = []
        sin_movimientos = 0
        con_movimientos = 0
        for o in ordenes:
            order_id = str(o.get("id", ""))
            woo_key = f"WOO-{order_id}"

            cur.execute("""
                SELECT id, fecha, tipo, cantidad, sku FROM movimientos
                WHERE (orden_id = %s OR numero_orden = %s)
                  AND canal = 'Web'
                ORDER BY fecha DESC
            """, (order_id, order_id))
            movs = []
            for r in cur.fetchall():
                movs.append({
                    "id": r[0], "fecha": r[1].isoformat() if r[1] else None,
                    "tipo": r[2], "cantidad": r[3], "sku": r[4]
                })

            cur.execute("SELECT orden_id FROM ordenes_procesadas WHERE order_id_texto = %s", (woo_key,))
            r_proc = cur.fetchone()

            if not movs and not r_proc:
                sin_movimientos += 1
            else:
                con_movimientos += 1

            diagnostico.append({
                "order_id": order_id,
                "status": o.get("status"),
                "date_created": o.get("date_created"),
                "total": o.get("total"),
                "items_sku": [it.get("sku") for it in (o.get("line_items") or [])],
                "items_quantity": [it.get("quantity") for it in (o.get("line_items") or [])],
                "movimientos_count": len(movs),
                "ya_procesada": bool(r_proc),
                "estado_lusync": (
                    "✅ OK procesada" if r_proc and movs else
                    "⚠ Marcada como procesada pero sin movimientos (RLS bloqueó INSERT?)" if r_proc and not movs else
                    "❌ NUNCA procesada — venta perdida" if not r_proc else
                    "?"
                )
            })

        cur.close(); release_conn(conn)

        return jsonify({
            "fecha_corte": fecha_corte,
            "dias_consultados": dias,
            "total_ordenes": len(ordenes),
            "resumen": {
                "ordenes_OK": con_movimientos,
                "ordenes_PERDIDAS": sin_movimientos
            },
            "ordenes": diagnostico
        })
    except Exception as e:
        import traceback
        return jsonify({"error": str(e), "trace": traceback.format_exc()[:600]}), 500


@app.route("/admin/rls/debug_woo_canceladas", methods=["GET"])
def admin_rls_debug_woo_canceladas():
    """Debug: lista las órdenes canceladas recientes en Woo y diagnostica
    por qué no se reflejan en movimientos."""
    bypass_token = os.environ.get("ADMIN_BYPASS_TOKEN", "lcTDX2fjcH3hiZFvv8apEwPd-eiCIqFdkKqJIVy1bVw")
    if not session.get("logged") and not session.get("is_lusync_admin") and request.args.get("token") != bypass_token:
        return jsonify({"error": "no autorizado"}), 401

    try:
        from datetime import timezone as _tz
        fecha_corte = (datetime.now(_tz.utc) - timedelta(days=7)).isoformat()

        # Traer canceladas/refunded/failed
        res_c = requests.get(
            "https://www.babymine.cl/wp-json/wc/v3/orders",
            params={
                "consumer_key": WC_KEY, "consumer_secret": WC_SECRET,
                "status": "cancelled,refunded,failed",
                "per_page": 30,
                "after": fecha_corte
            },
            timeout=15
        )

        if res_c.status_code != 200:
            return jsonify({
                "error": f"HTTP {res_c.status_code}",
                "body": res_c.text[:500]
            })

        ordenes = res_c.json() or []

        from inventario import get_conn, release_conn
        conn = get_conn(is_admin=True); cur = conn.cursor()

        diagnostico = []
        for o in ordenes:
            order_id = str(o.get("id", ""))
            woo_key = f"WOO-{order_id}"
            cancel_key = f"WOO-CANCEL-{order_id}"

            # Verificar si la orden fue procesada (positiva)
            cur.execute("""
                SELECT id, fecha, tipo, cantidad, sku, motivo
                FROM movimientos
                WHERE orden_id = %s OR numero_orden = %s
                ORDER BY fecha DESC LIMIT 10
            """, (order_id, order_id))
            movs = []
            for r in cur.fetchall():
                movs.append({
                    "id": r[0], "fecha": r[1].isoformat() if r[1] else None,
                    "tipo": r[2], "cantidad": r[3], "sku": r[4], "motivo": r[5]
                })

            # Verificar el "registro de procesadas" (usa order_id_texto)
            cur.execute("""
                SELECT orden_id, fecha FROM ordenes_procesadas WHERE order_id_texto = %s
            """, (woo_key,))
            r_proc = cur.fetchone()
            cur.execute("""
                SELECT orden_id, fecha FROM ordenes_procesadas WHERE order_id_texto = %s
            """, (cancel_key,))
            r_cancel = cur.fetchone()

            diagnostico.append({
                "order_id": order_id,
                "status": o.get("status"),
                "date_created": o.get("date_created"),
                "date_modified": o.get("date_modified"),
                "total": o.get("total"),
                "line_items_count": len(o.get("line_items", [])),
                "items_sku": [it.get("sku") for it in (o.get("line_items") or [])],
                "items_quantity": [it.get("quantity") for it in (o.get("line_items") or [])],
                "movimientos_en_bd": movs,
                "orden_proc_ya_marcada_como_venta": bool(r_proc),
                "cancelacion_ya_marcada": bool(r_cancel),
                "diagnostico": (
                    "Cancelación procesada OK" if r_cancel else
                    ("Orden NO se procesó como venta originalmente (cancelar sin venta previa)" if not r_proc else
                     "Pendiente: orden procesada pero cancelación no marcada")
                )
            })

        cur.close(); release_conn(conn)

        return jsonify({
            "fecha_corte": fecha_corte,
            "ordenes_canceladas_total": len(ordenes),
            "ordenes": diagnostico
        })
    except Exception as e:
        import traceback
        return jsonify({"error": str(e), "trace": traceback.format_exc()[:600]}), 500


@app.route("/admin/rls/debug_meli_orden", methods=["GET"])
def admin_rls_debug_meli_orden():
    """Debug profundo: detalle completo de una orden MELI específica.
    Muestra TODOS los campos relacionados con precio/envío/descuentos.
    Uso: ?order_id=2000016417889134
    """
    bypass_token = os.environ.get("ADMIN_BYPASS_TOKEN", "lcTDX2fjcH3hiZFvv8apEwPd-eiCIqFdkKqJIVy1bVw")
    if not session.get("logged") and not session.get("is_lusync_admin") and request.args.get("token") != bypass_token:
        return jsonify({"error": "no autorizado"}), 401

    order_id = request.args.get("order_id", "")
    if not order_id:
        return jsonify({"error": "falta order_id"}), 400

    try:
        from mercadolibre import meli_headers, MELI_API_URL
        import requests as _r
        hdrs = meli_headers()
        result = {"order_id": order_id}

        # 1) Detalle de la orden
        ro = _r.get(f"{MELI_API_URL}/orders/{order_id}", headers=hdrs, timeout=15)
        result["orden_status"] = ro.status_code
        orden = ro.json() if ro.status_code == 200 else {}
        result["orden_keys"] = list(orden.keys()) if orden else []

        # Capturar campos clave de la orden
        result["orden_resumen"] = {
            "status": orden.get("status"),
            "total_amount": orden.get("total_amount"),
            "paid_amount": orden.get("paid_amount"),
            "total_amount_with_shipping": orden.get("total_amount_with_shipping"),
            "currency_id": orden.get("currency_id"),
            "coupon": orden.get("coupon"),
            "taxes": orden.get("taxes"),
            "shipping_id": (orden.get("shipping") or {}).get("id"),
        }

        # Items con sus precios
        result["items"] = []
        for it in (orden.get("order_items") or []):
            result["items"].append({
                "title": (it.get("item") or {}).get("title"),
                "sku": (it.get("item") or {}).get("seller_custom_field"),
                "quantity": it.get("quantity"),
                "unit_price": it.get("unit_price"),
                "full_unit_price": it.get("full_unit_price"),
                "sale_fee": it.get("sale_fee"),
                "manufacturing_days": it.get("manufacturing_days"),
                "differential_pricing_id": it.get("differential_pricing_id"),
            })

        # Pagos (incluye shipping_cost, taxes_amount, etc)
        result["payments"] = []
        for p in (orden.get("payments") or []):
            result["payments"].append({
                "id": p.get("id"),
                "transaction_amount": p.get("transaction_amount"),
                "shipping_cost": p.get("shipping_cost"),
                "marketplace_fee": p.get("marketplace_fee"),
                "coupon_amount": p.get("coupon_amount"),
                "taxes_amount": p.get("taxes_amount"),
                "overpaid_amount": p.get("overpaid_amount"),
                "total_paid_amount": p.get("total_paid_amount"),
                "status": p.get("status"),
                "payment_method_id": p.get("payment_method_id"),
                "payment_type": p.get("payment_type"),
            })

        # 2) Detalle del shipment
        ship_id = (orden.get("shipping") or {}).get("id")
        if ship_id:
            rs = _r.get(f"{MELI_API_URL}/shipments/{ship_id}", headers=hdrs, timeout=15)
            result["shipment_status"] = rs.status_code
            if rs.status_code == 200:
                ship = rs.json()
                result["shipment_keys"] = list(ship.keys())

                # Campos críticos del shipment
                result["shipment_resumen"] = {
                    "id": ship.get("id"),
                    "status": ship.get("status"),
                    "mode": ship.get("mode"),
                    "logistic_type": ship.get("logistic_type"),
                    "shipping_mode": ship.get("shipping_mode"),
                    "shipping_option_id": (ship.get("shipping_option") or {}).get("id") if isinstance(ship.get("shipping_option"), dict) else None,
                    "shipping_option_name": (ship.get("shipping_option") or {}).get("name") if isinstance(ship.get("shipping_option"), dict) else None,
                    "tracking_number": ship.get("tracking_number"),
                    "carrier_info": ship.get("carrier_info"),
                    "service_id": ship.get("service_id"),
                }

                # COSTOS DEL ENVÍO (este es el dato clave)
                shipping_option = ship.get("shipping_option") or {}
                if isinstance(shipping_option, dict):
                    result["shipping_option_completo"] = shipping_option
                    result["costos_envio"] = {
                        "cost": shipping_option.get("cost"),  # lo que paga el seller (descuento)
                        "list_cost": shipping_option.get("list_cost"),  # costo normal
                        "shipping_cost": ship.get("shipping_cost"),
                        "buyer_cost": shipping_option.get("buyer_cost"),  # lo que paga el comprador
                    }

                # 3) Costos detallados (endpoint específico)
                try:
                    rc = _r.get(f"{MELI_API_URL}/shipments/{ship_id}/costs", headers=hdrs, timeout=10)
                    if rc.status_code == 200:
                        result["shipment_costs"] = rc.json()
                    else:
                        result["shipment_costs_status"] = rc.status_code
                except Exception as e:
                    result["shipment_costs_error"] = str(e)[:200]

        return jsonify(result)
    except Exception as e:
        import traceback
        return jsonify({"error": str(e), "trace": traceback.format_exc()[:600]}), 500


@app.route("/admin/rls/debug_paris_falabella_detalle", methods=["GET"])
def admin_rls_debug_paris_falabella_detalle():
    """Debug profundo: Paris detalle de orden + Falabella items con precio."""
    bypass_token = os.environ.get("ADMIN_BYPASS_TOKEN", "lcTDX2fjcH3hiZFvv8apEwPd-eiCIqFdkKqJIVy1bVw")
    if not session.get("logged") and not session.get("is_lusync_admin") and request.args.get("token") != bypass_token:
        return jsonify({"error": "no autorizado"}), 401

    resultado = {}

    # ─── PARIS — detalle de una orden específica ─────────────────────────
    try:
        from paris import obtener_orden_paris, obtener_ordenes_paris_todas
        # Tomar la primera orden con fecha 2026-05-13
        ordenes = obtener_ordenes_paris_todas(dias=7) or []
        primera_05_13 = None
        for o in ordenes:
            if (o.get("createdAt") or "").startswith("2026-05-13"):
                primera_05_13 = o
                break
        if primera_05_13:
            sub_order = primera_05_13.get("subOrderNumber")
            detalle = obtener_orden_paris(sub_order)
            # Buscar todos los campos que parezcan precio en la estructura
            def buscar_precios(obj, path=""):
                hallazgos = {}
                if isinstance(obj, dict):
                    for k, v in obj.items():
                        new_path = f"{path}.{k}" if path else k
                        if isinstance(v, (int, float, str)):
                            sk = k.lower()
                            if any(x in sk for x in ['price', 'amount', 'total', 'paid', 'cost', 'value']):
                                hallazgos[new_path] = v
                        elif isinstance(v, (dict, list)):
                            sub = buscar_precios(v, new_path)
                            hallazgos.update(sub)
                elif isinstance(obj, list) and obj:
                    for i, item in enumerate(obj[:2]):  # Solo primeros 2 items
                        sub = buscar_precios(item, f"{path}[{i}]")
                        hallazgos.update(sub)
                return hallazgos

            campos_precio_listado = buscar_precios(primera_05_13)
            campos_precio_detalle = buscar_precios(detalle) if detalle else {}

            # Estructura completa del primer item si existe
            items_estructura = None
            if detalle:
                for ship in (detalle.get("shipments") or []):
                    for item in (ship.get("items") or [])[:1]:
                        items_estructura = item
                        break
                    if items_estructura: break

            resultado["paris"] = {
                "sub_order_consultada": sub_order,
                "detalle_obtenido": detalle is not None,
                "detalle_keys": list(detalle.keys()) if detalle else [],
                "campos_precio_en_listado": campos_precio_listado,
                "campos_precio_en_detalle": campos_precio_detalle,
                "primer_item_completo": items_estructura,
                "shipments_count": len(detalle.get("shipments") or []) if detalle else 0,
            }
        else:
            resultado["paris"] = {"error": "no se encontró orden Paris del 13/05"}
    except Exception as e:
        import traceback
        resultado["paris"] = {"error": str(e), "trace": traceback.format_exc()[:400]}

    # ─── FALABELLA — verificar items de la orden + desglose ─────────────
    try:
        from falabella import obtener_ordenes_falabella, obtener_items_orden_falabella
        ordenes_fa = obtener_ordenes_falabella(dias=2) or []
        primera_orden = None
        for o in ordenes_fa:
            if (o.get("CreatedAt") or "").startswith("2026-05-13"):
                primera_orden = o
                break
        if primera_orden:
            order_id = primera_orden.get("OrderId")
            items = obtener_items_orden_falabella(order_id) or []
            # Capturar TODOS los campos con monto/precio/envío
            campos_montos = {}
            for k, v in primera_orden.items():
                kl = k.lower()
                if any(x in kl for x in ['price', 'total', 'amount', 'paid', 'cost',
                                          'shipping', 'fee', 'tax', 'voucher', 'discount',
                                          'subtotal', 'value']):
                    campos_montos[k] = v
            # Lo mismo para el item
            campos_montos_item = {}
            if items:
                for k, v in items[0].items():
                    kl = k.lower()
                    if any(x in kl for x in ['price', 'total', 'amount', 'paid', 'cost',
                                              'shipping', 'fee', 'tax', 'voucher', 'discount',
                                              'subtotal', 'value']):
                        campos_montos_item[k] = v
            resultado["falabella"] = {
                "order_id": order_id,
                "campos_montos_de_la_orden": campos_montos,
                "items_count": len(items),
                "campos_montos_del_item": campos_montos_item,
                "items_keys_completos": list(items[0].keys()) if items else [],
                "primer_item_completo": items[0] if items else None,
            }
        else:
            resultado["falabella"] = {"error": "no se encontró orden Falabella del 13/05"}
    except Exception as e:
        import traceback
        resultado["falabella"] = {"error": str(e), "trace": traceback.format_exc()[:400]}

    return jsonify(resultado)


@app.route("/admin/rls/debug_reporte_mkts", methods=["GET"])
def admin_rls_debug_reporte_mkts():
    """Diagnostica cada MKT individualmente: status, cant órdenes, keys del primer JSON.
    Permite identificar por qué un MKT no trae datos o trae precio en 0.
    """
    bypass_token = os.environ.get("ADMIN_BYPASS_TOKEN", "lcTDX2fjcH3hiZFvv8apEwPd-eiCIqFdkKqJIVy1bVw")
    if not session.get("logged") and not session.get("is_lusync_admin") and request.args.get("token") != bypass_token:
        return jsonify({"error": "no autorizado"}), 401

    fd = request.args.get("fecha_desde", "")
    fh = request.args.get("fecha_hasta", "")

    resultado = {"fecha_desde": fd, "fecha_hasta": fh, "canales": {}}

    # ─── WALMART ──────────────────────────────────────────────────────────
    try:
        from walmart import walmart_headers, WALMART_BASE_URL
        import requests as _r
        params_wm = {"limit": 200}
        if fd: params_wm["createdStartDate"] = f"{fd}T00:00:00"
        if fh: params_wm["createdEndDate"]   = f"{fh}T23:59:59"
        rr = _r.get(f"{WALMART_BASE_URL}/v3/orders", headers=walmart_headers(),
                    params=params_wm, timeout=20)
        body = rr.json() if rr.status_code == 200 else {}
        raw = (body.get("list", {}) or {}).get("elements", {}).get("order", []) or []
        ordenes = raw if isinstance(raw, list) else [raw]
        primera = ordenes[0] if ordenes else None
        keys_primera = list(primera.keys()) if primera else []
        primera_line_charges = None
        if primera:
            try:
                primera_line_charges = ((primera.get("orderLines") or {}).get("orderLine") or [{}])[0].get("charges")
            except: pass
        resultado["canales"]["walmart"] = {
            "status_code": rr.status_code,
            "params_enviados": params_wm,
            "cantidad_ordenes": len(ordenes),
            "primera_orden_keys": keys_primera,
            "primera_order_date": primera.get("orderDate") if primera else None,
            "primera_customer_order_id": primera.get("customerOrderId") if primera else None,
            "primera_line_charges_estructura": str(primera_line_charges)[:500] if primera_line_charges else None,
            "raw_response_keys": list(body.keys()) if body else [],
            "raw_meta": body.get("meta") if body else None,
        }
    except Exception as e:
        import traceback
        resultado["canales"]["walmart"] = {"error": str(e), "trace": traceback.format_exc()[:300]}

    # ─── FALABELLA ────────────────────────────────────────────────────────
    try:
        from falabella import obtener_ordenes_falabella, obtener_items_orden_falabella
        # Trae las últimas órdenes; vamos a ver qué campos tiene cada una
        ordenes_fa = []
        for estado in ("delivered", "shipped", "ready_to_ship"):
            try:
                lote = obtener_ordenes_falabella(estado=estado, dias=7, limit=20, offset=0)
                if isinstance(lote, list):
                    ordenes_fa.extend(lote)
            except: pass
        # Filtrar por fecha si aplica
        ordenes_filtradas = []
        if fd:
            for o in ordenes_fa:
                fc = (o.get("CreatedAt") or o.get("createdAt") or o.get("creation_date") or "")[:10]
                if fc and fd <= fc <= (fh or fd):
                    ordenes_filtradas.append(o)
        else:
            ordenes_filtradas = ordenes_fa

        primera = ordenes_filtradas[0] if ordenes_filtradas else (ordenes_fa[0] if ordenes_fa else None)
        keys = list(primera.keys()) if primera else []

        items_keys = None
        items_primer_precio = None
        if primera:
            try:
                order_id = primera.get("OrderId") or primera.get("OrderNumber") or primera.get("OrderItemId")
                if order_id:
                    items = obtener_items_orden_falabella(order_id) or []
                    if items:
                        items_keys = list(items[0].keys())
                        # Buscar campos que parezcan precio
                        for k in items_keys:
                            if 'price' in k.lower() or 'precio' in k.lower() or 'paid' in k.lower() or 'amount' in k.lower():
                                items_primer_precio = items_primer_precio or {}
                                items_primer_precio[k] = items[0].get(k)
            except Exception as e:
                items_keys = f"error: {str(e)[:100]}"

        resultado["canales"]["falabella"] = {
            "cantidad_ordenes_brutas": len(ordenes_fa),
            "cantidad_filtradas_por_fecha": len(ordenes_filtradas),
            "primera_orden_keys": keys,
            "primera_orden_resumen": {
                "OrderId": primera.get("OrderId") if primera else None,
                "OrderNumber": primera.get("OrderNumber") if primera else None,
                "Price": primera.get("Price") if primera else None,
                "PaidPrice": primera.get("PaidPrice") if primera else None,
                "Subtotal": primera.get("Subtotal") if primera else None,
                "CreatedAt": primera.get("CreatedAt") if primera else None,
            } if primera else None,
            "items_keys": items_keys,
            "items_campos_precio": items_primer_precio,
        }
    except Exception as e:
        import traceback
        resultado["canales"]["falabella"] = {"error": str(e), "trace": traceback.format_exc()[:300]}

    # ─── PARIS ────────────────────────────────────────────────────────────
    try:
        from paris import obtener_ordenes_paris_todas
        ordenes_pa = obtener_ordenes_paris_todas(dias=7, max_paginas=5) or []
        # Filtrar por fecha
        ordenes_filtradas_pa = []
        if fd:
            for o in ordenes_pa:
                # Paris devuelve órdenes con campos varios
                fc = (o.get("createdAt") or o.get("CreatedAt") or o.get("originOrderDate") or "")[:10]
                if fc and fd <= fc <= (fh or fd):
                    ordenes_filtradas_pa.append(o)
        else:
            ordenes_filtradas_pa = ordenes_pa

        primera = ordenes_filtradas_pa[0] if ordenes_filtradas_pa else (ordenes_pa[0] if ordenes_pa else None)
        keys = list(primera.keys()) if primera else []

        # Buscar precio en estructura Paris
        primera_resumen = {}
        if primera:
            for k in ('subOrderNumber', 'orderNumber', 'createdAt', 'originOrderDate',
                      'totalAmount', 'amount', 'price', 'items', 'subOrders'):
                if k in primera:
                    val = primera[k]
                    if isinstance(val, (list, dict)):
                        val = f"<{type(val).__name__} len={len(val) if hasattr(val,'__len__') else '?'}>"
                    primera_resumen[k] = val

        # Si hay subOrders, ver primer item
        primer_item_keys = None
        primer_item_precio = None
        if primera:
            try:
                sub_orders = primera.get("subOrders") or [primera]
                if sub_orders:
                    items = sub_orders[0].get("items") if isinstance(sub_orders[0], dict) else []
                    if items:
                        primer_item_keys = list(items[0].keys())
                        for k in primer_item_keys:
                            if 'price' in k.lower() or 'amount' in k.lower() or 'total' in k.lower():
                                primer_item_precio = primer_item_precio or {}
                                primer_item_precio[k] = items[0].get(k)
            except Exception as e:
                primer_item_keys = f"error: {str(e)[:100]}"

        resultado["canales"]["paris"] = {
            "cantidad_ordenes_brutas": len(ordenes_pa),
            "cantidad_filtradas_por_fecha": len(ordenes_filtradas_pa),
            "primera_orden_keys": keys,
            "primera_orden_resumen": primera_resumen,
            "primer_item_keys": primer_item_keys,
            "primer_item_campos_precio": primer_item_precio,
        }
    except Exception as e:
        import traceback
        resultado["canales"]["paris"] = {"error": str(e), "trace": traceback.format_exc()[:300]}

    return jsonify(resultado)


@app.route("/admin/rls/debug_ventas_dia", methods=["GET"])
def admin_rls_debug_ventas_dia():
    """Debug: lista TODOS los movimientos de venta del día actual (o el día especificado)
    incluyendo canal, origen, cantidad y precio donde sea posible.
    """
    bypass_token = os.environ.get("ADMIN_BYPASS_TOKEN", "lcTDX2fjcH3hiZFvv8apEwPd-eiCIqFdkKqJIVy1bVw")
    if not session.get("logged") and not session.get("is_lusync_admin") and request.args.get("token") != bypass_token:
        return jsonify({"error": "no autorizado"}), 401

    fecha = request.args.get("fecha", "")  # YYYY-MM-DD; vacío = hoy

    try:
        from inventario import get_conn, release_conn
        conn = get_conn(is_admin=True); cur = conn.cursor()

        where_fecha = ""
        params = []
        if fecha:
            where_fecha = "AND DATE(fecha) = %s"
            params = [fecha]
        else:
            where_fecha = "AND DATE(fecha) = CURRENT_DATE"

        # Lista CRUDA todos los movimientos de tipo salida del día
        cur.execute(f"""
            SELECT id, fecha, sku, cantidad, canal, origen_registro, motivo,
                   COALESCE(numero_orden, '') AS orden, COALESCE(usuario, '') AS usuario,
                   tenant_id
            FROM movimientos
            WHERE tipo = 'salida' {where_fecha}
            ORDER BY fecha DESC
        """, params)

        cols = ["id", "fecha", "sku", "cantidad", "canal", "origen", "motivo", "orden", "usuario", "tenant_id"]
        rows = cur.fetchall()
        movs = []
        for r in rows:
            d = dict(zip(cols, r))
            if isinstance(d["fecha"], (str,)):
                d["fecha"] = str(d["fecha"])
            elif d["fecha"]:
                d["fecha"] = d["fecha"].isoformat()
            movs.append(d)

        # Agrupar por canal
        from collections import defaultdict
        por_canal = defaultdict(lambda: {"unidades": 0, "movs": 0})
        for m in movs:
            c = m["canal"] or "(sin canal)"
            por_canal[c]["unidades"] += abs(m["cantidad"] or 0)
            por_canal[c]["movs"] += 1

        # Cuáles cuentan como ventas reales según CANALES_VENTA_ACTIVOS
        from inventario import CANALES_VENTA_ACTIVOS
        ventas_validas = [m for m in movs if m["canal"] in CANALES_VENTA_ACTIVOS]

        cur.close(); release_conn(conn)

        return jsonify({
            "fecha_consultada": fecha or "HOY",
            "total_movimientos_salida": len(movs),
            "total_ventas_validas_canales_marketplace": len(ventas_validas),
            "unidades_validas": sum(abs(m["cantidad"] or 0) for m in ventas_validas),
            "por_canal": dict(por_canal),
            "canales_validos_para_venta": list(CANALES_VENTA_ACTIVOS),
            "movimientos_detalle": movs[:50]
        })
    except Exception as e:
        import traceback
        return jsonify({"error": str(e), "trace": traceback.format_exc()[:500]}), 500


@app.route("/admin/rls/comparar_movimientos", methods=["GET"])
def admin_rls_comparar_movimientos():
    """Compara cuántos movimientos ve Babymine (tenant=1) vs admin (bypass).
    Si los números difieren, hay movimientos sin tenant_id correctamente seteado.
    """
    bypass_token = os.environ.get("ADMIN_BYPASS_TOKEN", "lcTDX2fjcH3hiZFvv8apEwPd-eiCIqFdkKqJIVy1bVw")
    if not session.get("logged") and not session.get("is_lusync_admin") and request.args.get("token") != bypass_token:
        return jsonify({"error": "no autorizado"}), 401
    try:
        from inventario import get_conn, release_conn
        from datetime import datetime, timedelta

        # Vista admin (todo)
        conn_a = get_conn(is_admin=True); cur_a = conn_a.cursor()

        cur_a.execute("SELECT COUNT(*) FROM movimientos")
        total_admin = cur_a.fetchone()[0]

        cur_a.execute("SELECT tenant_id, COUNT(*) FROM movimientos GROUP BY tenant_id ORDER BY tenant_id")
        por_tenant = {r[0]: r[1] for r in cur_a.fetchall()}

        cur_a.execute("""
            SELECT tipo, COUNT(*) FROM movimientos
            WHERE fecha >= NOW() - INTERVAL '30 days'
            GROUP BY tipo
            ORDER BY COUNT(*) DESC
        """)
        por_tipo_30d = {r[0]: r[1] for r in cur_a.fetchall()}

        cur_a.execute("""
            SELECT origen_registro, COUNT(*) FROM movimientos
            WHERE fecha >= NOW() - INTERVAL '30 days'
            GROUP BY origen_registro
            ORDER BY COUNT(*) DESC
        """)
        por_origen_30d = {(r[0] or "sin_origen"): r[1] for r in cur_a.fetchall()}

        cur_a.execute("""
            SELECT canal, COUNT(*) FROM movimientos
            WHERE fecha >= NOW() - INTERVAL '30 days' AND tipo = 'venta'
            GROUP BY canal
            ORDER BY COUNT(*) DESC
        """)
        ventas_por_canal_30d = {(r[0] or "sin_canal"): r[1] for r in cur_a.fetchall()}

        cur_a.execute("SELECT MAX(fecha), MIN(fecha) FROM movimientos WHERE tipo='venta'")
        max_v, min_v = cur_a.fetchone()

        cur_a.close(); release_conn(conn_a)

        # Vista tenant 1 (Babymine)
        conn_t = get_conn(tenant_id=1); cur_t = conn_t.cursor()
        cur_t.execute("SELECT COUNT(*) FROM movimientos")
        total_t1 = cur_t.fetchone()[0]
        cur_t.execute("SELECT COUNT(*) FROM movimientos WHERE fecha >= NOW() - INTERVAL '30 days' AND tipo='venta'")
        ventas_30d_t1 = cur_t.fetchone()[0]
        cur_t.close(); release_conn(conn_t)

        return jsonify({
            "vista_admin_bypass": {
                "total_movimientos": total_admin,
                "distribucion_por_tenant": por_tenant,
                "fecha_max_venta": max_v.isoformat() if max_v else None,
                "fecha_min_venta": min_v.isoformat() if min_v else None,
                "ultimos_30d_por_tipo": por_tipo_30d,
                "ultimos_30d_por_origen": por_origen_30d,
                "ventas_30d_por_canal": ventas_por_canal_30d,
            },
            "vista_tenant_1_babymine": {
                "total_movimientos": total_t1,
                "ventas_ultimos_30d": ventas_30d_t1,
            },
            "diferencia": {
                "movimientos_invisibles_para_t1": total_admin - total_t1,
                "diagnostico": "Si hay diferencia, hay movimientos con tenant_id != 1 o NULL"
            }
        })
    except Exception as e:
        import traceback
        return jsonify({"error": str(e), "trace": traceback.format_exc()[:500]}), 500


