@app.route("/admin/debug_meli_stock_locations")
def admin_debug_meli_stock_locations():
    """
    Debug completo: para un user_product_id de MELI, devuelve:
    - Estado del item (logistic_type, tags, status)
    - Stock locations (Full + selling_address)
    - x-version header
    Útil para diagnosticar convivencia Full/Flex.

    Uso: ?user_product_id=MLCU3179719354&token=XXX
         ó ?item_id=MLC1529109001&token=XXX (busca user_product_ids de variantes)
    """
    bypass_token = os.environ.get("ADMIN_BYPASS_TOKEN", "lcTDX2fjcH3hiZFvv8apEwPd-eiCIqFdkKqJIVy1bVw")
    if request.args.get("token") != bypass_token and not session.get("logged"):
        return jsonify({"error": "no autorizado"}), 401

    upid = request.args.get("user_product_id", "").strip()
    item_id = request.args.get("item_id", "").strip()

    try:
        import requests as _req
        from mercadolibre import meli_headers, MELI_API_URL

        resultado = {}

        # Si se pasa item_id, primero traer todos los user_product_id de variantes
        if item_id and not upid:
            r_item = _req.get(
                f"{MELI_API_URL}/items/{item_id}?include_attributes=all",
                headers=meli_headers(), timeout=20
            )
            if r_item.status_code != 200:
                return jsonify({"error": f"GET item falló: {r_item.status_code}", "body": r_item.text[:500]}), 500
            item = r_item.json()
            resultado["item"] = {
                "id": item_id,
                "logistic_type": item.get("shipping", {}).get("logistic_type"),
                "tags": item.get("tags", []),
                "status": item.get("status"),
                "sub_status": item.get("sub_status"),
                "tiene_self_service_in": "self_service_in" in (item.get("tags") or []),
                "user_product_id_item": item.get("user_product_id"),
                "inventory_id": item.get("inventory_id"),
            }

            # Recopilar user_product_ids de variantes
            variantes_info = []
            for v in item.get("variations") or []:
                v_upid = v.get("user_product_id")
                v_color = next((ac.get("value_name") for ac in v.get("attribute_combinations",[])
                                if ac.get("id") == "COLOR"), None)
                v_seller_sku = next((a.get("value_name") for a in v.get("attributes",[])
                                     if a.get("id") == "SELLER_SKU"), None)
                v_info = {
                    "variation_id": v.get("id"),
                    "user_product_id": v_upid,
                    "inventory_id": v.get("inventory_id"),
                    "color": v_color,
                    "seller_sku": v_seller_sku,
                    "available_quantity": v.get("available_quantity"),
                }
                # Para cada variante, traer su stock
                if v_upid:
                    try:
                        r_st = _req.get(
                            f"{MELI_API_URL}/user-products/{v_upid}/stock",
                            headers=meli_headers(), timeout=15
                        )
                        v_info["stock_status_code"] = r_st.status_code
                        v_info["x_version"] = r_st.headers.get("x-version")
                        if r_st.status_code == 200:
                            v_info["stock_data"] = r_st.json()
                        else:
                            v_info["stock_error_body"] = r_st.text[:300]
                    except Exception as e:
                        v_info["stock_error"] = str(e)
                variantes_info.append(v_info)
            resultado["variantes"] = variantes_info

        elif upid:
            # Solo consultar el user_product_id directamente
            r_st = _req.get(
                f"{MELI_API_URL}/user-products/{upid}/stock",
                headers=meli_headers(), timeout=15
            )
            resultado["user_product_id"] = upid
            resultado["status_code"] = r_st.status_code
            resultado["x_version"] = r_st.headers.get("x-version")
            if r_st.status_code == 200:
                resultado["stock_data"] = r_st.json()
            else:
                resultado["error_body"] = r_st.text[:500]
        else:
            return jsonify({"error": "Pasa ?item_id=XXX ó ?user_product_id=XXX"}), 400

        return jsonify(resultado)
    except Exception as e:
        import traceback
        return jsonify({"error": str(e), "trace": traceback.format_exc()}), 500


@app.route("/admin/limpiar_mapeos_huerfanos", methods=["GET", "POST"])
def admin_limpiar_mapeos_huerfanos():
    """
    Identifica y elimina mapeos huérfanos en sku_mapeo_canal:
    - Mapeos sin item_id_canal cuando otro mapeo del mismo (sku_lusync, canal) sí lo tiene
    - Mapeos con item_id_canal idénticos pero sku_lusync distintos (decide cuál mantener)

    Uso: ?token=XXX&dry_run=1 (default) o dry_run=0 para ejecutar
    """
    bypass_token = os.environ.get("ADMIN_BYPASS_TOKEN", "lcTDX2fjcH3hiZFvv8apEwPd-eiCIqFdkKqJIVy1bVw")
    if request.args.get("token") != bypass_token and not session.get("logged"):
        return jsonify({"error": "no autorizado"}), 401

    dry_run = request.args.get("dry_run", "1") == "1"
    canal_filter = request.args.get("canal", "").strip().lower()

    try:
        from inventario import get_conn
        conn = get_conn(); cur = conn.cursor()

        # Obtener todos los mapeos activos
        sql = """SELECT id, canal, sku_lusync, sku_canal, item_id_canal, notas
                 FROM sku_mapeo_canal WHERE activo=TRUE"""
        params = []
        if canal_filter:
            sql += " AND canal=%s"
            params.append(canal_filter)
        cur.execute(sql, params)
        rows = cur.fetchall()

        # Agrupar por (canal, sku_lusync) para detectar huérfanos
        # Si hay un mapeo con item_id_canal lleno, los que tienen NULL son huérfanos a eliminar
        from collections import defaultdict
        grupos = defaultdict(list)
        for r in rows:
            key = (r[1], (r[2] or "").upper())  # (canal, sku_lusync)
            grupos[key].append({
                "id": r[0], "canal": r[1], "sku_lusync": r[2],
                "sku_canal": r[3], "item_id_canal": r[4], "notas": r[5]
            })

        huerfanos_a_eliminar = []
        for (canal, sku_lus), mapeos in grupos.items():
            tiene_con_id = any(m["item_id_canal"] for m in mapeos)
            if tiene_con_id:
                # Si hay al menos uno con item_id_canal, los que NO lo tienen son huérfanos
                for m in mapeos:
                    if not m["item_id_canal"]:
                        huerfanos_a_eliminar.append(m)

        eliminados = []
        if not dry_run:
            for m in huerfanos_a_eliminar:
                cur.execute("DELETE FROM sku_mapeo_canal WHERE id=%s", (m["id"],))
                eliminados.append(m["id"])
            conn.commit()

        cur.close(); conn.close()

        return jsonify({
            "dry_run": dry_run,
            "huerfanos_detectados": len(huerfanos_a_eliminar),
            "huerfanos": huerfanos_a_eliminar,
            "ids_eliminados": eliminados,
        })
    except Exception as e:
        import traceback
        return jsonify({"error": str(e), "trace": traceback.format_exc()}), 500


@app.route("/admin/debug_paris_stock_sku")
def admin_debug_paris_stock_sku():
    """Consulta el stock de un SKU específico en Paris."""
    bypass_token = os.environ.get("ADMIN_BYPASS_TOKEN", "lcTDX2fjcH3hiZFvv8apEwPd-eiCIqFdkKqJIVy1bVw")
    if request.args.get("token") != bypass_token and not session.get("logged"):
        return jsonify({"error": "no autorizado"}), 401
    sku = request.args.get("sku", "").strip()
    if not sku:
        return jsonify({"error": "Pasa ?sku=XXX"}), 400
    try:
        from paris import obtener_stock_paris, obtener_productos_paris
        # Obtener todo el stock paginado y filtrar por SKU
        encontrados = []
        offset = 0
        while True:
            data = obtener_stock_paris(limite=100, offset=offset)
            if not data:
                break
            # Paris devuelve la lista en "skus" (no en "items")
            if isinstance(data, dict):
                items = data.get("skus") or data.get("items") or []
            elif isinstance(data, list):
                items = data
            else:
                items = []
            if not items:
                break
            for it in items:
                # Paris devuelve "sku_seller" (con guión bajo), no sellerSku
                matches_sku = (
                    str(it.get("sku_seller", "")).upper().strip() == sku.upper().strip()
                    or str(it.get("sellerSku", "")).upper().strip() == sku.upper().strip()
                    or str(it.get("sku", "")).upper().strip() == sku.upper().strip()
                    or str(it.get("offerSku", "")).upper().strip() == sku.upper().strip()
                )
                if matches_sku:
                    encontrados.append(it)
            if len(items) < 100:
                break
            offset += 100
            if offset > 5000:
                break

        return jsonify({
            "sku_buscado": sku,
            "encontrados": encontrados,
            "total": len(encontrados)
        })
    except Exception as e:
        import traceback
        return jsonify({"error": str(e), "trace": traceback.format_exc()}), 500


@app.route("/admin/verificar_stock_todos_canales")
def admin_verificar_stock_todos_canales():
    """
    Consulta el stock real en TODOS los canales para un SKU específico.
    Compara con el stock de Lusync.
    Uso: ?sku=XXX&token=YYY
    """
    bypass_token = os.environ.get("ADMIN_BYPASS_TOKEN", "lcTDX2fjcH3hiZFvv8apEwPd-eiCIqFdkKqJIVy1bVw")
    if request.args.get("token") != bypass_token and not session.get("logged"):
        return jsonify({"error": "no autorizado"}), 401
    sku = request.args.get("sku", "").strip()
    if not sku:
        return jsonify({"error": "Pasa ?sku=XXX"}), 400

    resultado = {"sku": sku, "canales": {}}

    # 1. Lusync
    try:
        from inventario import get_conn
        conn = get_conn(); cur = conn.cursor()
        cur.execute("""
            SELECT sb.bodega_codigo, b.nombre, b.tipo, sb.cantidad
            FROM stock_bodega sb
            JOIN bodegas b ON b.codigo = sb.bodega_codigo
            WHERE sb.sku = %s
        """, (sku,))
        bodegas = [{"bodega": r[0], "nombre": r[1], "tipo": r[2], "cantidad": int(r[3])} for r in cur.fetchall()]
        propio = sum(b["cantidad"] for b in bodegas if b["tipo"] == "propia")
        full = sum(b["cantidad"] for b in bodegas if b["tipo"] in ("fulfillment", "transito"))
        cur.execute("SELECT stock FROM productos WHERE sku=%s", (sku,))
        row = cur.fetchone()
        prod_stock = int(row[0]) if row else 0
        cur.close(); conn.close()
        resultado["canales"]["lusync"] = {
            "stock_disponible_propio": propio,
            "stock_full": full,
            "productos_stock": prod_stock,
            "bodegas": bodegas
        }
    except Exception as e:
        resultado["canales"]["lusync"] = {"error": str(e)}

    # 2. MELI - todas sus publicaciones
    try:
        import requests as _req
        from inventario import get_conn
        from mercadolibre import meli_headers, MELI_API_URL
        conn = get_conn(); cur = conn.cursor()
        cur.execute("""
            SELECT item_id_canal FROM sku_mapeo_canal
            WHERE canal='mercadolibre' AND sku_lusync=%s AND activo=TRUE AND item_id_canal IS NOT NULL
        """, (sku,))
        items_meli = [r[0] for r in cur.fetchall()]
        cur.close(); conn.close()

        meli_data = []
        for item_id in items_meli:
            try:
                r = _req.get(f"{MELI_API_URL}/items/{item_id}?include_attributes=all",
                            headers=meli_headers(), timeout=15)
                if r.status_code == 200:
                    d = r.json()
                    info = {
                        "item_id": item_id,
                        "catalog_listing": d.get("catalog_listing", False),
                        "available_quantity": d.get("available_quantity"),
                        "status": d.get("status"),
                    }
                    # Si tiene variantes, traer stock de cada una
                    variations = d.get("variations") or []
                    if variations:
                        info["variantes"] = []
                        for v in variations:
                            v_seller_sku = next((a.get("value_name") for a in (v.get("attributes") or [])
                                                 if a.get("id") == "SELLER_SKU"), None)
                            upid = v.get("user_product_id")
                            v_info = {
                                "variation_id": v.get("id"),
                                "user_product_id": upid,
                                "seller_sku": v_seller_sku,
                                "available_quantity": v.get("available_quantity"),
                            }
                            if upid:
                                try:
                                    r_st = _req.get(f"{MELI_API_URL}/user-products/{upid}/stock",
                                                    headers=meli_headers(), timeout=10)
                                    if r_st.status_code == 200:
                                        v_info["locations"] = r_st.json().get("locations", [])
                                except Exception:
                                    pass
                            info["variantes"].append(v_info)
                    meli_data.append(info)
                else:
                    meli_data.append({"item_id": item_id, "error": f"HTTP {r.status_code}"})
            except Exception as e:
                meli_data.append({"item_id": item_id, "error": str(e)})
        resultado["canales"]["mercadolibre"] = meli_data
    except Exception as e:
        resultado["canales"]["mercadolibre"] = {"error": str(e)}

    # 3. Paris
    try:
        from paris import obtener_stock_paris
        encontrados = []
        offset = 0
        while True:
            data = obtener_stock_paris(limite=100, offset=offset)
            if not data: break
            if isinstance(data, dict):
                items = data.get("skus") or data.get("items") or []
            elif isinstance(data, list):
                items = data
            else:
                items = []
            if not items: break
            for it in items:
                # Paris devuelve "sku_seller" (con guión bajo), no sellerSku
                if (str(it.get("sku_seller", "")).upper().strip() == sku.upper()
                    or str(it.get("sellerSku", "")).upper().strip() == sku.upper()
                    or str(it.get("sku", "")).upper().strip() == sku.upper()
                    or str(it.get("offerSku", "")).upper().strip() == sku.upper()):
                    encontrados.append(it)
            if len(items) < 100: break
            offset += 100
            if offset > 5000: break
        resultado["canales"]["paris"] = encontrados or "no encontrado"
    except Exception as e:
        resultado["canales"]["paris"] = {"error": str(e)}

    # 4. Falabella
    try:
        from falabella import llamar_api_falabella
        r = llamar_api_falabella("GetProducts", params={"Filter": "all", "SkuSellerList": sku}, formato="JSON")
        if r.get("ok"):
            resultado["canales"]["falabella"] = r.get("data", {}).get("SuccessResponse", {}).get("Body", {})
        else:
            resultado["canales"]["falabella"] = {"error": r.get("error")}
    except Exception as e:
        resultado["canales"]["falabella"] = {"error": str(e)}

    # 5. Walmart
    try:
        from walmart import obtener_inventario_walmart
        inv = obtener_inventario_walmart(sku)
        resultado["canales"]["walmart"] = inv
    except Exception as e:
        resultado["canales"]["walmart"] = {"error": str(e)}

    # 6. Ripley
    try:
        from ripley import obtener_stock_ripley
        st = obtener_stock_ripley(sku)
        resultado["canales"]["ripley"] = st
    except Exception as e:
        resultado["canales"]["ripley"] = {"error": str(e)}

    # 7. Woo
    try:
        from woo import obtener_stock_producto_woo
        wst = obtener_stock_producto_woo(sku)
        resultado["canales"]["woo"] = wst
    except Exception as e:
        resultado["canales"]["woo"] = {"error": str(e)}

    return jsonify(resultado)


@app.route("/admin/enriquecer_mapeos_paris")
def admin_enriquecer_mapeos_paris():
    """
    Enriquece los mapeos de Paris que están huérfanos (sin item_id_canal).
    Consulta la API de Paris y para cada sku_seller encontrado, llena el item_id_canal.
    Uso: ?token=XXX&dry_run=1 (default) o dry_run=0 para ejecutar
    """
    bypass_token = os.environ.get("ADMIN_BYPASS_TOKEN", "lcTDX2fjcH3hiZFvv8apEwPd-eiCIqFdkKqJIVy1bVw")
    if request.args.get("token") != bypass_token and not session.get("logged"):
        return jsonify({"error": "no autorizado"}), 401
    dry_run = request.args.get("dry_run", "1") == "1"

    try:
        from paris import obtener_stock_paris
        from inventario import get_conn

        # 1. Recopilar todos los SKUs de Paris (sku_seller -> sku Paris item_id)
        paris_lookup = {}  # {sku_seller_upper: paris_item_sku}
        offset = 0
        while True:
            data = obtener_stock_paris(limite=100, offset=offset)
            if not data:
                break
            if isinstance(data, dict):
                items = data.get("skus") or data.get("items") or []
            elif isinstance(data, list):
                items = data
            else:
                items = []
            if not items:
                break
            for it in items:
                sku_seller = str(it.get("sku_seller") or "").upper().strip()
                paris_sku = str(it.get("sku") or "").strip()
                if sku_seller and paris_sku:
                    paris_lookup[sku_seller] = paris_sku
            if len(items) < 100:
                break
            offset += 100
            if offset > 5000:
                break

        # 2. Buscar mapeos huérfanos de Paris
        conn = get_conn(); cur = conn.cursor()
        cur.execute("""
            SELECT id, sku_lusync, sku_canal
            FROM sku_mapeo_canal
            WHERE canal='paris' AND activo=TRUE AND item_id_canal IS NULL
        """)
        huerfanos = [{"id": r[0], "sku_lusync": r[1], "sku_canal": r[2]} for r in cur.fetchall()]

        # 3. Para cada huérfano, intentar enriquecer
        enriquecidos = []
        sin_match = []
        for h in huerfanos:
            # Intentar match por sku_lusync, sku_canal
            for key in [h["sku_lusync"], h["sku_canal"]]:
                if not key:
                    continue
                key_up = key.upper().strip()
                if key_up in paris_lookup:
                    paris_sku = paris_lookup[key_up]
                    enriquecidos.append({
                        **h,
                        "match_por": key,
                        "sku_seller_paris": key_up,
                        "item_id_canal_paris": paris_sku
                    })
                    if not dry_run:
                        cur.execute("""
                            UPDATE sku_mapeo_canal
                            SET item_id_canal = %s,
                                sku_canal = %s,
                                notas = COALESCE(notas,'') || ' | enriquecido_paris',
                                actualizado_at = NOW()
                            WHERE id = %s
                        """, (paris_sku, key_up, h["id"]))
                    break
            else:
                sin_match.append(h)

        if not dry_run:
            conn.commit()
        cur.close(); conn.close()

        return jsonify({
            "dry_run": dry_run,
            "huerfanos_paris": len(huerfanos),
            "enriquecidos": enriquecidos,
            "sin_match_en_paris": sin_match,
            "total_skus_paris": len(paris_lookup)
        })
    except Exception as e:
        import traceback
        return jsonify({"error": str(e), "trace": traceback.format_exc()}), 500


@app.route("/admin/debug_paris_actualizar_raw")
def admin_debug_paris_actualizar_raw():
    """
    Hace una llamada directa a la API de Paris para actualizar stock,
    y devuelve el payload + respuesta completa para diagnosticar.
    Uso: ?sku=PBEAMG001&cantidad=7&token=YYY
    """
    bypass_token = os.environ.get("ADMIN_BYPASS_TOKEN", "lcTDX2fjcH3hiZFvv8apEwPd-eiCIqFdkKqJIVy1bVw")
    if request.args.get("token") != bypass_token and not session.get("logged"):
        return jsonify({"error": "no autorizado"}), 401
    sku = request.args.get("sku", "").strip()
    cantidad = int(request.args.get("cantidad", "0"))
    if not sku:
        return jsonify({"error": "Pasa ?sku=XXX&cantidad=N"}), 400

    try:
        from inventario import get_conn
        conn = get_conn(); cur = conn.cursor()
        cur.execute("""
            SELECT id, sku_canal, item_id_canal, notas
            FROM sku_mapeo_canal
            WHERE canal='paris' AND sku_lusync=%s AND activo=TRUE
        """, (sku,))
        mapeos = [{"id": r[0], "sku_canal": r[1], "item_id_canal": r[2], "notas": r[3]} for r in cur.fetchall()]
        cur.close(); conn.close()

        # Llamar directamente con request a la API
        import requests as _req
        from paris import paris_headers, PARIS_BASE_URL

        resultados = []
        for m in mapeos:
            paris_sku = m["item_id_canal"]
            sku_seller = m["sku_canal"]
            if not paris_sku:
                resultados.append({"mapeo": m, "skip": "sin item_id_canal"})
                continue

            # Probar varios endpoints/payloads de Paris
            # Endpoint 1: PUT /sellers/v1/inventory/sku/{sku} con quantity
            # Endpoint 2: POST /sellers/v1/inventory con array
            # Necesitamos ver cuál usa la función actual

            # Primero ver el payload que actualizar_stock_paris ya usa via función
            from paris import actualizar_stock_paris
            try:
                # Llamar la función real y capturar logs
                import io, sys
                old_stdout = sys.stdout
                sys.stdout = capt = io.StringIO()
                try:
                    res = actualizar_stock_paris(sku, cantidad)
                finally:
                    sys.stdout = old_stdout
                resultados.append({
                    "mapeo": m,
                    "resultado_funcion": res,
                    "logs_funcion": capt.getvalue()
                })
            except Exception as e:
                import traceback
                resultados.append({"mapeo": m, "error": str(e), "trace": traceback.format_exc()})

        return jsonify({
            "sku": sku,
            "cantidad": cantidad,
            "mapeos": mapeos,
            "resultados": resultados
        })
    except Exception as e:
        import traceback
        return jsonify({"error": str(e), "trace": traceback.format_exc()}), 500


