@app.route("/pos/entrada_lote", methods=["POST"])
def pos_entrada_lote():
    """Entrada de múltiples SKUs asociados a un único documento (factura/invoice/guía).
    Body JSON:
    {
        "clave_admin": "...",
        "documento": { "numero_doc":"F-12345", "tipo_doc":"factura",
                       "proveedor":"Proveedor SA", "fecha_doc":"2026-05-10",
                       "moneda":"CLP", "monto_total":500000,
                       "monto_neto":420168, "iva":79832, "notas":"..." },
        "items": [
            { "sku":"SKU001", "cantidad":10, "costo_unitario":15000,
              "bodega_destino":"CENTRAL", "notas_linea":"" },
            ...
        ]
    }
    """
    data = request.json or {}
    clave_correcta = os.environ.get("LUSYNC_ADMIN_KEY", "")
    clave_recibida = (data.get("clave_admin") or "").strip()
    if not clave_correcta:
        return jsonify({"error": "LUSYNC_ADMIN_KEY no configurada"}), 500
    if clave_recibida != clave_correcta:
        registrar_audit(session.get("usuario","Sistema"), request.remote_addr,
                        "pos_entrada_DENEGADA", detalle=f"doc={data.get('documento',{}).get('numero_doc')}")
        return jsonify({"error": "Clave admin incorrecta"}), 403

    doc_data = data.get("documento") or {}
    items    = data.get("items") or []
    if not doc_data.get("numero_doc"):
        return jsonify({"error": "numero_doc es obligatorio"}), 400
    if not items:
        return jsonify({"error": "Debe incluir al menos un ítem"}), 400

    usuario  = session.get("usuario", "Luis Padilla")
    from inventario import (crear_documento_compra, registrar_linea_documento,
                             ajustar_stock_bodega, get_conn as _get_conn)

    # 1. Crear / recuperar el documento de compra
    try:
        doc_id = crear_documento_compra(
            numero_doc  = doc_data["numero_doc"],
            tipo_doc    = doc_data.get("tipo_doc","factura"),
            proveedor   = doc_data.get("proveedor",""),
            fecha_doc   = doc_data.get("fecha_doc") or None,
            moneda      = doc_data.get("moneda","CLP"),
            monto_total = doc_data.get("monto_total") or None,
            monto_neto  = doc_data.get("monto_neto") or None,
            iva         = doc_data.get("iva") or None,
            notas       = doc_data.get("notas",""),
            usuario     = usuario
        )
    except Exception as e:
        return jsonify({"error": f"Error creando documento: {e}"}), 500

    productos_cache = {p["sku"]: p for p in cargar_productos()}
    resultados = []
    errores    = []

    # 2. Procesar cada ítem
    for item in items:
        sku      = (item.get("sku") or "").strip()
        cantidad = int(item.get("cantidad") or 0)
        costo_u  = float(item.get("costo_unitario") or 0) or None
        bodega   = (item.get("bodega_destino") or "CENTRAL").strip()

        if not sku or cantidad <= 0:
            errores.append({"sku": sku, "error": "SKU inválido o cantidad 0"})
            continue

        p = productos_cache.get(sku)
        if not p:
            errores.append({"sku": sku, "error": "Producto no encontrado"})
            continue

        # 2a. Ajustar stock en la bodega destino
        try:
            ajustar_stock_bodega(sku, bodega, cantidad)
        except Exception as e:
            errores.append({"sku": sku, "error": f"Error bodega: {e}"}); continue

        # 2b. Actualizar productos.stock (suma total de bodegas propias)
        p["stock"] += cantidad
        guardar_producto(p)

        # 2c. Registrar movimiento
        motivo = f"Entrada POS | Doc: {doc_data['numero_doc']} | Bodega: {bodega}"
        if costo_u:
            motivo += f" | Costo u.: ${costo_u:,.0f}"
        mov_id = registrar_movimiento(
            "entrada", sku, p["nombre"], cantidad, motivo,
            usuario=usuario, canal="Manual",
            documento_ref=doc_data["numero_doc"],
            origen_registro="pos"
        )

        # 2d. Linkear movimiento al documento de compra
        try:
            _c = _get_conn(); _cur = _c.cursor()
            _cur.execute("UPDATE movimientos SET documento_compra_id=%s WHERE id=%s", (doc_id, mov_id))
            _c.commit(); _cur.close(); _c.close()
        except Exception: pass

        # 2e. Registrar línea en movimientos_documento (trazabilidad de costeo)
        try:
            registrar_linea_documento(
                documento_id   = doc_id,
                movimiento_id  = mov_id,
                sku            = sku,
                nombre         = p["nombre"],
                cantidad       = cantidad,
                costo_unitario = costo_u,
                bodega_destino = bodega,
                notas_linea    = item.get("notas_linea","")
            )
        except Exception as e:
            print(f"[POS] error linea doc: {e}")

        # 2f. Stock actualizado para sync
        try:
            _c = _get_conn(); _cur = _c.cursor()
            _cur.execute("""SELECT COALESCE(SUM(sb.cantidad),0) FROM stock_bodega sb
                            LEFT JOIN bodegas b ON b.codigo=sb.bodega_codigo
                        WHERE sb.sku=%s AND (b.tipo='propia' OR b.tipo IS NULL OR sb.bodega_codigo='CENTRAL')""", (sku,))
            stock_disp = int(_cur.fetchone()[0] or 0)
            _cur.close(); _c.close()
        except Exception:
            stock_disp = p["stock"]

        syncs = sincronizar_stock_marketplaces(sku, stock_disp, contexto="pos_entrada")
        resultados.append({"sku": sku, "nombre": p["nombre"], "cantidad": cantidad,
                           "bodega": bodega, "costo_unitario": costo_u,
                           "stock_disponible": stock_disp, "syncs": syncs})

    registrar_audit(usuario, request.remote_addr, "pos_entrada_lote",
                    entidad="productos",
                    detalle=f"doc={doc_data['numero_doc']} items={len(resultados)} errores={len(errores)}")

    return jsonify({
        "ok": True,
        "documento_id": doc_id,
        "numero_doc"  : doc_data["numero_doc"],
        "procesados"  : resultados,
        "errores"     : errores
    })


@app.route("/pos/salida_lote", methods=["POST"])
def pos_salida_lote():
    """Salida de múltiples SKUs (despacho físico, OC, transferencia, etc.).
    Body JSON:
    {
        "clave_admin": "...",
        "oc": "OC-2025-001",           -- documento de referencia para la salida
        "motivo": "Despacho bodega",   -- motivo libre
        "items": [
            { "sku":"SKU001", "cantidad":3, "bodega_origen":"CENTRAL" },
            ...
        ]
    }
    """
    data = request.json or {}
    clave_correcta = os.environ.get("LUSYNC_ADMIN_KEY", "")
    clave_recibida = (data.get("clave_admin") or "").strip()
    if not clave_correcta:
        return jsonify({"error": "LUSYNC_ADMIN_KEY no configurada"}), 500
    if clave_recibida != clave_correcta:
        registrar_audit(session.get("usuario","Sistema"), request.remote_addr,
                        "pos_salida_DENEGADA", detalle=f"oc={data.get('oc')}")
        return jsonify({"error": "Clave admin incorrecta"}), 403

    items    = data.get("items") or []
    oc       = (data.get("oc") or "").strip()
    motivo_g = (data.get("motivo") or "Salida manual POS").strip()
    usuario  = session.get("usuario", "Luis Padilla")

    if not items:
        return jsonify({"error": "Debe incluir al menos un ítem"}), 400

    from inventario import ajustar_stock_bodega, get_conn as _get_conn

    productos_cache = {p["sku"]: p for p in cargar_productos()}
    resultados = []; errores = []

    for item in items:
        sku      = (item.get("sku") or "").strip()
        cantidad = int(item.get("cantidad") or 0)
        bodega   = (item.get("bodega_origen") or "CENTRAL").strip()

        if not sku or cantidad <= 0:
            errores.append({"sku": sku, "error": "SKU inválido o cantidad 0"}); continue
        p = productos_cache.get(sku)
        if not p:
            errores.append({"sku": sku, "error": "Producto no encontrado"}); continue
        if p["stock"] < cantidad:
            errores.append({"sku": sku, "error": f"Stock insuficiente ({p['stock']} disponibles)"}); continue

        try:
            ajustar_stock_bodega(sku, bodega, -cantidad)
        except Exception as e:
            errores.append({"sku": sku, "error": f"Error bodega: {e}"}); continue

        p["stock"] -= cantidad
        guardar_producto(p)

        canal = _detectar_canal_por_oc(oc) or "Manual"
        motivo = f"{motivo_g} | OC: {oc}" if oc else motivo_g
        registrar_movimiento(
            "salida", sku, p["nombre"], cantidad, motivo,
            usuario=usuario, canal=canal,
            numero_orden=oc or None, documento_ref=oc or None,
            origen_registro="pos"
        )

        try:
            _c = _get_conn(); _cur = _c.cursor()
            _cur.execute("""SELECT COALESCE(SUM(sb.cantidad),0) FROM stock_bodega sb
                            LEFT JOIN bodegas b ON b.codigo=sb.bodega_codigo
                        WHERE sb.sku=%s AND (b.tipo='propia' OR b.tipo IS NULL OR sb.bodega_codigo='CENTRAL')""", (sku,))
            stock_disp = int(_cur.fetchone()[0] or 0)
            _cur.close(); _c.close()
        except Exception:
            stock_disp = p["stock"]

        syncs = sincronizar_stock_marketplaces(sku, stock_disp, contexto="pos_salida")
        resultados.append({"sku": sku, "nombre": p["nombre"], "cantidad": cantidad,
                           "bodega": bodega, "stock_disponible": stock_disp, "syncs": syncs})

    registrar_audit(usuario, request.remote_addr, "pos_salida_lote",
                    detalle=f"oc={oc} items={len(resultados)} errores={len(errores)}")
    return jsonify({"ok": True, "oc": oc, "procesados": resultados, "errores": errores})


@app.route("/pos/ajuste", methods=["POST"])
def pos_ajuste():
    """Ajuste manual de inventario (merma, daño, conteo físico, robo, vencimiento, otro).
    Body JSON:
    {
        "clave_admin": "...",
        "sku": "SKU001",
        "cantidad_ajuste": -5,         -- negativo = baja, positivo = alza
        "motivo_ajuste": "merma",      -- merma | daño | conteo_fisico | robo | vencimiento | otro
        "notas": "Producto mojado",
        "bodega": "CENTRAL"
    }
    """
    data = request.json or {}
    clave_correcta = os.environ.get("LUSYNC_ADMIN_KEY", "")
    clave_recibida = (data.get("clave_admin") or "").strip()
    if not clave_correcta:
        return jsonify({"error": "LUSYNC_ADMIN_KEY no configurada"}), 500
    if clave_recibida != clave_correcta:
        registrar_audit(session.get("usuario","Sistema"), request.remote_addr,
                        "pos_ajuste_DENEGADO", detalle=f"sku={data.get('sku')}")
        return jsonify({"error": "Clave admin incorrecta"}), 403

    sku             = (data.get("sku") or "").strip()
    cantidad_ajuste = int(data.get("cantidad_ajuste") or 0)
    motivo_ajuste   = (data.get("motivo_ajuste") or "otro").strip()
    notas           = (data.get("notas") or "").strip()
    bodega          = (data.get("bodega") or "CENTRAL").strip()
    usuario         = session.get("usuario", "Luis Padilla")

    MOTIVOS_VALIDOS = {"merma","daño","conteo_fisico","robo","vencimiento","otro"}
    if not sku:
        return jsonify({"error": "SKU obligatorio"}), 400
    if cantidad_ajuste == 0:
        return jsonify({"error": "cantidad_ajuste no puede ser 0"}), 400
    if motivo_ajuste not in MOTIVOS_VALIDOS:
        return jsonify({"error": f"motivo_ajuste debe ser uno de: {', '.join(MOTIVOS_VALIDOS)}"}), 400

    from inventario import (ajustar_stock_bodega, registrar_ajuste_inventario,
                             get_stock_bodega, get_conn as _get_conn)

    productos_cache = {p["sku"]: p for p in cargar_productos()}
    p = productos_cache.get(sku)
    if not p:
        return jsonify({"error": "Producto no encontrado"}), 404

    cantidad_antes = get_stock_bodega(sku, bodega) or 0

    # Validar que no quede negativo
    if (cantidad_antes + cantidad_ajuste) < 0:
        return jsonify({
            "error": f"Stock insuficiente en bodega {bodega}. Actual: {cantidad_antes}, ajuste: {cantidad_ajuste}"
        }), 400

    try:
        ajustar_stock_bodega(sku, bodega, cantidad_ajuste)
    except Exception as e:
        return jsonify({"error": f"Error ajustando bodega: {e}"}), 500

    # ajustar_stock_bodega() ya recalcula productos.stock como la suma real de
    # todas las bodegas (vía _recalcular_stock_total). NO volver a sumar el delta
    # sobre el cache (p["stock"]) porque ese cache puede estar viejo o incluir
    # fulfillment, lo que descuadra productos.stock vs las bodegas. Releemos el
    # valor ya recalculado para mantener todo consistente.
    try:
        from inventario import get_conn as _gc_stock
        _cs = _gc_stock(); _cur_s = _cs.cursor()
        _cur_s.execute("SELECT COALESCE(stock, 0) FROM productos WHERE sku = %s", (sku,))
        _row_s = _cur_s.fetchone()
        p["stock"] = int(_row_s[0]) if _row_s and _row_s[0] is not None else max(0, p["stock"] + cantidad_ajuste)
        _cur_s.close(); _cs.close()
    except Exception:
        # Si por algún motivo no se pudo releer, usar el cálculo manual como respaldo.
        p["stock"] = max(0, p["stock"] + cantidad_ajuste)

    tipo_mov = "entrada" if cantidad_ajuste > 0 else "salida"
    motivo_completo = f"Ajuste {motivo_ajuste} | Bodega: {bodega} | {notas}" if notas else f"Ajuste {motivo_ajuste} | Bodega: {bodega}"
    mov_id = registrar_movimiento(
        tipo_mov, sku, p["nombre"], abs(cantidad_ajuste), motivo_completo,
        usuario=usuario, canal="Ajuste",
        documento_ref=f"AJUSTE-{motivo_ajuste.upper()}",
        origen_registro="pos"
    )

    try:
        registrar_ajuste_inventario(
            sku=sku, nombre=p["nombre"],
            cantidad_antes=cantidad_antes,
            cantidad_ajuste=cantidad_ajuste,
            motivo_ajuste=motivo_ajuste, notas=notas,
            usuario=usuario, movimiento_id=mov_id
        )
    except Exception as e:
        print(f"[POS ajuste] error registrando ajuste tabla: {e}")

    try:
        _c = _get_conn(); _cur = _c.cursor()
        _cur.execute("""SELECT COALESCE(SUM(sb.cantidad),0) FROM stock_bodega sb
                        LEFT JOIN bodegas b ON b.codigo=sb.bodega_codigo
                        WHERE sb.sku=%s AND (b.tipo='propia' OR b.tipo IS NULL OR sb.bodega_codigo='CENTRAL')""", (sku,))
        stock_disp = int(_cur.fetchone()[0] or 0)
        _cur.close(); _c.close()
    except Exception:
        stock_disp = p["stock"]

    syncs = sincronizar_stock_marketplaces(sku, stock_disp, contexto="pos_ajuste")

    registrar_audit(usuario, request.remote_addr, f"pos_ajuste_{motivo_ajuste}",
                    entidad="productos",
                    detalle=f"sku={sku} antes={cantidad_antes} ajuste={cantidad_ajuste} despues={cantidad_antes+cantidad_ajuste}")

    return jsonify({
        "ok"              : True,
        "sku"             : sku,
        "nombre"          : p["nombre"],
        "bodega"          : bodega,
        "cantidad_antes"  : cantidad_antes,
        "cantidad_ajuste" : cantidad_ajuste,
        "cantidad_despues": cantidad_antes + cantidad_ajuste,
        "stock_disponible": stock_disp,
        "syncs"           : syncs
    })


@app.route("/pos/documentos", methods=["GET"])
def pos_listar_documentos():
    """Lista documentos de compra para el historial del POS."""
    from inventario import listar_documentos_compra
    limite   = int(request.args.get("limite", 30))
    offset   = int(request.args.get("offset", 0))
    tipo_doc = request.args.get("tipo_doc") or None
    docs = listar_documentos_compra(limite=limite, offset=offset, tipo_doc=tipo_doc)
    # Serializar fechas
    for d in docs:
        for k in ("fecha_doc","fecha_registro"):
            if d.get(k) and hasattr(d[k], "isoformat"):
                d[k] = d[k].isoformat()
        for k in ("monto_total","unidades_totales","lineas"):
            if d.get(k) is not None:
                d[k] = float(d[k]) if k == "monto_total" else int(d[k])
    return jsonify({"ok": True, "documentos": docs})


@app.route("/pos/documento/<numero_doc>", methods=["GET"])
def pos_detalle_documento(numero_doc):
    """Retorna el detalle completo de un documento (encabezado + líneas)."""
    from inventario import get_historial_documento
    doc = get_historial_documento(numero_doc)
    if not doc:
        return jsonify({"error": "Documento no encontrado"}), 404
    # Serializar fechas
    for k in ("fecha_doc","fecha_registro"):
        if doc.get(k) and hasattr(doc[k], "isoformat"):
            doc[k] = doc[k].isoformat()
    for linea in doc.get("lineas", []):
        for k in ("costo_unitario","costo_total_linea"):
            if linea.get(k) is not None:
                linea[k] = float(linea[k])
        if linea.get("fecha") and hasattr(linea["fecha"], "isoformat"):
            linea["fecha"] = linea["fecha"].isoformat()
    return jsonify({"ok": True, "documento": doc})


@app.route("/pos/ajustes_historial", methods=["GET"])
def pos_ajustes_historial():
    """Historial de ajustes de inventario para auditoría."""
    from inventario import get_conn as _get_conn
    limite = int(request.args.get("limite", 50))
    try:
        _c = _get_conn(); _cur = _c.cursor()
        _cur.execute("""
            SELECT id, sku, nombre, cantidad_antes, cantidad_ajuste, cantidad_despues,
                   motivo_ajuste, notas, usuario, fecha
            FROM ajustes_inventario
            ORDER BY fecha DESC LIMIT %s
        """, (limite,))
        cols = [d[0] for d in _cur.description]
        rows = [dict(zip(cols, r)) for r in _cur.fetchall()]
        _cur.close(); _c.close()
        for r in rows:
            if r.get("fecha") and hasattr(r["fecha"], "isoformat"):
                r["fecha"] = r["fecha"].isoformat()
        return jsonify({"ok": True, "ajustes": rows})
    except Exception as e:
        return jsonify({"error": str(e)}), 500


# ── ENDPOINT CONSOLIDADO PARA GRÁFICOS DEL MODAL DE VENTAS ──────────────────
@app.route("/ventas/graficos", methods=["GET"])
def ventas_graficos():
    """Devuelve todos los datos necesarios para los gráficos del modal:
    - ventas_por_dia: [{fecha, entradas, salidas, unidades}]
    - ventas_por_canal: [{canal, unidades, monto_est}]
    - top_productos: [{sku, nombre, unidades, monto_est}]
    - resumen: {total_ordenes, total_unidades, monto_estimado, canal_top, producto_top}
    """
    if not session.get("logged"):
        return jsonify({"error": "no autorizado"}), 401

    desde = request.args.get("desde") or request.args.get("fecha_desde") or ""
    hasta = request.args.get("hasta") or request.args.get("fecha_hasta") or ""

    try:
        from inventario import get_conn as _gc
        conn = _gc(); cur = conn.cursor()

        where = "m.tipo = 'salida' AND m.canal NOT IN ('Manual','Ajuste','Sistema')"
        params = []
        if desde:
            where += " AND DATE(m.fecha) >= %s"; params.append(desde)
        if hasta:
            where += " AND DATE(m.fecha) <= %s"; params.append(hasta)

        # 1. Ventas por día
        cur.execute(f"""
            SELECT DATE(m.fecha) AS dia,
                   COUNT(DISTINCT COALESCE(m.orden_id::text, m.numero_orden, m.id::text)) AS ordenes,
                   SUM(m.cantidad) AS unidades,
                   COALESCE(SUM(m.cantidad * COALESCE(p.precio_oferta, p.precio_normal, 0)), 0) AS monto
            FROM movimientos m
            LEFT JOIN productos p ON p.sku = m.sku
            WHERE {where}
            GROUP BY DATE(m.fecha)
            ORDER BY DATE(m.fecha)
        """, params)
        ventas_por_dia = [
            {"fecha": str(r[0]), "ordenes": int(r[1] or 0),
             "unidades": int(r[2] or 0), "monto": float(r[3] or 0)}
            for r in cur.fetchall()
        ]

        # 2. Ventas por canal
        cur.execute(f"""
            SELECT m.canal,
                   COUNT(DISTINCT COALESCE(m.orden_id::text, m.numero_orden, m.id::text)) AS ordenes,
                   SUM(m.cantidad) AS unidades,
                   COALESCE(SUM(m.cantidad * COALESCE(p.precio_oferta, p.precio_normal, 0)), 0) AS monto
            FROM movimientos m
            LEFT JOIN productos p ON p.sku = m.sku
            WHERE {where}
            GROUP BY m.canal
            ORDER BY unidades DESC
        """, params)
        ventas_por_canal = [
            {"canal": r[0] or "Otro", "ordenes": int(r[1] or 0),
             "unidades": int(r[2] or 0), "monto": float(r[3] or 0)}
            for r in cur.fetchall()
        ]

        # 3. Top 10 productos
        cur.execute(f"""
            SELECT m.sku, m.nombre,
                   SUM(m.cantidad) AS unidades,
                   COALESCE(SUM(m.cantidad * COALESCE(p.precio_oferta, p.precio_normal, 0)), 0) AS monto
            FROM movimientos m
            LEFT JOIN productos p ON p.sku = m.sku
            WHERE {where}
            GROUP BY m.sku, m.nombre
            ORDER BY unidades DESC
            LIMIT 10
        """, params)
        top_productos = [
            {"sku": r[0], "nombre": (r[1] or r[0] or "")[:45],
             "unidades": int(r[2] or 0), "monto": float(r[3] or 0)}
            for r in cur.fetchall()
        ]

        # 4. Resumen global
        total_u = sum(r["unidades"] for r in ventas_por_dia)
        total_o = sum(r["ordenes"]  for r in ventas_por_dia)
        monto_t = sum(r["monto"]    for r in ventas_por_dia)
        canal_t = ventas_por_canal[0]["canal"] if ventas_por_canal else "—"
        prod_t  = top_productos[0]["nombre"]   if top_productos    else "—"

        cur.close(); conn.close()

        return jsonify({
            "ok": True,
            "ventas_por_dia"  : ventas_por_dia,
            "ventas_por_canal": ventas_por_canal,
            "top_productos"   : top_productos,
            "resumen": {
                "total_ordenes" : total_o,
                "total_unidades": total_u,
                "monto_estimado": monto_t,
                "canal_top"     : canal_t,
                "producto_top"  : prod_t,
            }
        })
    except Exception as e:
        import traceback
        return jsonify({"error": str(e), "trace": traceback.format_exc()}), 500


# ════════════════════════════════════════════════════════════════════════════════
# MÓDULO REPORTE DE VENTAS — consolida órdenes de todos los marketplaces
# Devuelve filas listas para exportar a CSV/Excel
# ════════════════════════════════════════════════════════════════════════════════

@app.route("/ventas/reporte", methods=["GET"])
def ventas_reporte():
    """Construye reporte de ventas consolidado por rango de fechas."""
    if not session.get("logged"):
        return jsonify({"error": "no autorizado"}), 401
    try:
        fecha_desde = request.args.get("fecha_desde") or ""
        fecha_hasta = request.args.get("fecha_hasta") or ""
        canales_str = request.args.get("canales") or ""
        filas = _construir_filas_ventas(fecha_desde, fecha_hasta, canales_str)
        return jsonify({"ok": True, "filas": filas, "total": len(filas)})
    except Exception as e:
        import traceback
        print(f"[ventas_reporte] ERROR: {e}\n{traceback.format_exc()}")
        return jsonify({"error": str(e)}), 500


def _construir_filas_ventas(fecha_desde, fecha_hasta, canales_str):
    """Función interna: construye las filas del reporte consultando APIs de cada canal.
    Retorna lista de dicts listos para JSON o CSV.
    Cada fila = 1 unidad de 1 producto (si qty=3 → 3 filas con mismos datos de cliente).
    """
    canales_req = [c.strip().lower() for c in (canales_str or "").split(",") if c.strip()]
    filas = []

    # ── Helper para fila base ──────────────────────────────────────────────
    def fila(canal, orden, fecha, nombre, apellido, rut, telefono, email,
             producto, sku_seller, precio, envio, direccion, comuna,
             metodo_pago, metodo_envio, tracking, **kwargs):
        """Construye una fila del reporte.
        kwargs acepta es_flota_propia (ignorado por ahora) para compat."""
        return {
            "canal": canal, "orden": str(orden or ""), "fecha": (fecha or "")[:10],
            "nombre": nombre or "", "apellido": apellido or "",
            "rut": rut or "", "telefono": telefono or "", "email": email or "",
            "producto": producto or "", "sku_seller": sku_seller or "",
            "cantidad": 1,
            "precio_pagado": float(precio or 0), "valor_envio": float(envio or 0),
            "direccion": direccion or "", "comuna": comuna or "",
            "metodo_pago": metodo_pago or "", "metodo_envio": metodo_envio or "",
            "tracking": tracking or "",
        }

    # ── MERCADOLIBRE ──────────────────────────────────────────────────────
    if not canales_req or "mercadolibre" in canales_req:
        try:
            from mercadolibre import obtener_todas_ordenes_meli_rango, meli_headers, MELI_API_URL
            import requests as _req
            df = f"{fecha_desde}T00:00:00.000-04:00" if fecha_desde else None
            dt = f"{fecha_hasta}T23:59:59.000-04:00" if fecha_hasta else None
            ordenes_meli = obtener_todas_ordenes_meli_rango(df, dt) if df else []
            hdrs = meli_headers()

            for o in ordenes_meli:
                if o.get("status") not in ("paid", "confirmed", "payment_required"):
                    continue

                order_id  = str(o.get("id", ""))
                buyer     = o.get("buyer") or {}
                buyer_id  = buyer.get("id")
                payments  = o.get("payments") or [{}]
                pago      = (payments[0].get("payment_method_id") or "") if payments else ""
                envio_cost= float((payments[0].get("shipping_cost") or 0)) if payments else 0
                shipping  = o.get("shipping") or {}
                ship_id   = shipping.get("id")

                # Nombre real: intentar billing_info primero (tiene RUT y nombre completo)
                nombre = apellido = rut = email = telefono = ""
                try:
                    bi = _req.get(f"{MELI_API_URL}/orders/{order_id}/billing_info",
                                  headers=hdrs, timeout=8)
                    if bi.status_code == 200:
                        bd = bi.json()
                        billing = bd.get("billing_info") or bd
                        nombre   = billing.get("first_name") or ""
                        apellido = billing.get("last_name") or ""
                        rut      = billing.get("doc_number") or billing.get("identification", {}).get("number","") if isinstance(billing.get("identification"),dict) else ""
                        email    = billing.get("email") or buyer.get("email") or ""
                        telefono = billing.get("phone") or ""
                except Exception:
                    pass

                # Fallback: campos del buyer en la orden
                if not nombre:
                    nombre   = buyer.get("first_name") or ""
                    apellido = buyer.get("last_name") or ""
                if not email:
                    email = buyer.get("email") or ""
                # Si aún no hay nombre, usar nickname pero marcado
                if not nombre and not apellido:
                    nombre = buyer.get("nickname") or ""

                # Datos de envío
                direccion = comuna = tracking = metodo_envio = ""
                if ship_id:
                    try:
                        sr = _req.get(f"{MELI_API_URL}/shipments/{ship_id}",
                                      headers=hdrs, timeout=8)
                        if sr.status_code == 200:
                            sd = sr.json()
                            tracking     = sd.get("tracking_number") or ""
                            metodo_envio = sd.get("logistic_type") or sd.get("shipping_mode") or ""
                            dest = sd.get("destination") or {}
                            addr = dest.get("shipping_address") or {}
                            num  = addr.get("street_number") or ""
                            direccion = f"{addr.get('street_name','')}{' '+num if num else ''}".strip()
                            city = addr.get("city") or {}
                            comuna = city.get("name","") if isinstance(city, dict) else str(city or "")
                    except Exception:
                        pass

                for item in (o.get("order_items") or []):
                    it    = item.get("item") or {}
                    sku_s = (it.get("seller_custom_field") or it.get("seller_sku") or "").strip()
                    prod  = it.get("title") or ""
                    qty   = int(item.get("quantity") or 1)
                    price = float(item.get("unit_price") or 0)
                    fecha = (o.get("date_created") or "")[:10]
                    for _ in range(qty):
                        filas.append(fila("MercadoLibre", order_id, fecha,
                            nombre, apellido, rut, telefono, email,
                            prod, sku_s, price, envio_cost,
                            direccion, comuna, pago, metodo_envio, tracking))
        except Exception as e:
            print(f"[Reporte ventas] MELI error: {e}")

    # ── PARIS ─────────────────────────────────────────────────────────────
    if not canales_req or "paris" in canales_req:
        try:
            from paris import obtener_ordenes_paris_todas, obtener_orden_paris
            from datetime import datetime as _dt
            dias = 30
            if fecha_desde:
                try:
                    d0 = _dt.strptime(fecha_desde, "%Y-%m-%d")
                    d1 = _dt.strptime(fecha_hasta, "%Y-%m-%d") if fecha_hasta else _dt.utcnow()
                    dias = max(1, min((d1 - d0).days + 1, 365))
                except Exception:
                    pass
            for o in obtener_ordenes_paris_todas(dias=dias):
                created = (o.get("createdAt") or o.get("originOrderDate") or "")[:10]
                if fecha_desde and created < fecha_desde: continue
                if fecha_hasta and created > fecha_hasta: continue
                order_id = str(o.get("subOrderNumber") or o.get("orderNumber") or "")

                # FIX: Paris en el listado NO trae items; hay que ir al detalle de cada sub-orden
                detalle = None
                if order_id:
                    try:
                        detalle = obtener_orden_paris(order_id)
                    except Exception:
                        detalle = None
                # Combinar datos de listado + detalle
                o_full = {**o, **(detalle or {})}

                cust = o_full.get("customer") or {}
                billing = o_full.get("billingAddress") or {}
                addr = o_full.get("shippingAddress") or {}
                nombre   = cust.get("firstName") or cust.get("name") or billing.get("firstName") or ""
                apellido = cust.get("lastName") or billing.get("lastName") or ""
                email    = cust.get("email") or ""
                telefono = cust.get("phone") or billing.get("phone") or ""
                rut      = cust.get("documentNumber") or cust.get("rut") or ""
                st_name  = addr.get("streetName") or addr.get("address1") or billing.get("address1") or ""
                st_num   = addr.get("streetNumber") or ""
                direccion= f"{st_name}{' '+st_num if st_num else ''}".strip()
                comuna   = addr.get("city") or addr.get("commune") or billing.get("city") or ""

                # Items de Paris vienen dentro de shipments[].items o subOrders[].items o items directo
                items_paris = []
                # Opción 1: items directo
                if o_full.get("items"):
                    items_paris = o_full.get("items") or []
                # Opción 2: dentro de shipments
                if not items_paris:
                    for ship in (o_full.get("shipments") or []):
                        items_paris.extend(ship.get("items") or [])
                # Opción 3: dentro de subOrders
                if not items_paris:
                    for so in (o_full.get("subOrders") or []):
                        items_paris.extend(so.get("items") or [])

                tracking = ""
                m_envio = (o_full.get("deliveryOption") or {}).get("name") if isinstance(o_full.get("deliveryOption"), dict) else (o_full.get("logisticType") or o_full.get("shippingType") or "")
                m_pago = o_full.get("paymentMethod") or o_full.get("originInvoiceType") or ""

                # Buscar tracking en shipments
                for ship in (o_full.get("shipments") or []):
                    tracking = ship.get("trackingNumber") or tracking
                    if tracking: break

                envio_c = 0
                # Costo de envío del primer shipment
                for ship in (o_full.get("shipments") or []):
                    try:
                        envio_c = float(ship.get("cost") or 0)
                        if envio_c > 0: break
                    except: pass

                if not items_paris:
                    filas.append(fila("Paris", order_id, created,
                        nombre, apellido, rut, telefono, email,
                        "", "", 0, envio_c,
                        direccion, comuna, m_pago, m_envio, tracking))
                    continue

                for item in items_paris:
                    sku_s = (item.get("sellerSku") or item.get("seller_sku") or
                             item.get("sku") or item.get("jda_sku") or item.get("jdaSku") or "")
                    prod  = item.get("name") or item.get("productName") or item.get("title") or ""
                    qty   = int(item.get("quantity") or 1)
                    # Paris: priceAfterDiscounts = precio final pagado por el cliente
                    price = float(item.get("priceAfterDiscounts") or
                                  item.get("price_after_discounts") or
                                  item.get("grossPrice") or
                                  item.get("gross_price") or
                                  item.get("basePrice") or
                                  item.get("base_price") or
                                  item.get("unitPrice") or
                                  item.get("price") or 0)
                    for _ in range(qty):
                        filas.append(fila("Paris", order_id, created,
                            nombre, apellido, rut, telefono, email,
                            prod, sku_s, price, envio_c,
                            direccion, comuna, m_pago, m_envio, tracking))
        except Exception as e:
            print(f"[Reporte ventas] Paris error: {e}")

    # ── WALMART ───────────────────────────────────────────────────────────
    if not canales_req or "walmart" in canales_req:
        try:
            from walmart import walmart_headers, WALMART_BASE_URL
            import requests as _req2
            params_wm = {"limit": 200}
            if fecha_desde: params_wm["createdStartDate"] = f"{fecha_desde}T00:00:00"
            if fecha_hasta: params_wm["createdEndDate"]   = f"{fecha_hasta}T23:59:59"
            r_wm = _req2.get(f"{WALMART_BASE_URL}/v3/orders",
                             headers=walmart_headers(), params=params_wm, timeout=20)
            if r_wm.status_code == 200:
                data_wm = r_wm.json()
                raw = (data_wm.get("list",{}) or {}).get("elements",{}).get("order",[]) or []
                ordenes_wm = raw if isinstance(raw, list) else [raw]
                for o in ordenes_wm:
                    order_id  = str(o.get("customerOrderId") or "")
                    # FIX: orderDate puede venir como int (timestamp ms) o string
                    raw_date = o.get("orderDate")
                    if isinstance(raw_date, (int, float)):
                        # timestamp en ms → fecha ISO
                        from datetime import datetime as _dt_wm
                        try:
                            created = _dt_wm.fromtimestamp(raw_date / 1000).strftime("%Y-%m-%d")
                        except: created = ""
                    else:
                        created = (str(raw_date) or "")[:10]
                    email_wm  = o.get("customerEmailId") or ""
                    ship_info = o.get("shippingInfo") or {}
                    addr      = ship_info.get("postalAddress") or {}
                    full_name = addr.get("name") or ""
                    nombre = full_name; apellido = ""
                    if " " in full_name:
                        partes = full_name.split(" ", 1)
                        nombre = partes[0]; apellido = partes[1]
                    direccion    = addr.get("address1") or ""
                    comuna       = addr.get("city") or ""
                    metodo_envio = ship_info.get("methodCode") or ""
                    metodo_pago  = (o.get("paymentData") or {}).get("paymentType") or ""
                    for line in ((o.get("orderLines") or {}).get("orderLine") or []):
                        item  = line.get("item") or {}
                        prod  = item.get("productName") or ""
                        sku_s = item.get("sku") or line.get("sellerOrderId") or ""
                        qty   = int((line.get("orderLineQuantity") or {}).get("amount") or 1)

                        # Walmart separa cargos en: PRODUCT, COMMISSION, SHIPPING
                        # PRODUCT = precio del SKU + IVA producto
                        charges = (line.get("charges") or {}).get("charge") or []
                        if not isinstance(charges, list): charges = [charges]

                        precio = 0.0
                        for ch in charges:
                            if ch.get("chargeType") == "PRODUCT":
                                base = float((ch.get("chargeAmount") or {}).get("amount") or 0)
                                iva = float(((ch.get("tax") or {}).get("taxAmount") or {}).get("amount") or 0)
                                precio = base + iva
                                break
                        # Fallback: si no encuentra PRODUCT, usar primer charge con IVA
                        if precio == 0.0 and charges:
                            base = float((charges[0].get("chargeAmount") or {}).get("amount") or 0)
                            iva = float(((charges[0].get("tax") or {}).get("taxAmount") or {}).get("amount") or 0)
                            precio = base + iva

                        tracking = ""
                        for pkg in ((line.get("fulfillment") or {}).get("trackingInfo") or []):
                            tracking = pkg.get("trackingNumber") or ""; break

                        for _ in range(qty):
                            filas.append(fila("Walmart", order_id, created,
                                nombre, apellido, "", "", email_wm,
                                prod, sku_s, precio, 0,
                                direccion, comuna, metodo_pago, metodo_envio, tracking))
        except Exception as e:
            print(f"[Reporte ventas] Walmart error: {e}")

    # ── FALABELLA — consulta API directamente ─────────────────────────────
    if not canales_req or "falabella" in canales_req:
        try:
            from falabella import obtener_ordenes_falabella, obtener_items_orden_falabella
            from datetime import datetime as _dt2
            dias_fa = 30
            if fecha_desde:
                try:
                    d0 = _dt2.strptime(fecha_desde, "%Y-%m-%d")
                    d1 = _dt2.strptime(fecha_hasta, "%Y-%m-%d") if fecha_hasta else _dt2.utcnow()
                    dias_fa = max(1, min((d1 - d0).days + 2, 365))
                except Exception:
                    pass
            ordenes_fa = obtener_ordenes_falabella(dias=dias_fa) or []
            print(f"[Reporte ventas] Falabella: {len(ordenes_fa)} órdenes brutas, filtrando por {fecha_desde}–{fecha_hasta}")
            for o in ordenes_fa:
                try:
                    created  = (o.get("CreatedAt") or o.get("created_at") or "")[:10]
                    if fecha_desde and created < fecha_desde: continue
                    if fecha_hasta and created > fecha_hasta: continue
                    order_id = str(o.get("OrderId") or o.get("order_id") or "")
                    # Datos de cliente en la orden de Falabella
                    nombre   = o.get("CustomerFirstName") or o.get("BillingName") or ""
                    apellido = o.get("CustomerLastName") or ""
                    if not nombre:
                        full = o.get("CustomerName") or o.get("AddressName") or ""
                        if " " in full: nombre, apellido = full.split(" ", 1)
                        else: nombre = full
                    email    = o.get("CustomerEmail") or ""
                    telefono = o.get("CustomerPhone") or o.get("BillingPhone") or ""
                    rut      = o.get("NationalRegistrationNumber") or o.get("CustomerRut") or ""
                    # Dirección de envío
                    direccion = o.get("AddressLine1") or o.get("ShippingAddress") or ""
                    comuna    = o.get("City") or o.get("Ward") or o.get("ShippingCity") or ""
                    m_pago    = o.get("PaymentMethod") or ""
                    m_envio   = o.get("ShippingType") or o.get("DeliveryType") or ""
                    tracking  = o.get("TrackingCode") or ""

                    # Items de la orden
                    try:
                        items_fa = obtener_items_orden_falabella(order_id) or []
                    except Exception as e_items:
                        print(f"[Reporte ventas] Falabella items error orden {order_id}: {e_items}")
                        items_fa = []

                    # Falabella devuelve strings ("42,780.00" o "42780.00"). Castear seguro.
                    def _to_float(v):
                        if v is None: return 0.0
                        if isinstance(v, (int, float)): return float(v)
                        s = str(v).replace(",", "")
                        try: return float(s)
                        except: return 0.0

                    # Price = total con envío (Gran Total). Si no, usar GrandTotal o ProductTotal.
                    precio_total_orden = (_to_float(o.get("Price")) or
                                          _to_float(o.get("GrandTotal")) or
                                          _to_float(o.get("ProductTotal")))
                    shipping_total_orden = (_to_float(o.get("ShippingFeeTotal")) or
                                            _to_float(o.get("ShippingFee")))
                    total_units = sum(int(it.get("Quantity") or 1) for it in items_fa) if items_fa else 1
                    if total_units < 1: total_units = 1
                    precio_unitario_default = precio_total_orden / total_units if precio_total_orden > 0 else 0

                    if not items_fa:
                        filas.append(fila("Falabella", order_id, created,
                            nombre, apellido, rut, telefono, email,
                            "", "", precio_total_orden, shipping_total_orden,
                            direccion, comuna, m_pago, m_envio, tracking))
                        continue

                    for item in items_fa:
                        sku_s = item.get("SellerSku") or item.get("Sku") or ""
                        prod  = item.get("Name") or item.get("ProductName") or ""
                        qty   = int(item.get("Quantity") or 1)
                        price = (_to_float(item.get("PaidPrice")) or
                                 _to_float(item.get("ItemPrice")) or
                                 _to_float(item.get("Price")))
                        if price <= 0:
                            price = precio_unitario_default
                        envio_c = (_to_float(item.get("ShippingFee")) or
                                   _to_float(item.get("ShippingAmount")))
                        if envio_c <= 0:
                            envio_c = shipping_total_orden / total_units if shipping_total_orden > 0 else 0
                        track_i = item.get("TrackingCode") or tracking
                        for _ in range(qty):
                            filas.append(fila("Falabella", order_id, created,
                                nombre, apellido, rut, telefono, email,
                                prod, sku_s, price, envio_c,
                                direccion, comuna, m_pago, m_envio, track_i))
                except Exception as e_orden:
                    print(f"[Reporte ventas] Falabella error procesando orden: {e_orden}")
                    continue
        except Exception as e:
            import traceback
            print(f"[Reporte ventas] Falabella error general: {e}\n{traceback.format_exc()}")

    # ── WEB / WOOCOMMERCE — consulta API directa para precios reales ──────
    if not canales_req or "web" in canales_req or "woocommerce" in canales_req:
        try:
            from datetime import timezone as _tz_woo
            # Convertir fecha_desde a ISO con timezone
            df_woo = f"{fecha_desde}T00:00:00" if fecha_desde else ""
            dt_woo = f"{fecha_hasta}T23:59:59" if fecha_hasta else ""

            params_woo = {
                "consumer_key": WC_KEY, "consumer_secret": WC_SECRET,
                "status": "processing,completed",  # solo ventas reales
                "per_page": 100
            }
            if df_woo: params_woo["after"] = df_woo
            if dt_woo: params_woo["before"] = dt_woo

            r_woo = requests.get(
                "https://www.babymine.cl/wp-json/wc/v3/orders",
                params=params_woo, timeout=15
            )
            if r_woo.status_code == 200:
                ordenes_woo = r_woo.json() or []
                for o in ordenes_woo:
                    order_id = str(o.get("id", ""))
                    created  = (o.get("date_created") or "")[:10]

                    # Datos cliente
                    billing = o.get("billing") or {}
                    shipping = o.get("shipping") or {}
                    nombre   = billing.get("first_name") or shipping.get("first_name") or ""
                    apellido = billing.get("last_name") or shipping.get("last_name") or ""
                    email    = billing.get("email") or ""
                    telefono = billing.get("phone") or ""
                    direccion= (shipping.get("address_1") or billing.get("address_1") or "")
                    comuna   = (shipping.get("city") or billing.get("city") or "")
                    # Buscar RUT en meta_data si existe
                    rut = ""
                    for m in (o.get("meta_data") or []):
                        if str(m.get("key", "")).lower() in ("_billing_rut", "billing_rut", "rut"):
                            rut = str(m.get("value", "")); break

                    m_pago = o.get("payment_method_title") or o.get("payment_method") or ""
                    envio_c = float(o.get("shipping_total") or 0)

                    # Shipping método
                    m_envio = ""
                    for sl in (o.get("shipping_lines") or []):
                        m_envio = sl.get("method_title") or sl.get("method_id") or ""; break

                    for line in (o.get("line_items") or []):
                        sku_s = (line.get("sku") or "").strip()
                        prod  = line.get("name") or ""
                        qty   = int(line.get("quantity") or 1)
                        # Precio = total / quantity (precio realmente pagado, no precio_normal)
                        line_total = float(line.get("total") or 0)
                        line_tax   = float(line.get("total_tax") or 0)
                        precio_unit = (line_total + line_tax) / qty if qty > 0 else 0
                        for _ in range(qty):
                            filas.append(fila("Web", order_id, created,
                                nombre, apellido, rut, telefono, email,
                                prod, sku_s, precio_unit, envio_c / max(qty, 1),
                                direccion, comuna, m_pago, m_envio, ""))
            else:
                print(f"[Reporte ventas] Web HTTP {r_woo.status_code}")
        except Exception as e:
            print(f"[Reporte ventas] Web error: {e}")

    # ── RIPLEY / OTROS CANALES LOCALES — desde movimientos ────────────────
    canales_locales = {"ripley", "tienda", "shopify",
                       "vtex", "jumpseller", "prestashop", "magento"}
    if not canales_req or canales_locales.intersection(canales_req):
        try:
            from inventario import get_conn as _gc2, release_conn as _rc2
            _c = _gc2(); _cur = _c.cursor()
            excluir = "('MercadoLibre','Paris','Walmart','Falabella','Manual','Ajuste','Sistema','Web','WooCommerce')"
            where_parts = [f"tipo = 'salida'", f"canal NOT IN {excluir}"]
            params_mv = []
            if fecha_desde:
                where_parts.append("DATE(fecha) >= %s"); params_mv.append(fecha_desde)
            if fecha_hasta:
                where_parts.append("DATE(fecha) <= %s"); params_mv.append(fecha_hasta)
            if canales_req:
                local_solicitados = canales_locales.intersection(canales_req)
                if local_solicitados:
                    ph = ",".join(["%s"] * len(local_solicitados))
                    where_parts.append(f"LOWER(canal) IN ({ph})")
                    params_mv.extend(local_solicitados)
            _cur.execute(f"""
                SELECT sku, nombre, cantidad, canal, numero_orden,
                       TO_CHAR(fecha,'YYYY-MM-DD'), precio_normal
                FROM movimientos m
                LEFT JOIN productos p ON p.sku = m.sku
                WHERE {' AND '.join(where_parts)}
                ORDER BY fecha DESC LIMIT 500
            """, params_mv)
            for r in _cur.fetchall():
                qty = int(r[2] or 1)
                canal_raw = r[3] or "Ripley"
                for _ in range(qty):
                    filas.append(fila(canal_raw, r[4] or "", r[5] or "",
                        "", "", "", "", "",
                        r[1] or "", r[0] or "",
                        float(r[6] or 0) if r[6] else 0, 0,
                        "", "", "", "", ""))
            _cur.close(); _rc2(_c)
        except Exception as e:
            print(f"[Reporte ventas] locales error: {e}")

    # Ordenar por fecha desc
    filas.sort(key=lambda x: x.get("fecha",""), reverse=True)
    return filas



@app.route("/ventas/export_csv", methods=["GET"])
def ventas_export_csv():
    """Exporta el reporte de ventas como CSV descargable directamente."""
    if not session.get("logged"):
        return jsonify({"error": "no autorizado"}), 401

    import io, csv
    from flask import Response

    fecha_desde = request.args.get("fecha_desde") or ""
    fecha_hasta = request.args.get("fecha_hasta") or ""
    canales_str = request.args.get("canales") or ""

    # Llamar directamente a la función interna reutilizable
    try:
        filas = _construir_filas_ventas(fecha_desde, fecha_hasta, canales_str)
    except Exception as e:
        return jsonify({"error": str(e)}), 500

    COLUMNAS = [
        ("canal","Canal"), ("orden","N° Orden"), ("fecha","Fecha"),
        ("nombre","Nombre"), ("apellido","Apellido"), ("rut","RUT"),
        ("telefono","Teléfono"), ("email","Correo"),
        ("producto","Producto"), ("sku_seller","SKU Seller"),
        ("cantidad","Cantidad"), ("precio_pagado","Precio pagado"),
        ("valor_envio","Valor envío"), ("direccion","Dirección"),
        ("comuna","Comuna"), ("metodo_pago","Método de pago"),
        ("metodo_envio","Método de envío"), ("tracking","N° Seguimiento"),
    ]

    output = io.StringIO()
    output.write("\ufeff")  # BOM para Excel en español
    writer = csv.writer(output, delimiter=";")
    writer.writerow([c[1] for c in COLUMNAS])
    for fila in filas:
        writer.writerow([str(fila.get(c[0],"") or "") for c in COLUMNAS])

    nombre_archivo = f"ventas_lusync_{fecha_desde or 'all'}_{fecha_hasta or 'all'}.csv"
    return Response(
        output.getvalue(),
        mimetype="text/csv; charset=utf-8",
        headers={"Content-Disposition": f"attachment; filename={nombre_archivo}"}
    )


# ════════════════════════════════════════════════════════════════════════════
# EMISIÓN MANUAL DE BOLETAS (interfaz Lusync)
# ════════════════════════════════════════════════════════════════════════════
# GET  /facturacion/emitir          → sirve el formulario (templates/emitir_boleta.html)
# POST /facturacion/boleta/emitir   → emite UNA boleta real y la envía al SII
# GET  /facturacion/boleta/<id>/pdf → genera el PDF de una boleta emitida
#
# Reutiliza el flujo validado del Set de Pruebas, parametrizado para una boleta
# real: folio atómico desde el CAF, resolución leída de la config del tenant.
# ════════════════════════════════════════════════════════════════════════════

@app.route("/facturacion/emitir", methods=["GET"])
def facturacion_emitir_form():
    """Sirve la interfaz de emisión manual de boletas."""
    if not session.get("logged"):
        return redirect("/login")
    return render_template("emitir_boleta.html")


@app.route("/facturacion/boleta/emitir", methods=["POST"])
def facturacion_boleta_emitir():
    """Emite UNA boleta electrónica (39/41) y la envía al SII.

    FLUJO PROFESIONAL (guardar-antes-de-enviar):
      1. Reservar folio (atómico)
      2. Generar + firmar
      3. REGISTRAR en BD con estado 'generado' (ANTES de enviar) → nunca hay folio huérfano
      4. Enviar al SII
      5. Actualizar estado: 'enviado' (con track_id) o 'error_envio'
      Si el SII rechaza o falla la conexión, la boleta queda registrada con su estado
      real y su XML, para reintentar o auditar. El folio nunca se pierde sin rastro.
    """
    if not session.get("logged"):
        return jsonify({"ok": False, "error": "no autenticado"}), 401

    tenant_id = session.get("tenant_id") or 1
    data = request.get_json(silent=True) or {}

    from inventario import get_conn, release_conn
    from facturacion.certificados import obtener_certificado
    from facturacion.db import obtener_config_facturacion
    from facturacion.cafs import obtener_folio_disponible
    from facturacion.utils import normalizar_ambiente

    pasos = []
    def paso(nombre, ok, detalle=""):
        pasos.append({"nombre": nombre, "ok": ok, "detalle": detalle})

    # 0. Validar items
    items = data.get("items") or []
    if not items:
        return jsonify({"ok": False, "error": "Debes agregar al menos un ítem"}), 400
    for it in items:
        if not it.get("nombre") or not it.get("precio_unitario"):
            return jsonify({"ok": False, "error": "Cada ítem necesita nombre y precio"}), 400

    # 1. Config del tenant
    config = obtener_config_facturacion(get_conn, release_conn, tenant_id)
    if not config:
        return jsonify({"ok": False, "error": "No hay configuración de facturación para este tenant"}), 400

    ambiente = normalizar_ambiente(data.get("ambiente") or config.get("ambiente") or "certificacion")
    todos_exentos = all(it.get("exento") for it in items)
    tipo_dte = 41 if todos_exentos else 39

    emisor = {
        "rut": config["rut_emisor"], "razon_social": config["razon_social"],
        "giro": config.get("giro", "Venta al por menor"),
        "dir_origen": config.get("direccion", "Sin dirección"),
        "cmna_origen": config.get("comuna", "Santiago"),
    }

    nro_resol = config.get("resolucion_sii_numero")
    fch_resol = config.get("resolucion_sii_fecha")
    if fch_resol and not isinstance(fch_resol, str):
        try:
            fch_resol = fch_resol.isoformat()
        except Exception:
            fch_resol = str(fch_resol)
    if nro_resol is None:
        nro_resol = 0
    if not fch_resol:
        fch_resol = "2014-08-22"

    # 2. Certificado .pfx
    cert = obtener_certificado(get_conn, release_conn, tenant_id)
    if not cert.get("ok"):
        return jsonify({"ok": False, "error": "Certificado: " + str(cert.get("error", "no disponible")),
                        "pasos": pasos}), 400
    paso("Leer certificado .pfx", True, cert["metadata"].get("titular", "?"))
    rut_envia = cert["metadata"].get("rut", emisor["rut"])

    # Receptor: genérico si no viene (XML al SII lleva 'Consumidor Final', validado)
    receptor = data.get("receptor") or {"rut": "66666666-6", "razon_social": "Consumidor Final"}
    if not receptor.get("rut"):
        receptor["rut"] = "66666666-6"
    if not receptor.get("razon_social"):
        receptor["razon_social"] = "Consumidor Final"

    # 3. Reservar folio (ATÓMICO)
    folio_res = obtener_folio_disponible(get_conn, release_conn, tenant_id, tipo_dte, ambiente)
    if not folio_res.get("ok"):
        return jsonify({"ok": False, "error": folio_res.get("error"), "pasos": pasos}), 400
    folio = folio_res["folio"]
    paso("Reservar folio", True, "Folio " + str(folio) + " (tipo " + str(tipo_dte) + ", " + ambiente + ")")

    track_id = None
    boleta_id = None
    total = 0

    try:
        from facturacion.dtes.caf_parser import parsear_caf_xml
        from facturacion.dtes.boleta import generar_boleta_xml
        from facturacion.dtes.envio_boleta import armar_envio_boleta
        from facturacion.dtes.firma import firmar_envio_completo
        from facturacion.dtes.sii_client import autenticar, enviar_boletas

        caf = parsear_caf_xml(folio_res["xml_caf"])
        # Fecha de emisión en hora de CHILE (no UTC del servidor). Si el servidor
        # corre en UTC, datetime.now() daría el día equivocado de noche, causando
        # que el FchEmis no coincida al consultar al SII. Usamos zona Chile.
        try:
            from zoneinfo import ZoneInfo
            fecha = datetime.now(ZoneInfo("America/Santiago")).strftime("%Y-%m-%d")
        except Exception:
            # Fallback: UTC - 4 horas (horario estándar de Chile)
            from datetime import timezone as _tz, timedelta as _td
            fecha = (datetime.now(_tz.utc) - _td(hours=4)).strftime("%Y-%m-%d")

        # 4. Generar la boleta
        # Referencias opcionales del request (guía despacho, OC, etc.)
        referencias = data.get("referencias") or []
        if not isinstance(referencias, list):
            referencias = []
        res_bol = generar_boleta_xml(
            caf=caf, folio=folio, fecha_emision=fecha,
            emisor=emisor, items=items, receptor=receptor,
            referencias=referencias if referencias else None,
        )
        boleta_xml = res_bol["xml"]
        total = res_bol["totales"]["mnt_total"]
        documento_id = res_bol["documento_id"]
        paso("Generar boleta", True, ("$" + format(total, ",")).replace(",", "."))

        # 5. Armar sobre + firmar
        set_id = "SetDoc"
        sobre = armar_envio_boleta(
            dtes_firmados=[boleta_xml], rut_emisor=emisor["rut"],
            rut_envia=rut_envia, fch_resol=fch_resol, nro_resol=nro_resol,
            tipo_dte=tipo_dte, set_dte_id=set_id,
        )
        sobre_firmado = firmar_envio_completo(
            sobre, cert["pfx_bytes"], cert["password"],
            set_dte_id=set_id, documento_ids=[documento_id])
        paso("Firmar sobre", True, str(len(sobre_firmado)) + " bytes")

        # ─────────────────────────────────────────────────────────────────
        # 6. REGISTRAR EN BD ANTES DE ENVIAR (estado 'generado')
        #    Esto garantiza que el folio NUNCA queda huérfano: aunque el envío
        #    al SII falle, la boleta queda registrada con su XML para reintento/auditoría.
        # ─────────────────────────────────────────────────────────────────
        conn = get_conn()
        try:
            with conn.cursor() as cur:
                cur.execute("""
                    INSERT INTO facturacion_dtes
                      (tenant_id, tipo_dte, folio, rut_receptor, razon_social_receptor,
                       monto_neto, monto_iva, monto_total, xml_firmado, estado,
                       fecha_emision)
                    VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
                    RETURNING id
                """, (tenant_id, tipo_dte, folio, receptor["rut"], receptor["razon_social"],
                      res_bol["totales"]["mnt_neto"], res_bol["totales"]["mnt_iva"],
                      total, boleta_xml.decode("iso-8859-1", errors="replace"), "generado",
                      fecha))  # fecha TIMBRADA en el XML (no NOW), para que la consulta al SII coincida
                boleta_id = cur.fetchone()[0]
            conn.commit()
            paso("Registrar boleta (pre-envío)", True, "ID " + str(boleta_id) + " · estado: generado")
        except Exception as e:
            conn.rollback()
            release_conn(conn)
            # No pudimos registrar: abortamos ANTES de enviar (no consumimos folio en el SII)
            paso("Registrar boleta (pre-envío)", False, str(e)[:200])
            return jsonify({"ok": False, "folio": folio,
                            "error": "No se pudo registrar la boleta antes de enviar: " + str(e)[:200],
                            "pasos": pasos}), 500
        finally:
            try:
                release_conn(conn)
            except Exception:
                pass

        # 7. Autenticar + enviar al SII
        try:
            tok = autenticar(cert["pfx_bytes"], cert["password"], ambiente)
            resultado = enviar_boletas(
                envio_xml=sobre_firmado, token=tok,
                rut_emisor=emisor["rut"], rut_envia=rut_envia, ambiente=ambiente)
        except Exception as e:
            # Falló la conexión/auth: la boleta queda en BD como 'error_envio' para reintento
            _fact_actualizar_estado_dte(boleta_id, "error_envio", glosa=str(e)[:300])
            paso("Enviar al SII", False, str(e)[:200])
            return jsonify({"ok": False, "boleta_id": boleta_id, "folio": folio,
                            "error": "No se pudo conectar con el SII. La boleta quedó guardada para reintentar.",
                            "reintentable": True, "pasos": pasos}), 502

        if not resultado.get("ok"):
            detalle = resultado.get("error") or str(resultado.get("respuesta_cruda", ""))[:300]
            _fact_actualizar_estado_dte(boleta_id, "error_envio", glosa=detalle)
            paso("Enviar al SII", False, detalle)
            return jsonify({"ok": False, "boleta_id": boleta_id, "folio": folio,
                            "error": "El SII rechazó el envío: " + str(detalle),
                            "reintentable": True, "pasos": pasos}), 502

        track_id = resultado["track_id"]
        # 8. Actualizar a 'enviado' con track_id
        _fact_actualizar_estado_dte(boleta_id, "enviado", track_id=track_id,
                                    estado_sii=resultado.get("estado"), set_fecha_envio=True)
        paso("Enviar al SII", True, "Track ID: " + str(track_id))

    except Exception as e:
        import traceback
        paso("Error", False, traceback.format_exc()[:400])
        # Si ya habíamos registrado la boleta, dejarla marcada como error
        if boleta_id:
            try:
                _fact_actualizar_estado_dte(boleta_id, "error_envio", glosa=str(e)[:300])
            except Exception:
                pass
        return jsonify({"ok": False, "error": str(e)[:300], "folio": folio,
                        "boleta_id": boleta_id, "pasos": pasos}), 500

    return jsonify({
        "ok": True, "folio": folio, "tipo_dte": tipo_dte, "track_id": track_id,
        "total": total, "boleta_id": boleta_id,
        "pdf_url": ("/facturacion/boleta/" + str(boleta_id) + "/pdf") if boleta_id else None,
        "pasos": pasos,
    })


@app.route("/facturacion/nota-credito/emitir", methods=["POST"])
def facturacion_nota_credito_emitir():
    """Emite UNA Nota de Crédito (tipo 61) que anula o rebaja un documento previo.

    A diferencia de la boleta:
      • Va en sobre EnvioDTE (no EnvioBOLETA)
      • Se envía a maullin/palena DTEUpload con token SOAP (no pangal)
      • Requiere Referencia OBLIGATORIA al documento original

    Body JSON:
      {
        "referencia": {
            "folio_ref": 24,            # folio del documento original
            "tipo_doc_ref": 39,         # 39=boleta, 33=factura...
            "fecha_ref": "2026-05-27",  # fecha del doc original (FchRef)
            "cod_ref": 1,               # 1=anula, 2=corrige texto, 3=corrige montos
            "razon_ref": "ANULA BOLETA"
        },
        "items": [...],                  # para anulación: los mismos del doc original
        "receptor": {...}                # opcional
      }
    Para CodRef=1 (anula), los items deben replicar el documento original completo.
    Para CodRef=3 (rebaja), los items son el monto a rebajar.
    """
    if not session.get("logged"):
        return jsonify({"ok": False, "error": "no autenticado"}), 401

    tenant_id = session.get("tenant_id") or 1
    data = request.get_json(silent=True) or {}

    from inventario import get_conn, release_conn
    from facturacion.certificados import obtener_certificado
    from facturacion.db import obtener_config_facturacion
    from facturacion.cafs import obtener_folio_disponible
    from facturacion.utils import normalizar_ambiente

    pasos = []
    def paso(nombre, ok, detalle=""):
        pasos.append({"nombre": nombre, "ok": ok, "detalle": detalle})

    # 0. Validar referencia (OBLIGATORIA en NC)
    referencia = data.get("referencia") or {}
    if not referencia.get("folio_ref"):
        return jsonify({"ok": False, "error": "La Nota de Crédito requiere el folio del documento que modifica"}), 400
    cod_ref = int(referencia.get("cod_ref", 1))
    # items: para anulación pueden venir del documento original
    items = data.get("items") or []
    if cod_ref == 1 and not items:
        # Anulación sin items: intentar reconstruir desde el documento referenciado
        return jsonify({"ok": False, "error": "Para anular debes incluir los ítems del documento original (o usar el botón Anular desde el documento)"}), 400
    if not items:
        return jsonify({"ok": False, "error": "Debes incluir al menos un ítem"}), 400

    # 1. Config
    config = obtener_config_facturacion(get_conn, release_conn, tenant_id)
    if not config:
        return jsonify({"ok": False, "error": "No hay configuración de facturación"}), 400
    ambiente = normalizar_ambiente(data.get("ambiente") or config.get("ambiente") or "certificacion")

    emisor = {
        "rut": config["rut_emisor"], "razon_social": config["razon_social"],
        "giro": config.get("giro", "Venta al por menor"),
        "dir_origen": config.get("direccion", "Sin dirección"),
        "cmna_origen": config.get("comuna", "Santiago"),
    }
    nro_resol = config.get("resolucion_sii_numero")
    fch_resol = config.get("resolucion_sii_fecha")
    if fch_resol and not isinstance(fch_resol, str):
        try: fch_resol = fch_resol.isoformat()
        except Exception: fch_resol = str(fch_resol)
    if nro_resol is None: nro_resol = 0
    if not fch_resol: fch_resol = "2026-05-15"

    # 2. Certificado
    cert = obtener_certificado(get_conn, release_conn, tenant_id)
    if not cert.get("ok"):
        return jsonify({"ok": False, "error": "Certificado: " + str(cert.get("error", "no disponible")), "pasos": pasos}), 400
    paso("Leer certificado", True, cert["metadata"].get("titular", "?"))
    rut_envia = cert["metadata"].get("rut", emisor["rut"])

    receptor = data.get("receptor") or {"rut": "66666666-6", "razon_social": "Consumidor Final"}
    if not receptor.get("rut"): receptor["rut"] = "66666666-6"
    if not receptor.get("razon_social"): receptor["razon_social"] = "Consumidor Final"

    # 3. Reservar folio tipo 61 (ATÓMICO)
    folio_res = obtener_folio_disponible(get_conn, release_conn, tenant_id, 61, ambiente)
    if not folio_res.get("ok"):
        return jsonify({"ok": False, "error": folio_res.get("error") or "No hay folios de NC (tipo 61) disponibles. Carga un CAF tipo 61.", "pasos": pasos}), 400
    folio = folio_res["folio"]
    paso("Reservar folio NC", True, "Folio " + str(folio) + " (tipo 61, " + ambiente + ")")

    track_id = None
    nc_id = None
    total = 0

    try:
        from facturacion.dtes.caf_parser import parsear_caf_xml
        from facturacion.dtes.nota_credito import generar_nota_credito_xml
        from facturacion.dtes.envio_dte import armar_envio_dte
        from facturacion.dtes.firma import firmar_envio_completo
        from facturacion.dtes.sii_client import obtener_token_dte, enviar_dte

        caf = parsear_caf_xml(folio_res["xml_caf"])
        try:
            from zoneinfo import ZoneInfo
            fecha = datetime.now(ZoneInfo("America/Santiago")).strftime("%Y-%m-%d")
        except Exception:
            from datetime import timezone as _tz, timedelta as _td
            fecha = (datetime.now(_tz.utc) - _td(hours=4)).strftime("%Y-%m-%d")

        # Referencia completa para la NC
        ref = {
            "folio_ref": referencia["folio_ref"],
            "tipo_doc_ref": referencia.get("tipo_doc_ref", 39),
            "fecha_ref": referencia.get("fecha_ref", fecha),
            "cod_ref": cod_ref,
            "razon_ref": referencia.get("razon_ref", "ANULA" if cod_ref == 1 else "CORRIGE"),
        }

        # 4. Generar la NC
        res_nc = generar_nota_credito_xml(
            caf=caf, folio=folio, fecha_emision=fecha,
            emisor=emisor, items=items, referencia=ref, receptor=receptor,
        )
        nc_xml = res_nc["xml"]
        total = res_nc["totales"]["mnt_total"]
        documento_id = res_nc["documento_id"]
        paso("Generar Nota de Crédito", True, ("$" + format(total, ",")).replace(",", "."))

        # 5. Firmar el documento individual + armar sobre EnvioDTE + firmar sobre
        from facturacion.dtes.firma import firmar_documento
        nc_firmada = firmar_documento(nc_xml, cert["pfx_bytes"], cert["password"], documento_id)

        set_id = "SetDoc"
        sobre = armar_envio_dte(
            dtes_firmados=[nc_firmada], rut_emisor=emisor["rut"],
            rut_envia=rut_envia, fch_resol=fch_resol, nro_resol=nro_resol,
            tipo_dte=61, set_dte_id=set_id,
        )
        sobre_firmado = firmar_envio_completo(
            sobre, cert["pfx_bytes"], cert["password"],
            set_dte_id=set_id, documento_ids=[documento_id])
        paso("Firmar sobre EnvioDTE", True, str(len(sobre_firmado)) + " bytes")

        # 6. REGISTRAR EN BD ANTES DE ENVIAR
        conn = get_conn()
        try:
            with conn.cursor() as cur:
                cur.execute("""
                    INSERT INTO facturacion_dtes
                      (tenant_id, tipo_dte, folio, rut_receptor, razon_social_receptor,
                       monto_neto, monto_iva, monto_total, xml_firmado, estado, fecha_emision)
                    VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
                    RETURNING id
                """, (tenant_id, 61, folio, receptor["rut"], receptor["razon_social"],
                      res_nc["totales"]["mnt_neto"], res_nc["totales"]["mnt_iva"],
                      total, nc_firmada.decode("iso-8859-1", errors="replace"), "generado", fecha))
                nc_id = cur.fetchone()[0]
            conn.commit()
            paso("Registrar NC (pre-envío)", True, "ID " + str(nc_id))
        except Exception as e:
            conn.rollback(); release_conn(conn)
            paso("Registrar NC (pre-envío)", False, str(e)[:200])
            return jsonify({"ok": False, "folio": folio,
                            "error": "No se pudo registrar la NC antes de enviar: " + str(e)[:200], "pasos": pasos}), 500
        finally:
            try: release_conn(conn)
            except Exception: pass

        # 7. Token SOAP + enviar a DTEUpload
        try:
            tok = obtener_token_dte(cert["pfx_bytes"], cert["password"], ambiente)
            paso("Obtener token SOAP", True, "token " + str(tok)[:10] + "…")
        except Exception as e:
            import traceback
            detalle_tok = str(e)[:250]
            _fact_actualizar_estado_dte(nc_id, "error_envio", glosa="Token SOAP: " + detalle_tok)
            paso("Obtener token SOAP", False, detalle_tok)
            return jsonify({"ok": False, "nc_id": nc_id, "folio": folio,
                            "error": "Error al autenticar con el SII (token SOAP): " + detalle_tok,
                            "reintentable": True, "pasos": pasos,
                            "trace": traceback.format_exc()[:500]}), 502
        try:
            resultado = enviar_dte(
                envio_xml=sobre_firmado, token=tok,
                rut_emisor=emisor["rut"], rut_envia=rut_envia, ambiente=ambiente)
        except Exception as e:
            import traceback
            detalle_env = str(e)[:250]
            _fact_actualizar_estado_dte(nc_id, "error_envio", glosa="Envío DTE: " + detalle_env)
            paso("Enviar al SII", False, detalle_env)
            return jsonify({"ok": False, "nc_id": nc_id, "folio": folio,
                            "error": "Error al enviar al SII (DTEUpload): " + detalle_env,
                            "reintentable": True, "pasos": pasos,
                            "trace": traceback.format_exc()[:500]}), 502

        if not resultado.get("ok"):
            detalle = resultado.get("error") or ("; ".join(resultado.get("errores", []))) or str(resultado.get("respuesta_cruda", ""))[:300]
            _fact_actualizar_estado_dte(nc_id, "error_envio", glosa=detalle)
            paso("Enviar al SII", False, detalle)
            return jsonify({"ok": False, "nc_id": nc_id, "folio": folio,
                            "error": "El SII rechazó el envío: " + str(detalle),
                            "reintentable": True, "pasos": pasos}), 502

        track_id = resultado["track_id"]
        _fact_actualizar_estado_dte(nc_id, "enviado", track_id=track_id, set_fecha_envio=True)
        paso("Enviar al SII", True, "Track ID: " + str(track_id))

    except Exception as e:
        import traceback
        paso("Error", False, traceback.format_exc()[:400])
        if nc_id:
            try: _fact_actualizar_estado_dte(nc_id, "error_envio", glosa=str(e)[:300])
            except Exception: pass
        return jsonify({"ok": False, "error": str(e)[:300], "folio": folio, "nc_id": nc_id, "pasos": pasos}), 500

    return jsonify({
        "ok": True, "folio": folio, "tipo_dte": 61, "track_id": track_id,
        "total": total, "nc_id": nc_id,
        "pdf_url": ("/facturacion/boleta/" + str(nc_id) + "/pdf") if nc_id else None,
        "pasos": pasos,
    })


def _fact_actualizar_estado_dte(boleta_id, estado, track_id=None, estado_sii=None,
                                glosa=None, set_fecha_envio=False, set_fecha_aceptacion=False):
    """Actualiza el estado de un DTE registrado. Helper central de trazabilidad."""
    from inventario import get_conn, release_conn
    conn = get_conn()
    try:
        sets = ["estado = %s"]
        vals = [estado]
        if track_id is not None:
            sets.append("track_id_sii = %s"); vals.append(track_id)
        if estado_sii is not None:
            sets.append("estado_sii = %s"); vals.append(estado_sii)
        if glosa is not None:
            sets.append("glosa_sii = %s"); vals.append(glosa)
        if set_fecha_envio:
            sets.append("fecha_envio_sii = NOW()")
        if set_fecha_aceptacion:
            sets.append("fecha_aceptacion_sii = NOW()")
        vals.append(boleta_id)
        with conn.cursor() as cur:
            cur.execute("UPDATE facturacion_dtes SET " + ", ".join(sets) + " WHERE id = %s", vals)
        conn.commit()
        return True
    except Exception as e:
        conn.rollback()
        print("[Facturación] Error actualizando estado DTE %s: %s" % (boleta_id, e))
        return False
    finally:
        release_conn(conn)


@app.route("/facturacion/boleta/preview", methods=["POST"])
def facturacion_boleta_preview():
    """Genera un PDF de VISTA PREVIA (borrador) con el mismo diseño que el documento
    final, SIN reservar folio, SIN firmar y SIN enviar al SII. El folio se muestra
    como BORRADOR y el timbre como placeholder.

    Body JSON igual que /facturacion/boleta/emitir + "formato": "carta"|"rollo"
    Returns: PDF (application/pdf)
    """
    if not session.get("logged"):
        return jsonify({"ok": False, "error": "no autenticado"}), 401

    tenant_id = session.get("tenant_id") or 1
    data = request.get_json(silent=True) or {}
    formato = data.get("formato", "carta")

    from inventario import get_conn, release_conn
    from facturacion.db import obtener_config_facturacion
    from facturacion.dtes.pdf_dte import generar_pdf_dte
    from flask import Response

    items = data.get("items") or []
    if not items:
        return jsonify({"ok": False, "error": "Sin ítems"}), 400

    config = obtener_config_facturacion(get_conn, release_conn, tenant_id)
    if not config:
        return jsonify({"ok": False, "error": "Sin configuración"}), 400

    todos_exentos = all(it.get("exento") for it in items)
    tipo_dte = 41 if todos_exentos else 39

    # Calcular totales (precios incluyen IVA, igual que boleta.py)
    bruto_af = 0; mnt_exe = 0
    for it in items:
        sub = int(round(float(it.get("cantidad", 1)) * float(it.get("precio_unitario", 0))))
        if it.get("exento"):
            mnt_exe += sub
        else:
            bruto_af += sub
    neto = int(round(bruto_af / 1.19)) if bruto_af > 0 else 0
    iva = bruto_af - neto if bruto_af > 0 else 0
    total = neto + iva + mnt_exe

    receptor = data.get("receptor") or {}
    from datetime import datetime as _dt
    fecha = _dt.now().strftime("%Y-%m-%d")

    # Detalles XML
    detalles = ""
    for i, it in enumerate(items, 1):
        sub = int(round(float(it.get("cantidad", 1)) * float(it.get("precio_unitario", 0))))
        cant = it.get("cantidad", 1)
        cant_str = str(int(cant)) if float(cant) == int(cant) else f"{float(cant):.3f}".rstrip("0").rstrip(".")
        detalles += "<Detalle>"
        detalles += f"<NroLinDet>{i}</NroLinDet>"
        if it.get("exento"):
            detalles += "<IndExe>1</IndExe>"
        detalles += f"<NmbItem>{_esc_xml_preview(it.get('nombre',''))}</NmbItem>"
        detalles += f"<QtyItem>{cant_str}</QtyItem>"
        if it.get("unidad"):
            detalles += f"<UnmdItem>{_esc_xml_preview(it.get('unidad'))}</UnmdItem>"
        detalles += f"<PrcItem>{int(round(float(it.get('precio_unitario',0))))}</PrcItem>"
        detalles += f"<MontoItem>{sub}</MontoItem>"
        detalles += "</Detalle>"

    tot = "<Totales>"
    if bruto_af > 0:
        tot += f"<MntNeto>{neto}</MntNeto>"
    if mnt_exe > 0:
        tot += f"<MntExe>{mnt_exe}</MntExe>"
    if bruto_af > 0:
        tot += f"<IVA>{iva}</IVA>"
    tot += f"<MntTotal>{total}</MntTotal></Totales>"

    # XML borrador (sin TED real → el PDF mostrará placeholder de timbre)
    xml = (
        '<?xml version="1.0" encoding="ISO-8859-1"?>'
        '<DTE version="1.0"><Documento ID="BORRADOR">'
        '<Encabezado>'
        f'<IdDoc><TipoDTE>{tipo_dte}</TipoDTE><Folio>0</Folio><FchEmis>{fecha}</FchEmis></IdDoc>'
        '<Emisor>'
        f'<RUTEmisor>{config.get("rut_emisor","")}</RUTEmisor>'
        f'<RznSocEmisor>{_esc_xml_preview(config.get("razon_social",""))}</RznSocEmisor>'
        f'<GiroEmisor>{_esc_xml_preview(config.get("giro",""))}</GiroEmisor>'
        f'<DirOrigen>{_esc_xml_preview(config.get("direccion",""))}</DirOrigen>'
        f'<CmnaOrigen>{_esc_xml_preview(config.get("comuna",""))}</CmnaOrigen>'
        '</Emisor>'
        '<Receptor>'
        f'<RUTRecep>{receptor.get("rut","66666666-6")}</RUTRecep>'
        f'<RznSocRecep>{_esc_xml_preview(receptor.get("razon_social","Consumidor Final"))}</RznSocRecep>'
        '</Receptor>'
        f'{tot}'
        '</Encabezado>'
        f'{detalles}'
        '<TmstFirma>BORRADOR</TmstFirma>'
        '</Documento></DTE>'
    ).encode("iso-8859-1", errors="replace")

    url_consulta = "lusync.cl/consultadte"
    pdf = generar_pdf_dte(xml, formato=formato, url_consulta=url_consulta)
    return Response(pdf, mimetype="application/pdf",
                    headers={"Content-Disposition": 'inline; filename="preview.pdf"'})


def _esc_xml_preview(s):
    if s is None:
        return ""
    s = str(s)
    return (s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
             .replace('"', "&quot;").replace("'", "&apos;"))


# ═══════════════════════════════════════════════════════════════════════════
# PÁGINA PÚBLICA DE CONSULTA DE BOLETAS
# ═══════════════════════════════════════════════════════════════════════════
# /consultadte → formulario simple (sin login) para que el receptor verifique
#                su boleta con los datos impresos (RUT emisor, tipo, folio, fecha,
#                monto). La URL aparece en el pie del PDF de la boleta.
# Esto NO REEMPLAZA al SII pero sí confirma que el documento existe en el
# sistema del emisor y los datos calzan (anti-fraude).
# ═══════════════════════════════════════════════════════════════════════════

