@app.route("/admin/lusync/sii/test-pdf-boleta", methods=["GET"])
@requiere_lusync_admin
def admin_lusync_sii_test_pdf_boleta():
    """Genera la representación gráfica (PDF) de una boleta del Set.

    Formato configurable:
      ?formato=carta  (hoja, estilo factura — default)
      ?formato=rollo  (ticket térmico 80mm)
    Folio configurable con ?folio_desde=N (default 16, las boletas aceptadas).

    Uso: /admin/lusync/sii/test-pdf-boleta?token=...&tenant_id=3&formato=carta
    """
    from inventario import get_conn, release_conn
    from facturacion.certificados import obtener_certificado
    from facturacion import obtener_config_facturacion
    from flask import request, Response

    tenant_id = int(request.args.get("tenant_id", "3"))
    formato = request.args.get("formato", "carta").strip().lower()
    if formato not in ("carta", "rollo"):
        formato = "carta"
    _fd = request.args.get("folio_desde", "").strip()
    folio = int(_fd) if _fd.isdigit() else 16

    try:
        config = obtener_config_facturacion(get_conn, release_conn, tenant_id) or {}
        # CAF de boletas tipo 39
        conn = get_conn()
        try:
            with conn.cursor() as cur:
                cur.execute("""
                    SELECT xml_caf FROM facturacion_cafs
                    WHERE tenant_id = %s AND tipo_dte = 39
                    ORDER BY id DESC LIMIT 1
                """, (tenant_id,))
                row = cur.fetchone()
        finally:
            release_conn(conn)
        if not row:
            return Response("No hay CAF de Boleta 39 para este tenant", status=400)

        from facturacion.dtes.caf_parser import parsear_caf_xml
        from facturacion.dtes.boleta import generar_boleta_xml
        from facturacion.dtes.pdf_boleta import generar_pdf_boleta
        caf = parsear_caf_xml(row[0])

        emisor = {
            "rut": config.get("rut_emisor", "76.922.862-4"),
            "razon_social": config.get("razon_social", "GRUPO PH SPA"),
            "giro": config.get("giro", ""),
            "dir_origen": config.get("direccion", ""),
            "cmna_origen": config.get("comuna", "Santiago"),
        }
        # Usa el CASO-1 del Set como muestra
        res_bol = generar_boleta_xml(
            caf=caf, folio=folio, fecha_emision=datetime.now().strftime("%Y-%m-%d"),
            emisor=emisor,
            items=[{"nombre": "Cambio de aceite", "cantidad": 1, "precio_unitario": 19900, "exento": False},
                   {"nombre": "Alineacion y balanceo", "cantidad": 1, "precio_unitario": 9900, "exento": False}],
            referencia={"cod_ref": "SET", "razon_ref": "CASO-1"})

        pdf_bytes = generar_pdf_boleta(res_bol["xml"], formato=formato)
        nombre = f"boleta_{folio}_{formato}.pdf"
        return Response(pdf_bytes, mimetype="application/pdf",
                        headers={"Content-Disposition": f'inline; filename="{nombre}"'})
    except Exception as e:
        import traceback
        return Response(f"Error generando PDF: {e}\n\n{traceback.format_exc()}",
                        status=500, mimetype="text/plain")


@app.route("/admin/lusync/sii/test-rcof", methods=["GET"])
@requiere_lusync_admin
def admin_lusync_sii_test_rcof():
    """Genera el RCOF (Reporte de Consumo de Folios) que resume las 5 boletas
    del Set + las 2 Notas de Crédito. Lo firma y lo muestra.

    El RCOF es lo que el SII valida para certificar boletas.

    Uso: /admin/lusync/sii/test-rcof?token=...&tenant_id=3
    """
    from inventario import get_conn, release_conn
    from facturacion.certificados import obtener_certificado
    from facturacion.db import obtener_config_facturacion

    tenant_id = request.args.get("tenant_id", default=3, type=int)
    pasos = []
    def paso(nombre, ok, detalle=""):
        pasos.append({"nombre": nombre, "ok": ok, "detalle": detalle})

    error_fatal = False
    import html as _html
    rcof_xml_preview = ""
    try:
        # ─── 1. Certificado ───
        cert = obtener_certificado(get_conn, release_conn, tenant_id)
        if not cert.get("ok"):
            paso("Leer certificado .pfx", False, cert.get("error", "?"))
            error_fatal = True
        else:
            paso("Leer certificado .pfx", True, cert["metadata"].get("titular", "?"))

        # ─── 2. Config ───
        if not error_fatal:
            config = obtener_config_facturacion(get_conn, release_conn, tenant_id)
            rut_emisor = config["rut_emisor"]
            rut_envia = cert["metadata"].get("rut", "18849272-K")
            paso("Leer datos del emisor", True, f"{config['razon_social']} · {rut_emisor}")

        # ─── 3. Calcular Resumen tipo 39 (5 boletas) ───
        if not error_fatal:
            from facturacion.dtes.boleta import calcular_totales_boleta
            neto39 = iva39 = exento39 = total39 = 0
            for caso, items in SET_BOLETAS_BE.items():
                t = calcular_totales_boleta(items)
                neto39 += t["mnt_neto"]; iva39 += t["mnt_iva"]
                exento39 += t["mnt_exento"]; total39 += t["mnt_total"]
            paso("Calcular Resumen Boletas (tipo 39)", True,
                 f"neto ${neto39:,} + IVA ${iva39:,} + exento ${exento39:,} = ${total39:,}".replace(",", "."))

        # ─── 5. Construir el Resumen (solo tipo 39: el Set de boletas no lleva NC) ───
        if not error_fatal:
            from facturacion.dtes.rcof import construir_resumen
            # Rango configurable: ?folio_desde=N (debe coincidir con los folios
            # de las boletas que el SII ACEPTÓ). Por defecto 16-20.
            _fd = request.args.get("folio_desde", "").strip()
            _ini = int(_fd) if _fd.isdigit() else 16
            resumen_39 = construir_resumen(
                tipo_documento=39, mnt_neto=neto39, mnt_iva=iva39, mnt_total=total39,
                mnt_exento=exento39, folios_emitidos=5, folios_utilizados=5,
                rangos_utilizados=[{"inicial": _ini, "final": _ini + 4}],
            )
            paso("Construir Resumen RCOF (tipo 39)", True,
                 f"5 boletas · folios {_ini}-{_ini+4}")

        # ─── 6. Generar el RCOF ───
        if not error_fatal:
            from facturacion.dtes.rcof import generar_rcof_xml
            fecha = datetime.now().strftime("%Y-%m-%d")
            res_rcof = generar_rcof_xml(
                rut_emisor=rut_emisor, rut_envia=rut_envia, fecha=fecha,
                resumenes=[resumen_39],
                fch_resol="2026-05-15", nro_resol=0, sec_envio=1,
            )
            paso("Generar RCOF (ConsumoFolios)", True,
                 f"ID {res_rcof['documento_id']} · {len(res_rcof['xml'])} bytes")

        # ─── 7. Firmar el RCOF ───
        if not error_fatal:
            from facturacion.dtes.firma import firmar_envio, verificar_firma_propia
            # El RCOF se firma como un contenedor (igual que el SetDTE): se firma
            # el DocumentoConsumoFolios por su ID, conservando el namespace (quitar_ns=False).
            rcof_firmado = firmar_envio(
                res_rcof["xml"], cert["pfx_bytes"], cert["password"],
                set_dte_id=res_rcof["documento_id"])
            ver = verificar_firma_propia(rcof_firmado)
            paso("Firmar el RCOF (XMLDSig)", ver.get("ok", False),
                 f"{len(rcof_firmado)} bytes · firma {'válida' if ver.get('ok') else 'INVÁLIDA'}")
            if not ver.get("ok"):
                error_fatal = True
            else:
                rcof_xml_preview = _html.escape(rcof_firmado.decode("iso-8859-1"))
                # Modo descarga: devuelve el XML como archivo .xml listo para subir al SII
                if request.args.get("descargar") == "si":
                    from flask import Response
                    nombre = f"RCOF_{res_rcof['documento_id']}.xml"
                    return Response(
                        rcof_firmado,
                        mimetype="application/xml",
                        headers={"Content-Disposition": f'attachment; filename="{nombre}"'},
                    )

    except Exception as e:
        import traceback
        paso("Error", False, _html.escape(traceback.format_exc()[:500]))
        error_fatal = True

    todo_ok = all(p["ok"] for p in pasos)
    color = "#10b981" if todo_ok else "#dc2626"
    emoji = "🎉" if todo_ok else "❌"
    titulo = ("¡RCOF generado y firmado!" if todo_ok else "Problema al generar el RCOF")

    filas = ""
    for p in pasos:
        ic = "✅" if p["ok"] else "❌"
        col = "#10b981" if p["ok"] else "#dc2626"
        filas += f"""
        <div style="display:flex;gap:10px;padding:12px 14px;border-bottom:1px solid #f0f0ee;align-items:flex-start;">
          <div style="font-size:16px;">{ic}</div>
          <div style="flex:1;">
            <div style="font-weight:600;color:#1f1e1b;font-size:13px;">{p['nombre']}</div>
            <div style="color:{col};font-size:12px;margin-top:2px;font-family:monospace;word-break:break-word;">{p['detalle']}</div>
          </div>
        </div>"""

    preview_block = ""
    if rcof_xml_preview:
        tok_param = request.args.get("token", "")
        url_descarga = f"?token={tok_param}&tenant_id={tenant_id}&descargar=si"
        preview_block = f"""
        <div style="padding:14px 24px;">
          <a href="{url_descarga}" style="display:inline-block;margin-bottom:12px;background:#10b981;
          color:white;padding:10px 18px;border-radius:8px;text-decoration:none;font-weight:600;font-size:13px;">
          ⬇ Descargar RCOF.xml (para subir al SII)</a>
          <div style="font-weight:600;font-size:13px;margin-bottom:8px;">XML del RCOF firmado:</div>
          <textarea readonly style="width:100%;height:220px;font-family:monospace;font-size:10px;
          border:1px solid #e5e5e3;border-radius:8px;padding:10px;box-sizing:border-box;">{rcof_xml_preview}</textarea>
        </div>"""

    nota = ("El RCOF está listo. Falta enviarlo al SII (vía upload en certificación) "
            "e informar su TrackID para validar la certificación."
            if todo_ok else "Revisa el paso en rojo.")

    html = f"""<!DOCTYPE html><html lang="es"><head><meta charset="utf-8">
    <title>RCOF · Lusync</title>
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <style>
      body {{ font-family:-apple-system,'Segoe UI',sans-serif; background:#f6f5f1; margin:0; padding:24px; color:#1f1e1b; }}
      .card {{ max-width:760px; margin:0 auto; background:white; border-radius:14px; overflow:hidden; box-shadow:0 4px 20px rgba(0,0,0,0.06); }}
      .header {{ background:{color}; color:white; padding:24px; }}
      .header h1 {{ margin:0; font-size:18px; }}
      .header p {{ margin:6px 0 0; opacity:0.9; font-size:13px; }}
      .footer {{ padding:16px 24px; background:#fafaf9; font-size:12px; color:#6b7280; }}
    </style></head><body>
    <div class="card">
      <div class="header">
        <h1>{emoji} {titulo}</h1>
        <p>RCOF Set BE · 5 boletas + 2 NC · tenant {tenant_id}</p>
      </div>
      <div>{filas}</div>
      {preview_block}
      <div class="footer">{nota}</div>
    </div>
    </body></html>"""
    return html


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=int(os.environ.get("PORT", 10000)))
